/**
 * JARVIS — account lifecycle routes.
 *
 * Deletion is the one destructive operation, so it is deliberately strict:
 * it requires a verified session AND a fresh password confirmation. Data is
 * purged through a single idempotent server-side routine, and the auth row is
 * removed last so nothing is orphaned if an earlier step fails.
 *
 * Onboarding completion lives here too — it flips the flag on the caller's own
 * profile row, guarded by RLS.
 */
import type { Express, Response } from "express";
import { requireAuth, type AuthedRequest, AUTH_ERRORS } from "./authRoutes";
import { supabase, requireAdmin } from "./supabaseClient";
import { deleteAllMemories, memoryConfigured } from "./mem0Service";

export function registerAccountRoutes(app: Express): void {
  // ---- Complete onboarding (marks the caller's own profile) ---------------
  app.post("/api/account/onboarding", requireAuth, async (req: AuthedRequest, res: Response) => {
    const { error } = await supabase
      .from("profiles")
      .update({
        onboarding_completed: true,
        display_name: req.body?.displayName ? String(req.body.displayName).slice(0, 80) : undefined,
      })
      .eq("id", req.userId);
    if (error) return res.status(500).json({ error: "Could not save your setup." });
    res.json({ ok: true });
  });

  // ---- Update display name ------------------------------------------------
  app.post("/api/account/profile", requireAuth, async (req: AuthedRequest, res: Response) => {
    const displayName = req.body?.displayName === null ? null : String(req.body?.displayName || "").slice(0, 80) || null;
    const { error } = await supabase.from("profiles").update({ display_name: displayName }).eq("id", req.userId);
    if (error) return res.status(500).json({ error: "Could not save your profile." });
    res.json({ ok: true });
  });

  // ---- Set the memory preference ------------------------------------------
  app.post("/api/account/memory-enabled", requireAuth, async (req: AuthedRequest, res: Response) => {
    const enabled = req.body?.enabled === true;
    const { error } = await supabase
      .from("user_memory_settings")
      .update({ memory_enabled: enabled })
      .eq("user_id", req.userId);
    if (error) return res.status(500).json({ error: "Could not change the memory setting." });
    res.json({ ok: true, memoryEnabled: enabled });
  });

  // ---- Delete the account -------------------------------------------------
  // Requires re-authentication: the caller supplies their password, which we
  // verify against Supabase before touching anything.
  app.post("/api/account/delete", requireAuth, async (req: AuthedRequest, res: Response) => {
    const password = String(req.body?.password || "");
    const email = req.userEmail;

    if (!password) return res.status(400).json({ error: "Enter your password to confirm deletion." });
    if (!email) return res.status(400).json({ error: "Cannot verify this account." });

    // 1. Re-authenticate. Without this, a hijacked session could delete data.
    const { error: verifyError } = await supabase.auth.signInWithPassword({ email, password });
    if (verifyError) return res.status(401).json({ error: AUTH_ERRORS.invalidCredentials });

    const userId = req.userId!;

    // 2. Disconnect integrations through Composio (best effort; a failure
    //    here must not abort the deletion, only be reported).
    const integrationErrors: string[] = [];
    try {
      const admin = requireAdmin();
      const { data: connections } = await admin
        .from("integration_connections")
        .select("connection_id")
        .eq("user_id", userId);
      if (connections?.length && process.env.COMPOSIO_API_KEY) {
        for (const connection of connections) {
          try {
            await fetch(`${process.env.COMPOSIO_BASE_URL || "https://backend.composio.dev"}/api/v3.1/connections/${connection.connection_id}`, {
              method: "DELETE",
              headers: { "x-api-key": process.env.COMPOSIO_API_KEY },
            });
          } catch {
            integrationErrors.push(connection.connection_id);
          }
        }
      }
    } catch {
      /* Composio unavailable — continue with deletion */
    }

    // 3. Delete the user's local memories (best effort; failure does not abort deletion).
    const mem0UserId = `jarvis_user_${userId}`;
    let memoryDeleted = true;
    if (await memoryConfigured(mem0UserId)) {
      try {
        await deleteAllMemories(mem0UserId);
      } catch (error) {
        // Report honestly — never claim a deletion that failed.
        memoryDeleted = error instanceof Error ? false : true;
      }
    }

    // 4. Purge all user-owned application data, then remove the auth row last.
    //    The FK cascade removes anything the purge missed.
    const admin = requireAdmin();
    const { error: purgeError } = await admin.rpc("purge_user_data", { p_user_id: userId });
    if (purgeError) {
      return res.status(500).json({ error: "Account cleanup failed. Your data is intact — please try again." });
    }

    const { error: authError } = await admin.auth.admin.deleteUser(userId);
    if (authError) {
      return res.status(500).json({ error: "Account removal failed. Please contact support." });
    }

    res.json({
      ok: true,
      warnings: integrationErrors.length ? `${integrationErrors.length} integration(s) could not be disconnected.` : undefined,
      memoryDeleted,
    });
  });
}