export async function providerFetch(url:string, init:RequestInit={}, timeoutMs=15000):Promise<Response>{
  const controller=new AbortController();
  const timer=setTimeout(()=>controller.abort(),timeoutMs); timer.unref?.();
  const signal=init.signal;
  const onAbort=()=>controller.abort();
  signal?.addEventListener("abort",onAbort,{once:true});
  try { return await fetch(url,{...init,signal:controller.signal}); }
  finally { clearTimeout(timer); signal?.removeEventListener("abort",onAbort); }
}
export function safeProviderError(error:unknown):string{
  if(error instanceof DOMException && error.name==="AbortError") return "Provider request timed out.";
  return error instanceof Error ? error.message.slice(0,300) : "Provider request failed.";
}
