/**
 * JARVIS — personal workspace initialization.
 *
 * Called once after a verified sign-up (and defensively on sign-in) to make
 * sure the user's logical resources exist. Every step is idempotent: a
 * retried or interrupted registration must not create duplicate profiles or
 * memory identities.
 *
 * Prefers the service-role client when the instance has it configured; falls
 * back to the caller's own verified token (RLS "own row" policies) so the
 * distributed desktop build — which never ships the service-role key — still
 * initializes. Either way it only ever acts on the id resolved from a verified
 * session, never a client-supplied one.
 */
import { createClient, type SupabaseClient } from "@supabase/supabase-js";
import { getAdmin } from "./supabaseClient";

export interface WorkspaceInitResult {
  profileId: string;
  mem0UserId: string;
  memoryEnabled: boolean;
  /** True only when resources were actually created this call. */
  created: boolean;
}

/**
 * Pick the client used to initialize a workspace.
 *
 *  - Trusted server build: the service-role client (works before RLS session).
 *  - Distributed desktop build (no service role key shipped): a client scoped
 *    to the user's OWN verified token, so the RLS policies for "own row" apply.
 *    This is exactly as safe: the policies only allow auth.uid() = user_id.
 */
async function workspaceClient(accessToken?: string): Promise<SupabaseClient> {
  const admin = await getAdmin();
  if (admin) return admin;

  const url = process.env.SUPABASE_URL || "";
  const anonKey = process.env.SUPABASE_ANON_KEY || "";
  if (!url || !anonKey || !accessToken) {
    throw new Error("Supabase service role is not configured and no user token is available.");
  }
  return createClient(url, anonKey, {
    auth: { persistSession: false, autoRefreshToken: false },
    global: { headers: { Authorization: `Bearer ${accessToken}` } },
  });
}

/**
 * Initialize a user's JARVIS workspace: profile, local memory identity mapping, and
 * default preferences. Safe to call repeatedly.
 *
 * @param accessToken the user's verified access token; used to run the
 *   initialization through RLS when no service role key is configured.
 */
export async function initializeWorkspace(userId: string, accessToken?: string): Promise<WorkspaceInitResult> {
  const admin = await workspaceClient(accessToken);
  let created = false;

  // 1. Profile — upsert; the auth trigger usually beats us to it.
  const { data: existingProfile } = await admin
    .from("profiles")
    .select("id")
    .eq("id", userId)
    .maybeSingle();

  if (!existingProfile) {
    await admin.from("profiles").insert({ id: userId });
    created = true;
  }

  // 2. Stable local memory identity mapping, server-assigned.
  //    For local (single-user) installs, use the fixed LOCAL_SCOPE_ID.
  //    For multi-user Supabase installs, derive a deterministic identity from the auth UUID.
  const mem0UserId = /* Supabase multi-user: */ `jarvis_user_${userId}`;
  const { data: memoryRow } = await admin
    .from("user_memory_settings")
    .select("memory_enabled")
    .eq("user_id", userId)
    .maybeSingle();

  if (!memoryRow) {
    await admin.from("user_memory_settings").insert({
      user_id: userId,
      mem0_user_id: mem0UserId,
      memory_enabled: true,
    });
    created = true;
  }

  // 3. Default preferences (validated, non-sensitive JSONB).
  const { data: prefs } = await admin
    .from("user_preferences")
    .select("user_id")
    .eq("user_id", userId)
    .maybeSingle();

  if (!prefs) {
    await admin.from("user_preferences").insert({
      user_id: userId,
      preferences: {
        responseStyle: "balanced",
        language: "en",
        formatting: "concise",
      },
    });
    created = true;
  }

  return {
    profileId: userId,
    mem0UserId,
    memoryEnabled: memoryRow?.memory_enabled ?? true,
    created,
  };
}