/**
 * The PC's outbound connection to the EVA relay.
 *
 * The PC is always the CONNECTOR: it dials the relay with a host token and
 * keeps a single WebSocket open. Nothing ever connects inbound to the PC —
 * phones reach this computer only through the relay's room routing.
 *
 * Responsibilities:
 *   - connect (or reconnect with capped exponential backoff) to cfg.relayUrl;
 *   - send `host.hello {rooms}` so the relay routes envelopes for the users
 *     this PC actually has pairings for; refresh rooms every 30s so a pairing
 *     made after boot starts routing without a restart;
 *   - hand every inbound envelope (already `from`-stamped by the relay) to
 *     the gateway callback;
 *   - expose `send()` for PC -> phone envelopes.
 */
import WebSocket from "ws";
import { createLogger } from "../shared/logger";

const log = createLogger("remote.relay");

const ROOM_REFRESH_MS = 30_000;
const MIN_BACKOFF_MS = 1_000;
const MAX_BACKOFF_MS = 60_000;

export interface RelayConnectorDeps {
  relayUrl: string;
  hostToken: string;
  /** User ids whose devices this PC serves (rooms to bind). */
  rooms: () => Promise<string[]>;
  onEnvelope: (raw: string) => void;
  onStatus?: (connected: boolean) => void;
}

export class RelayConnector {
  private ws: WebSocket | null = null;
  private stopped = false;
  private backoffMs = MIN_BACKOFF_MS;
  private reconnectTimer: NodeJS.Timeout | null = null;
  private roomTimer: NodeJS.Timeout | null = null;

  constructor(private readonly deps: RelayConnectorDeps) {}

  start(): void {
    this.stopped = false;
    this.connect();
  }

  stop(): void {
    this.stopped = true;
    if (this.reconnectTimer) clearTimeout(this.reconnectTimer);
    if (this.roomTimer) clearInterval(this.roomTimer);
    this.reconnectTimer = null;
    this.roomTimer = null;
    const ws = this.ws;
    this.ws = null;
    if (ws) {
      try {
        ws.close(1001, "shutdown");
      } catch {
        /* already gone */
      }
    }
  }

  get connected(): boolean {
    return this.ws !== null && this.ws.readyState === WebSocket.OPEN;
  }

  /**
   * Re-send `host.hello` immediately (instead of waiting up to 30s for the
   * periodic refresh). Called when a pairing starts, so the relay can route
   * the phone's claim to this PC right away.
   */
  refreshRooms(): void {
    void this.sendHello();
  }

  send(envelope: unknown): boolean {
    if (!this.connected) return false;
    try {
      this.ws!.send(JSON.stringify(envelope));
      return true;
    } catch (error) {
      log.warn("relay send failed", { error: error instanceof Error ? error.message : String(error) });
      return false;
    }
  }

  private connect(): void {
    if (this.stopped) return;
    const url = new URL(this.deps.relayUrl);
    const subprotocol = `eva-relay.v1|${this.deps.hostToken}`;

    let ws: WebSocket;
    try {
      ws = new WebSocket(url, subprotocol, { handshakeTimeout: 10_000 });
    } catch (error) {
      log.error("relay dial failed", { error: error instanceof Error ? error.message : String(error) });
      this.scheduleReconnect();
      return;
    }
    this.ws = ws;

    ws.on("open", () => {
      log.info("connected to relay", { url: this.deps.relayUrl });
      this.backoffMs = MIN_BACKOFF_MS;
      this.deps.onStatus?.(true);
      void this.sendHello();
      if (this.roomTimer) clearInterval(this.roomTimer);
      this.roomTimer = setInterval(() => void this.sendHello(), ROOM_REFRESH_MS);
      this.roomTimer.unref?.();
    });

    ws.on("message", (data) => {
      if (typeof data !== "string" && !Buffer.isBuffer(data)) return;
      this.deps.onEnvelope(data.toString());
    });

    ws.on("close", (code, reason) => {
      log.warn("relay closed", { code, reason: reason?.toString() });
      this.teardown(ws);
    });

    ws.on("error", (error) => {
      log.warn("relay error", { error: error.message });
      try {
        ws.close();
      } catch {
        /* already gone */
      }
    });
  }

  private teardown(ws: WebSocket): void {
    if (this.ws === ws) {
      this.ws = null;
      this.deps.onStatus?.(false);
      if (this.roomTimer) clearInterval(this.roomTimer);
      this.roomTimer = null;
      this.scheduleReconnect();
    }
  }

  private scheduleReconnect(): void {
    if (this.stopped || this.reconnectTimer) return;
    this.reconnectTimer = setTimeout(() => {
      this.reconnectTimer = null;
      this.connect();
    }, this.backoffMs);
    this.reconnectTimer.unref?.();
    this.backoffMs = Math.min(this.backoffMs * 2, MAX_BACKOFF_MS);
  }

  private async sendHello(): Promise<void> {
    if (!this.connected) return;
    try {
      const rooms = await this.deps.rooms();
      this.send({
        v: 1,
        id: `host-hello-${Date.now()}`,
        from: "pc",
        to: "relay",
        kind: "host.hello",
        seq: 1,
        ts: Date.now(),
        payload: { rooms },
      });
    } catch (error) {
      log.warn("could not refresh relay rooms", { error: error instanceof Error ? error.message : String(error) });
    }
  }
}
