/**
 * EVA — Composio app bridge.
 *
 * The Integrations panel could list and connect apps, but no Composio tool
 * was ever exposed to the model: `server.ts` declared only the live-voice and
 * desktop tools, so a connected app gave Eva nothing she could call. This
 * module is the missing link — it resolves the signed-in user's own
 * connections, discovers the actions each connected app actually exposes, and
 * executes one of them.
 *
 * Design rules:
 *   * The caller is always identified by the VERIFIED user id that the
 *     backend resolved from the session. A provider or connection id that
 *     arrives from the model is never trusted on its own.
 *   * Discovery is dynamic: the action list comes from Composio for the
 *     connected toolkit, not from a hard-coded table that could drift.
 *   * Failures are reported as failures. Nothing here claims an action
 *     succeeded unless Composio returned a successful response.
 */
import { getAdmin } from "./supabaseClient";

export interface ConnectedApp {
  provider: string;
  status: string;
  connectionId: string;
}

export interface AppAction {
  /**
   * The Composio tool SLUG, for example GMAIL_SEND_EMAIL. This is the
   * identifier the execute endpoint expects — NOT the display name.
   */
  slug: string;
  /** Human-readable name, e.g. "Create email draft". */
  label: string;
  description: string;
  /** Parameter hints taken from the tool's JSON schema. */
  parameters: Array<{ name: string; type: string; required: boolean; description?: string }>;
  noAuth: boolean;
}

export interface ComposioCallResult {
  ok: boolean;
  /** Human-readable outcome for the model to relay. */
  summary: string;
  data?: unknown;
  error?: string;
}

function composioBaseUrl(): string {
  return process.env.COMPOSIO_BASE_URL || "https://backend.composio.dev";
}

function composioHeaders(): Record<string, string> {
  return {
    "x-api-key": (process.env.COMPOSIO_API_KEY || "").trim(),
    "Content-Type": "application/json",
  };
}

/**
 * Stable per-user identity inside Composio.
 *
 * Composio v3's execute endpoint needs BOTH the connected account id and the
 * user id the connection was created under. This is the single source of
 * truth for that id: the connection flow creates the account with it, and
 * the execution path must send exactly the same value.
 */
export function composioEntityId(userId: string): string {
  return `jarvis_user_${userId}`;
}

export function isComposioConfigured(): boolean {
  return (process.env.COMPOSIO_API_KEY || "").trim().length > 0;
}

/**
 * The apps that are available to connect, with whether this user has them.
 *
 * Eva needs to know both halves: what is already connected (she can call it
 * right now) and what exists but is not connected (the user must authorise it
 * first). Without the second half she can only ever talk about apps that are
 * already linked.
 */
export async function listAvailableApps(
  userId: string,
  limit = 40,
): Promise<Array<{ app: string; name: string; connected: boolean; status: string }>> {
  const connected = await listConnectedApps(userId);
  const byProvider = new Map(connected.map((a) => [a.provider.toLowerCase(), a]));

  let toolkits: any[] = [];
  try {
    const res = await fetch(
      `${composioBaseUrl()}/api/v3/toolkits?limit=200`,
      { headers: composioHeaders(), cache: "no-store" },
    );
    if (res.ok) {
      const data = await res.json();
      toolkits = Array.isArray(data?.items) ? data.items : [];
    }
  } catch {
    // The catalogue is a nice-to-have; the connected list is what matters.
  }

  const rows = toolkits
    .map((t: any) => ({
      app: String(t?.slug || "").trim().toLowerCase(),
      name: String(t?.name || t?.slug || ""),
    }))
    .filter((t: { app: string }) => Boolean(t.app))
    .slice(0, limit);

  return rows.map((t) => {
    const own = byProvider.get(t.app);
    return {
      app: t.app,
      name: t.name,
      connected: own?.status === "connected",
      status: own?.status ?? "not_connected",
    };
  });
}

/**
 * Every app this user has connected, with the live Composio connection id.
 *
 * The service role is used here because the model-facing path must not depend
 * on the caller's RLS scope, but the query is still filtered to this exact
 * user id — no other account's connections are ever visible.
 */
export async function listConnectedApps(userId: string): Promise<ConnectedApp[]> {
  const admin = await getAdmin();
  if (!admin) return [];
  const { data, error } = await admin
    .from("integration_connections")
    .select("provider, status, connection_id")
    .eq("user_id", userId);
  if (error) throw new Error(error.message);
  return (data ?? [])
    .filter((row: any) => typeof row?.provider === "string" && row.provider)
    .map((row: any) => ({
      provider: String(row.provider),
      status: String(row.status || "unknown"),
      connectionId: String(row.connection_id || ""),
    }));
}

/**
 * The actions a connected app actually exposes.
 *
 * Composio returns the toolkit's tool list; the result is trimmed to the
 * fields a model needs to choose and fill an action, so the context stays
 * small even for a toolkit with a hundred actions.
 */
export async function listAppActions(provider: string): Promise<AppAction[]> {
  if (!isComposioConfigured()) throw new Error("Composio is not configured.");
  const slug = provider.trim().toLowerCase();
  const res = await fetch(
    `${composioBaseUrl()}/api/v3/tools?toolkit_slug=${encodeURIComponent(slug)}&limit=200`,
    { headers: composioHeaders(), cache: "no-store" },
  );
  if (!res.ok) throw new Error(`Could not list actions for ${provider} (HTTP ${res.status}).`);
  const body = await res.json().catch(() => ({}));
  const items = Array.isArray(body?.items) ? body.items : [];
  return items
    .map((tool: any) => {
      // Composio returns `input_parameters` as a JSON Schema OBJECT:
      //   { type, title, required: [...], properties: { name: {...} } }
      // The property value itself is the schema for one parameter.
      const schema = tool?.input_parameters;
      const properties = schema && typeof schema === "object" && !Array.isArray(schema)
        ? schema.properties
        : null;
      const required = schema && typeof schema === "object" && Array.isArray(schema.required)
        ? new Set(schema.required.map((r: unknown) => String(r)))
        : new Set<string>();
      const parameters = properties && typeof properties === "object"
        ? Object.entries(properties).map(([name, raw]) => {
            const p = (raw ?? {}) as Record<string, unknown>;
            const type = Array.isArray(p.type) ? String(p.type[0]) : String(p.type || "string");
            return {
              name,
              type,
              required: required.has(name),
              description: typeof p.description === "string" ? p.description.slice(0, 200) : undefined,
            };
          })
        : [];
      return {
        slug: String(tool?.slug || ""),
        label: String(tool?.name || tool?.slug || ""),
        description: String(tool?.description || tool?.human_description || "").slice(0, 400),
        parameters,
        noAuth: Boolean(tool?.no_auth),
      };
    })
    .filter((action: AppAction) => Boolean(action.slug));
}

/**
 * Execute one action in a connected app, on behalf of this user.
 *
 * The connection is resolved from the user's OWN stored connection, so a
 * model-supplied connection id can never be used to act on another account.
 */
export async function executeAppAction(
  userId: string,
  provider: string,
  tool: string,
  args: Record<string, unknown>,
): Promise<ComposioCallResult> {
  if (!isComposioConfigured()) {
    return { ok: false, summary: "Integrations are not configured on this instance.", error: "composio_not_configured" };
  }
  const admin = await getAdmin();
  if (!admin) {
    return { ok: false, summary: "This instance cannot reach the integrations service.", error: "no_admin_client" };
  }

  const slug = provider.trim().toLowerCase();
  const { data: connection, error: connError } = await admin
    .from("integration_connections")
    .select("connection_id, status")
    .eq("user_id", userId)
    .eq("provider", slug)
    .maybeSingle();
  if (connError) {
    return { ok: false, summary: `Could not read the ${slug} connection.`, error: connError.message };
  }
  if (!connection) {
    return {
      ok: false,
      summary: `You have not connected ${slug} yet. Ask the user to connect it from Settings → Integrations first.`,
      error: "not_connected",
    };
  }
  if (String(connection.status || "") !== "connected") {
    return {
      ok: false,
      summary: `The ${slug} connection is ${connection.status}, not active. Ask the user to reconnect it.`,
      error: "not_active",
    };
  }

  try {
    const res = await fetch(
      `${composioBaseUrl()}/api/v3/tools/execute/${encodeURIComponent(tool)}`,
      {
        method: "POST",
        headers: composioHeaders(),
        body: JSON.stringify({
          connected_account_id: connection.connection_id,
          // Composio v3 rejects the call without the user id the connection
          // was created under: "User ID is required with connected account."
          user_id: composioEntityId(userId),
          arguments: args ?? {},
        }),
        cache: "no-store",
      },
    );
    const text = await res.text().catch(() => "");
    if (!res.ok) {
      let detail = text.slice(0, 300);
      try {
        const parsed = JSON.parse(text);
        detail = parsed?.error?.message || parsed?.message || parsed?.error || detail;
        if (typeof detail !== "string") detail = JSON.stringify(detail).slice(0, 300);
      } catch {
        /* not JSON — keep the raw text */
      }
      return {
        ok: false,
        summary: `${slug} could not complete "${tool}". ${detail}`.slice(0, 400),
        error: `http_${res.status}`,
      };
    }
    let data: unknown = text;
    try { data = JSON.parse(text); } catch { /* keep the raw body */ }
    return {
      ok: true,
      summary: `${slug} completed "${tool}".`,
      data,
    };
  } catch (error) {
    return {
      ok: false,
      summary: `${slug} is not responding right now.`,
      error: error instanceof Error ? error.message : String(error),
    };
  }
}
