import "dotenv/config";
export interface EvaProviderSettings {
  GEMINI_API_KEY?: string;
  ATRIA_DAWN_API_KEY?: string;
  COMPOSIO_API_KEY?: string;
  ATRIA_DAWN_BASE_URL: string;
  COMPOSIO_BASE_URL: string;
  PROVIDER_TIMEOUT_MS: number;
}
export const providerSettings: EvaProviderSettings = {
  GEMINI_API_KEY: process.env.GEMINI_API_KEY?.trim() || undefined,
  ATRIA_DAWN_API_KEY: process.env.ATRIA_DAWN_API_KEY?.trim() || undefined,
  COMPOSIO_API_KEY: process.env.COMPOSIO_API_KEY?.trim() || undefined,
  ATRIA_DAWN_BASE_URL: process.env.ATRIA_DAWN_BASE_URL?.trim() || "https://api.atria.ai",
  COMPOSIO_BASE_URL: process.env.COMPOSIO_BASE_URL?.trim() || "https://backend.composio.dev",
  PROVIDER_TIMEOUT_MS: Math.max(1000, Number(process.env.PROVIDER_TIMEOUT_MS) || 15000),
};
export function configuredProviderKeys() {
  return {
    gemini: Boolean(providerSettings.GEMINI_API_KEY),
    atria: Boolean(providerSettings.ATRIA_DAWN_API_KEY),
    composio: Boolean(providerSettings.COMPOSIO_API_KEY),
  };
}