/**
 * Lightweight resource-lock / lease manager for concurrent task coordination.
 *
 * Prevents conflicting access to shared resources (desktop UI, files, browser
 * sessions) while allowing independent read-only work to proceed in parallel.
 */
export interface Lease {
  id: string;
  resource: string;
  owner: string;
  expiresAt: number;
}

export class ResourceLockManager {
  private readonly leases = new Map<string, Lease>();

  acquire(resource: string, owner: string, ttlMs = 30_000): Lease | null {
    this.gc();
    const existing = this.leases.get(resource);
    if (existing && existing.expiresAt > Date.now() && existing.owner !== owner) return null;
    const lease: Lease = { id: `${resource}:${owner}:${Date.now()}`, resource, owner, expiresAt: Date.now() + ttlMs };
    this.leases.set(resource, lease);
    return lease;
  }

  release(resource: string, owner: string): boolean {
    const existing = this.leases.get(resource);
    if (!existing || existing.owner !== owner) return false;
    this.leases.delete(resource);
    return true;
  }

  isLocked(resource: string): boolean {
    this.gc();
    const l = this.leases.get(resource);
    return !!l && l.expiresAt > Date.now();
  }

  ownerOf(resource: string): string | null {
    this.gc();
    const l = this.leases.get(resource);
    return l && l.expiresAt > Date.now() ? l.owner : null;
  }

  private gc(): void {
    const now = Date.now();
    for (const [r, l] of this.leases) if (l.expiresAt <= now) this.leases.delete(r);
  }
}