import { providerSettings } from "../config";
import { providerFetch, safeProviderError } from "../http";
import type { CodingProvider, ProviderHealth } from "../types";

export class AtriaDawnProvider implements CodingProvider {
  id="atria-dawn"; name="Atria Dawn";
  async health():Promise<ProviderHealth>{
    return {id:this.id,name:this.name,status:providerSettings.ATRIA_DAWN_API_KEY ? "configured":"unconfigured"};
  }
  async execute(input: unknown, signal?: AbortSignal):Promise<unknown>{
    if(!providerSettings.ATRIA_DAWN_API_KEY) throw new Error("Atria Dawn is not configured.");
    const body = typeof input==="object" && input!==null ? input as Record<string,unknown> : {messages:[{role:"user",content:String(input)}]};
    const response=await providerFetch(`${providerSettings.ATRIA_DAWN_BASE_URL}/v1/chat/completions`,{
      method:"POST", headers:{"Authorization":`Bearer ${providerSettings.ATRIA_DAWN_API_KEY}`,"Content-Type":"application/json"},
      body:JSON.stringify({model:"Atria-Dawn-Preview",...body}), signal
    },providerSettings.PROVIDER_TIMEOUT_MS);
    if(!response.ok) throw new Error(`Atria Dawn request failed (${response.status}).`);
    return response.json();
  }
  async generate(input:unknown,signal?:AbortSignal){return this.execute(input,signal)}
}
