/**
 * Remote-control wire protocol.
 *
 * One envelope shape travels phone → relay → PC (and back). The relay only
 * understands `to`/`kind` for routing; the PC gateway validates `kind` and
 * `payload` fully. Every message carries an id (idempotency), a monotonic
 * per-sender sequence (reconnect resume / replay rejection) and a timestamp
 * (replay-window check).
 *
 * Payload validation is deliberately strict: unknown kinds are rejected, all
 * numbers are range-checked, and nothing is passed through to tools without
 * the gateway's own parsing (see remote/gateway.ts).
 */

export const ENVELOPE_VERSION = 1;

/** Kinds the PC gateway accepts from a paired client (phone → PC). */
export const CLIENT_TO_PC_KINDS = [
  "hello",
  "ping",
  "pairing.claim",
  "task.create",
  "task.action",
  "approval.resolve",
  "stream.start",
  "stream.stop",
  "stream.input",
  "file.list",
  "file.read",
  "file.write",
  "file.upload",
  "file.download",
  "app.list",
  "app.launch",
  "app.close",
  "session.open",
  "session.close",
  "session.refresh",
] as const;

/** Kinds the gateway may send to a paired client (PC → phone). */
export const PC_TO_CLIENT_KINDS = [
  "hello.ack",
  "pong",
  "error",
  "device.status",
  "pairing.status",
  "pairing.approved",
  "pairing.denied",
  "task.snapshot",
  "task.progress",
  "task.finished",
  "chat.message",
  "chat.done",
  "approval.requested",
  "approval.resolved",
  "stream.frame",
  "stream.stats",
  "stream.stopped",
  "file.entries",
  "file.data",
  "app.entries",
  "notification",
  "session.state",
  "session.updated",
] as const;

export type ClientToPcKind = (typeof CLIENT_TO_PC_KINDS)[number];
export type PcToClientKind = (typeof PC_TO_CLIENT_KINDS)[number];

export interface Envelope<T = unknown> {
  v: number;
  /** Unique message id — the receiver treats duplicates as no-ops. */
  id: string;
  /** Sender device id. */
  from: string;
  /** Recipient device id, or "*" for broadcast to the user's PC. */
  to: string;
  kind: string;
  /** Per-sender monotonic sequence, starting at 1. */
  seq: number;
  /** Sender timestamp (ms). */
  ts: number;
  /** Optional correlation id: replies reference the request's id. */
  ref?: string;
  payload: T;
}

export type HelloPayload = {
  protocolVersion: number;
  userAgent: string;
}

export type PairingClaimPayload = {
  token: string;
  deviceName: string;
  platform?: string;
  /** Supabase access token of the signed-in phone (ownership proof). */
  sessionToken?: string;
}

export type TaskCreatePayload = {
  command: string;
  /** Client-generated idempotency key; replayed requests return the same task. */
  key: string;
}

export type TaskActionPayload = {
  taskId: string;
  action: "stop" | "pause" | "resume" | "answer" | "continue";
  text?: string;
}

export type ApprovalResolvePayload = {
  confirmationId: string;
  approved: boolean;
  remember?: "once" | "session";
}

export type StreamInputPayload = {
  type: "move" | "down" | "up" | "wheel" | "key" | "text";
  /** Normalized 0..1 viewport coordinates (move/down/up). */
  x?: number;
  y?: number;
  button?: number;
  deltaX?: number;
  deltaY?: number;
  /** key: {key, ctrl, alt, shift, meta}; text: raw string. */
  key?: string;
  ctrl?: boolean;
  alt?: boolean;
  shift?: boolean;
  meta?: boolean;
  text?: string;
}

export type FileQueryPayload = {
  root?: string;
  /** Path relative to the resolved root; "" is the root itself. */
  path?: string;
}

export type FileWritePayload = FileQueryPayload & {
  content?: string;
}

export type FileDownloadPayload = FileQueryPayload & {
  transferId: string;
}

export type AppLaunchPayload = {
  application: string;
  /** Optional arguments when the launcher accepts them. */
  args?: string[];
}

const MAX_TEXT = 8_000;
const MAX_PATH = 1_024;
const MAX_KEY = 64;

export class ProtocolError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "ProtocolError";
  }
}

function requireObject(value: unknown): Record<string, unknown> {
  if (!value || typeof value !== "object" || Array.isArray(value)) throw new ProtocolError("payload must be an object");
  return value as Record<string, unknown>;
}

function str(value: unknown, field: string, max: number): string {
  if (typeof value !== "string" || !value.trim()) throw new ProtocolError(`${field} must be a non-empty string`);
  if (value.length > max) throw new ProtocolError(`${field} exceeds ${max} characters`);
  return value;
}

function optStr(value: unknown, field: string, max: number): string | undefined {
  if (value === undefined || value === null) return undefined;
  return str(value, field, max);
}

function num(value: unknown, field: string, min: number, max: number): number {
  if (typeof value !== "number" || !Number.isFinite(value)) throw new ProtocolError(`${field} must be a finite number`);
  if (value < min || value > max) throw new ProtocolError(`${field} out of range`);
  return value;
}

function optBool(value: unknown, field: string): boolean | undefined {
  if (value === undefined || value === null) return undefined;
  if (typeof value !== "boolean") throw new ProtocolError(`${field} must be a boolean`);
  return value;
}

/** Parse and validate a raw envelope received by the gateway or the relay. */
export function parseEnvelope(raw: unknown): Envelope {
  const text = typeof raw === "string" ? raw : Buffer.isBuffer(raw) ? raw.toString("utf-8") : null;
  if (text === null) throw new ProtocolError("message must be text");
  // Frames can be large (JPEG base64) but never unbounded.
  if (text.length > 6 * 1024 * 1024) throw new ProtocolError("message too large");

  let parsed: unknown;
  try {
    parsed = JSON.parse(text);
  } catch {
    throw new ProtocolError("message is not valid JSON");
  }
  const env = requireObject(parsed);

  if (env.v !== ENVELOPE_VERSION) throw new ProtocolError("unsupported protocol version");
  const id = str(env.id, "id", 64);
  const from = str(env.from, "from", 64);
  const to = str(env.to, "to", 64);
  const kind = str(env.kind, "kind", 48);
  const seq = Math.floor(num(env.seq, "seq", 1, Number.MAX_SAFE_INTEGER));
  const ts = Math.floor(num(env.ts, "ts", 0, Number.MAX_SAFE_INTEGER));

  const envelope: Envelope = { v: ENVELOPE_VERSION, id, from, to, kind, seq, ts, payload: env.payload ?? {} };
  if (env.ref !== undefined) envelope.ref = optStr(env.ref, "ref", 64);
  return envelope;
}

/** Validate + narrow a payload by message kind. Throws ProtocolError. */
export function validatePayload(kind: string, raw: unknown): Record<string, unknown> {
  const payload = requireObject(raw);
  switch (kind) {
    case "hello":
      return {
        protocolVersion: Math.floor(num(payload.protocolVersion, "protocolVersion", 1, 100)),
        userAgent: optStr(payload.userAgent, "userAgent", 256) || "unknown",
      } satisfies HelloPayload;
    case "ping":
      return {};
    case "pairing.claim": {
      const out: PairingClaimPayload = {
        token: str(payload.token, "token", 4096),
        deviceName: optStr(payload.deviceName, "deviceName", 120) || "Unknown device",
      };
      const platform = optStr(payload.platform, "platform", 120);
      if (platform !== undefined) out.platform = platform;
      const sessionToken = optStr(payload.sessionToken, "sessionToken", 4096);
      if (sessionToken !== undefined) out.sessionToken = sessionToken;
      return out;
    }
    case "task.create":
      return {
        command: str(payload.command, "command", MAX_TEXT),
        key: str(payload.key, "key", 64),
      } satisfies TaskCreatePayload;
    case "task.action": {
      const action = str(payload.action, "action", 16);
      if (!["stop", "pause", "resume", "answer", "continue"].includes(action)) {
        throw new ProtocolError("unknown task action");
      }
      const out: TaskActionPayload = { taskId: str(payload.taskId, "taskId", 64), action: action as TaskActionPayload["action"] };
      const text = optStr(payload.text, "text", MAX_TEXT);
      if (text !== undefined) out.text = text;
      return out;
    }
    case "approval.resolve": {
      const out: ApprovalResolvePayload = {
        confirmationId: str(payload.confirmationId, "confirmationId", 64),
        approved: payload.approved === true,
      };
      if (payload.remember === "once" || payload.remember === "session") out.remember = payload.remember;
      return out;
    }
    case "stream.start": {
      const out: Record<string, unknown> = {};
      if (payload.fps !== undefined) out.fps = Math.floor(num(payload.fps, "fps", 1, 30));
      if (payload.quality !== undefined) out.quality = Math.floor(num(payload.quality, "quality", 20, 90));
      return out;
    }
    case "stream.stop":
      return {};
    case "stream.input": {
      const type = str(payload.type, "type", 8);
      if (!["move", "down", "up", "wheel", "key", "text"].includes(type)) throw new ProtocolError("unknown input type");
      const out: StreamInputPayload = { type: type as StreamInputPayload["type"] };
      if (type !== "key" && type !== "text") {
        out.x = num(payload.x, "x", -1, 2);
        out.y = num(payload.y, "y", -1, 2);
      }
      if (payload.button !== undefined) out.button = Math.floor(num(payload.button, "button", 0, 4));
      if (type === "wheel") {
        out.deltaX = num(payload.deltaX ?? 0, "deltaX", -10_000, 10_000);
        out.deltaY = num(payload.deltaY ?? 0, "deltaY", -10_000, 10_000);
      }
      if (type === "key") {
        out.key = str(payload.key, "key", MAX_KEY);
        out.ctrl = optBool(payload.ctrl, "ctrl");
        out.alt = optBool(payload.alt, "alt");
        out.shift = optBool(payload.shift, "shift");
        out.meta = optBool(payload.meta, "meta");
      }
      if (type === "text") out.text = str(payload.text, "text", MAX_TEXT);
      return out;
    }
    case "file.list":
    case "file.read": {
      const out: FileQueryPayload = {};
      const root = optStr(payload.root, "root", MAX_PATH);
      const rel = optStr(payload.path, "path", MAX_PATH);
      if (root !== undefined) out.root = root;
      if (rel !== undefined) out.path = rel;
      return out;
    }
    case "file.write": {
      const out: FileWritePayload = {};
      const root = optStr(payload.root, "root", MAX_PATH);
      const rel = optStr(payload.path, "path", MAX_PATH);
      if (root !== undefined) out.root = root;
      if (rel !== undefined) out.path = rel;
      const content = payload.content;
      if (content !== undefined) {
        if (typeof content !== "string") throw new ProtocolError("content must be a string");
        if (content.length > 2 * 1024 * 1024) throw new ProtocolError("content exceeds 2MB; use file.upload");
        out.content = content;
      }
      return out;
    }
    case "file.download": {
      const out: FileDownloadPayload = { transferId: str(payload.transferId, "transferId", 64) };
      const root = optStr(payload.root, "root", MAX_PATH);
      const rel = optStr(payload.path, "path", MAX_PATH);
      if (root !== undefined) out.root = root;
      if (rel !== undefined) out.path = rel;
      return out;
    }
    case "file.upload": {
      const out: Record<string, unknown> = {
        transferId: str(payload.transferId, "transferId", 64),
        path: str(payload.path, "path", MAX_PATH),
        name: str(payload.name, "name", 255),
        chunk: Math.floor(num(payload.chunk, "chunk", 0, 1_000_000)),
        chunks: Math.floor(num(payload.chunks, "chunks", 1, 1_000_000)),
        data: str(payload.data, "data", 4 * 1024 * 1024),
      };
      const root = optStr(payload.root, "root", MAX_PATH);
      if (root !== undefined) out.root = root;
      if (out.chunk > out.chunks) throw new ProtocolError("chunk out of range");
      return out;
    }
    case "app.list":
      return {};
    case "app.launch":
      return { application: str(payload.application, "application", 260) };
    case "app.close":
      return { application: str(payload.application, "application", 260) };
    case "session.open":
      return { capability: str(payload.capability, "capability", 32) };
    case "session.close":
      return { capability: str(payload.capability, "capability", 32) };
    case "session.refresh":
      // The device's refresh credential; verified against the store by the
      // gateway before any new access token is issued.
      return { refresh: str(payload.refresh, "refresh", 4096) };
    default:
      throw new ProtocolError(`unknown message kind "${kind}"`);
  }
}

export function makeEnvelope(to: string, kind: string, payload: unknown, from: string, seq: number, ref?: string): Envelope {
  const envelope: Envelope = {
    v: ENVELOPE_VERSION,
    id: `${from}-${seq}-${Math.random().toString(36).slice(2, 10)}`,
    from,
    to,
    kind,
    seq,
    ts: Date.now(),
    payload,
  };
  if (ref) envelope.ref = ref;
  return envelope;
}
