const CAMERA_QUESTION_PATTERNS: RegExp[] = [
  /\bwhat\s+am\s+i\s+holding\b/i,
  /\bwhat(?:'s| is)\s+on\s+my\s+(?:desk|table|hand)\b/i,
  /\b(?:read|describe|analy[sz]e|inspect)\b[^.?!]{0,60}\b(?:this|that|page|paper|document|image|camera|webcam|here|what\s+you\s+see)\b/i,
  /\b(?:what|who)\s+(?:can|do)\s+you\s+see\b/i,
  /\bcan\s+you\s+see\s+(?:me|what\s+i(?:'m| am)\s+holding)\b/i,
  /\b(?:is|are)\s+(?:my\s+)?(?:laptop|computer|phone|monitor|screen|desk|hands?)\b[^.?!]{0,35}\b(?:visible|in view|showing|there)\b/i,
  /\b(?:look|see|watch)\b[^.?!]{0,30}\b(?:camera|webcam|me)\b/i,
  /\b(?:camera|webcam)\b[^.?!]{0,50}\b(?:what|describe|read|see|look|analy[sz]e)\b/i,
  /^\s*(?:eva[,\s]+)?(?:what can you see|describe what you can see|look at this|read this page)\s*[?.!]*\s*$/i,
];

const START_CAMERA_PATTERNS: RegExp[] = [
  /\b(?:start|enable|activate|open)\b[^.?!]{0,24}\b(?:camera|webcam)\b/i,
  /\b(?:turn|switch)\b[^.?!]{0,20}\bon\b[^.?!]{0,12}\b(?:camera|webcam)\b/i,
  /\b(?:camera|webcam)\b[^.?!]{0,18}\b(?:on|start|enable|activate)\b/i,
];

const STOP_CAMERA_PATTERNS: RegExp[] = [
  /\b(?:stop|disable|deactivate|close)\b[^.?!]{0,24}\b(?:camera|webcam)\b/i,
  /\b(?:turn|switch)\b[^.?!]{0,20}\b(?:off)\b[^.?!]{0,12}\b(?:camera|webcam)\b/i,
  /\b(?:turn|switch)\b[^.?!]{0,20}\b(?:camera|webcam)\b[^.?!]{0,12}\boff\b/i,
  /\b(?:camera|webcam)\b[^.?!]{0,18}\b(?:off|stop|disable|deactivate)\b/i,
];

export function detectCameraVisionIntent(text: string): boolean {
  if (!text || text.length > 600) return false;
  if (/^\s*(?:eva[,\s]+)?(?:what(?:'s| is) this|read this|explain this|look at this|can you see this)\s*[?.!]*\s*$/i.test(text)) {
    return false;
  }
  if (/\b(?:screen share|share screen|screen vision|what(?:'s| is)\b[^.?!]{0,30}\bon my screen|look\b[^.?!]{0,30}\bscreen)\b/i.test(text)) {
    return false;
  }
  return CAMERA_QUESTION_PATTERNS.some((pattern) => pattern.test(text));
}

export function detectCameraControlIntent(text: string): "start" | "stop" | null {
  if (!text || text.length > 300) return null;
  if (STOP_CAMERA_PATTERNS.some((pattern) => pattern.test(text))) return "stop";
  if (START_CAMERA_PATTERNS.some((pattern) => pattern.test(text))) return "start";
  return null;
}
