/**
 * The remote-control gateway: the security and dispatch heart of the feature.
 *
 * Every envelope that arrives from a phone via the relay lands here. The
 * gateway:
 *
 *   1. parses/validates the envelope shape (protocol.ts);
 *   2. enforces per-device replay + rate admission (connection.ts);
 *   3. re-checks the device row on EVERY privileged envelope — a revoked
 *      device stops working immediately, even mid-session;
 *   4. dispatches to a handler (tasks, approvals, stream, files, apps);
 *   5. replies through the relay connector.
 *
 * The relay is trusted only for transport: it verifies the HMAC token and
 * stamps `from`/room membership. Authorization decisions happen HERE, against
 * the authoritative device store.
 */
import { randomUUID } from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import type { RemoteConfig } from "./config";
import { REMOTE_ERRORS } from "./config";
import type { DeviceStore, RemoteDevice } from "./devices";
import type { PairingService } from "./pairing";
import { SessionTracker } from "./connection";
import {
  ENVELOPE_VERSION,
  ProtocolError,
  makeEnvelope,
  parseEnvelope,
  validatePayload,
  type Envelope,
} from "./protocol";
import type { TokenClaims } from "./tokens";
import { verifyToken } from "./tokens";

/**
 * Path validation for remote file operations.
 * Ensures all file paths are confined to configured fileRoots (or default safe roots).
 */
interface PathValidationResult {
  ok: boolean;
  resolvedPath?: string;
  error?: string;
}

export function getDefaultFileRoots(): string[] {
  const home = process.env.USERPROFILE || process.env.HOME || "";
  const cwd = process.cwd();
  const roots: string[] = [];
  if (home) {
    roots.push(home);
    roots.push(path.join(home, "Desktop"));
    roots.push(path.join(home, "Documents"));
    roots.push(path.join(home, "Downloads"));
    roots.push(path.join(home, "Pictures"));
    roots.push(path.join(home, "Music"));
    roots.push(path.join(home, "Videos"));
  }
  roots.push(cwd);
  return roots.filter(Boolean);
}

export function resolveRealPath(inputPath: string): string | null {
  try {
    // Expand environment variables and user home
    let expanded = inputPath.replace(/%([^%]+)%/g, (_, key) => process.env[key] || "");
    if (expanded.startsWith("~")) {
      const home = process.env.USERPROFILE || process.env.HOME || "";
      expanded = home ? path.join(home, expanded.slice(1)) : expanded;
    }
    // Resolve to absolute path
    const absolute = path.resolve(expanded);
    // If path exists, canonicalize (resolve symlinks/junctions)
    // If not, resolve the parent directory and append the filename
    if (fs.existsSync(absolute)) {
      return fs.realpathSync(absolute);
    } else {
      const parent = path.dirname(absolute);
      const filename = path.basename(absolute);
      if (fs.existsSync(parent)) {
        return path.join(fs.realpathSync(parent), filename);
      }
      return absolute;
    }
  } catch {
    return null;
  }
}

export function validateFilePath(inputPath: string, allowedRoots: string[]): PathValidationResult {
  const realPath = resolveRealPath(inputPath);
  if (!realPath) {
    return { ok: false, error: `Invalid or inaccessible path: ${inputPath}` };
  }

  // Check if the resolved path is within any allowed root
  for (const root of allowedRoots) {
    const realRoot = resolveRealPath(root);
    if (!realRoot) continue;
    const normalizedRoot = realRoot.endsWith(path.sep) ? realRoot : realRoot + path.sep;
    if (realPath === realRoot || realPath.startsWith(normalizedRoot)) {
      return { ok: true, resolvedPath: realPath };
    }
  }

  return {
    ok: false,
    error: `Path '${inputPath}' is outside allowed file roots. Allowed roots: ${allowedRoots.join(", ")}`,
  };
}

export function getEffectiveFileRoots(cfg: RemoteConfig): string[] {
  return cfg.fileRoots.length > 0 ? cfg.fileRoots : getDefaultFileRoots();
}

export interface AgentResult {
  ok: boolean;
  result?: unknown;
  error?: string;
}

export interface GatewayDeps {
  cfg: RemoteConfig;
  store: DeviceStore;
  pairing: PairingService;
  /** Send an envelope to a device through the relay. Returns false if offline. */
  send: (deviceId: string, envelope: Envelope) => boolean;
  connected: () => boolean;
  tasks: {
    start: (goal: string) => { id: string };
    stop: (taskId: string) => boolean;
    pause: (taskId: string) => boolean;
    resume: (taskId: string) => boolean;
    answer: (taskId: string, text: string) => boolean;
  };
  confirmations: {
    resolve: (id: string, answer: { approved: boolean; remember?: "once" | "session"; via: "api" }) => boolean;
  };
  callAgent: (tool: string, args: Record<string, unknown>, signal?: AbortSignal) => Promise<AgentResult>;
  /**
   * Verify a Supabase access token and return its user id, or null. Present
   * only when Supabase is configured; when absent, the pairing link itself
   * (emailed to the account address + human approval on the PC) is the proof.
   */
  verifyUser?: (token: string) => Promise<string | null>;
  log?: (message: string, extra?: Record<string, unknown>) => void;
}

/** Kinds a `pending` (claimed, not yet approved) device may use. */
const PENDING_ALLOWED = new Set(["hello", "ping", "pairing.claim"]);

interface DeviceConn {
  userId: string;
  deviceId: string;
  kind: TokenClaims["k"];
}

interface StreamState {
  timer: NodeJS.Timeout;
  fps: number;
  quality: number;
  width: number;
  height: number;
  busy: boolean;
  frames: number;
}

const FRAME_MAX_DIM = 1280;
const FRAME_INTERVAL_FLOOR_MS = 66; // hard cap ~15fps even if asked for more

export class RemoteGateway {
  private readonly sessions: SessionTracker;
  private readonly conns = new Map<string, DeviceConn>();
  private readonly streams = new Map<string, StreamState>();
  private readonly uploads = new Map<string, { path: string; chunks: Buffer[]; total: number }>();
  private readonly taskOwners = new Map<string, string>();
  private seq = 0;

  constructor(private readonly deps: GatewayDeps) {
    this.sessions = new SessionTracker(deps.cfg.rateLimitPerMinute);
  }

  // -------------------------------------------------------------------------
  // Inbound
  // -------------------------------------------------------------------------

  /** Entry point for raw text frames from the relay. */
  handleRaw(raw: string): void {
    let envelope: Envelope;
    try {
      envelope = parseEnvelope(raw);
    } catch (error) {
      if (error instanceof ProtocolError) this.deps.log?.(`reject: ${error.message}`);
      return;
    }

    // Relay-internal kinds and anything not addressed to this PC: ignore.
    if (envelope.to !== "pc" && envelope.to !== "*") return;
    if (envelope.kind.startsWith("relay.") || envelope.kind.startsWith("host.")) return;

    const deviceId = envelope.from;
    // hello is exempt from the stale-sequence replay check: a reloaded phone
    // restarts its counter at 1 and needs hello to reset the baseline.
    const admission = this.sessions.admit(deviceId, envelope.id, envelope.seq, {
      allowResync: envelope.kind === "hello",
    });
    if (admission === "replay") return;
    if (admission === "rate") {
      this.replyError(deviceId, envelope, 429, REMOTE_ERRORS.rateLimited);
      return;
    }

    void this.dispatch(deviceId, envelope).catch((error) => {
      this.deps.log?.(`dispatch failed: ${error instanceof Error ? error.message : String(error)}`);
      this.replyError(deviceId, envelope, 500, "Internal error.");
    });
  }

  private async dispatch(deviceId: string, envelope: Envelope): Promise<void> {
    const kind = envelope.kind;

    // --- pairing (uses the token inside the payload, not the connection) ---
    if (kind === "pairing.claim") {
      await this.handlePairingClaim(deviceId, envelope);
      return;
    }

    const conn = this.conns.get(deviceId) || (await this.hydrateConn(deviceId, envelope));
    if (!conn) {
      this.replyError(deviceId, envelope, 401, REMOTE_ERRORS.deviceRequired);
      return;
    }

    const device = await this.deps.store.get(deviceId).catch(() => null);
    if (!device || device.userId !== conn.userId) {
      this.replyError(deviceId, envelope, 404, REMOTE_ERRORS.deviceUnknown);
      this.forget(deviceId);
      return;
    }
    if (device.status === "revoked") {
      this.replyError(deviceId, envelope, 403, REMOTE_ERRORS.deviceRevoked);
      this.forget(deviceId);
      return;
    }
    if (device.status !== "active" && !PENDING_ALLOWED.has(kind)) {
      this.reply(deviceId, envelope, "pairing.status", { status: device.status });
      return;
    }

    // Record/refresh the connection identity once the device is known-good.
    this.conns.set(deviceId, { userId: device.userId, deviceId, kind: conn.kind });
    this.touch(deviceId);

    let payload: Record<string, unknown>;
    try {
      payload = validatePayload(kind, envelope.payload);
    } catch (error) {
      this.replyError(deviceId, envelope, 400, error instanceof ProtocolError ? error.message : "Invalid payload.");
      return;
    }

    switch (kind) {
      case "hello":
        this.sessions.resetSeq(deviceId, envelope.seq);
        this.reply(deviceId, envelope, "hello.ack", {
          protocolVersion: ENVELOPE_VERSION,
          capabilities: [
            "task", "approval", "stream", "files", "apps", "pairing",
          ],
          device: { id: device.id, name: device.name, status: device.status },
        });
        return;

      case "ping":
        this.reply(deviceId, envelope, "pong", { t: Date.now() });
        return;

      case "task.create":
        this.handleTaskCreate(deviceId, envelope, payload);
        return;

      case "task.action":
        this.handleTaskAction(deviceId, envelope, payload);
        return;

      case "approval.resolve":
        this.handleApprovalResolve(deviceId, envelope, payload);
        return;

      case "stream.start":
        this.handleStreamStart(deviceId, envelope, payload);
        return;

      case "stream.stop":
        this.stopStream(deviceId);
        this.reply(deviceId, envelope, "stream.stopped", {});
        return;

      case "stream.input":
        void this.handleStreamInput(deviceId, payload);
        return;

      case "file.list":
      case "file.read":
      case "file.write":
      case "file.download":
      case "file.upload":
        void this.handleFile(deviceId, envelope, kind, payload);
        return;

      case "app.list":
      case "app.launch":
      case "app.close":
        void this.handleApp(deviceId, envelope, kind, payload);
        return;

      case "session.open":
        this.reply(deviceId, envelope, "session.state", { capability: payload.capability, open: true });
        return;

      case "session.close":
        if (payload.capability === "stream") this.stopStream(deviceId);
        this.reply(deviceId, envelope, "session.state", { capability: payload.capability, open: false });
        return;

      case "session.refresh":
        this.handleSessionRefresh(deviceId, envelope, payload);
        return;

      default:
        this.replyError(deviceId, envelope, 400, `Unsupported kind "${kind}".`);
    }
  }

  /** Resolve the device identity for a first envelope on this connection. */
  private async hydrateConn(deviceId: string, envelope: Envelope): Promise<DeviceConn | null> {
    const device = await this.deps.store.get(deviceId).catch(() => null);
    if (!device) return null;
    return { userId: device.userId, deviceId, kind: "access" };
  }

  // -------------------------------------------------------------------------
  // Pairing over the relay
  // -------------------------------------------------------------------------

  private async handlePairingClaim(deviceId: string, envelope: Envelope): Promise<void> {
    let payload: Record<string, unknown>;
    try {
      payload = validatePayload("pairing.claim", envelope.payload);
    } catch (error) {
      this.replyError(deviceId, envelope, 400, error instanceof ProtocolError ? error.message : "Invalid payload.");
      return;
    }

    const token = String(payload.token);
    const claims = verifyToken(this.deps.cfg, token, "pair");
    if (!claims) {
      this.reply(deviceId, envelope, "pairing.denied", { reason: REMOTE_ERRORS.pairingExpired });
      return;
    }

    // Ownership check: when Supabase auth is configured, the claiming phone
    // must prove it is signed in AS THE SAME USER the link was emailed to.
    // The pairing link alone is never a bearer credential.
    if (this.deps.verifyUser) {
      const sessionToken = typeof payload.sessionToken === "string" ? payload.sessionToken : "";
      const sessionUserId = sessionToken ? await this.deps.verifyUser(sessionToken).catch(() => null) : null;
      if (!sessionUserId || sessionUserId !== claims.uid) {
        this.reply(deviceId, envelope, "pairing.denied", { reason: "Sign in as the account this computer belongs to." });
        return;
      }
    }

    const result = await this.deps.pairing.claim(
      claims.uid,
      token,
      String(payload.deviceName || "Unknown device"),
      payload.platform ? String(payload.platform) : null,
    );
    if (!result) {
      this.reply(deviceId, envelope, "pairing.denied", { reason: REMOTE_ERRORS.pairingExpired });
      return;
    }

    // Track the waiting connection so `pairing.approved` can find it.
    this.conns.set(deviceId, { userId: claims.uid, deviceId, kind: "pair" });
    this.sessions.open(deviceId, claims.uid);

    if (result.device.status === "active") {
      // Approved while we were away — issue credentials right now.
      const creds = this.deps.pairing.issueCredentials(claims.uid, result.device.id);
      this.reply(deviceId, envelope, "pairing.approved", {
        device: publicDevice(result.device),
        ...creds,
      });
      return;
    }

    this.reply(deviceId, envelope, "pairing.status", {
      status: "pending",
      device: publicDevice(result.device),
    });
  }

  /** Called by the pairing service when the human on the PC clicks Allow. */
  notifyPairingApproved(device: RemoteDevice): void {
    const creds = this.deps.pairing.issueCredentials(device.userId, device.id);
    this.push(device.id, "pairing.approved", { device: publicDevice(device), ...creds });
  }

  notifyPairingRevoked(device: RemoteDevice): void {
    this.push(device.id, "device.status", { status: "revoked", device: publicDevice(device) });
    this.forget(device.id);
  }

  // -------------------------------------------------------------------------
  // Tasks + approvals
  // -------------------------------------------------------------------------

  private handleTaskCreate(deviceId: string, envelope: Envelope, payload: Record<string, unknown>): void {
    try {
      const session = this.deps.tasks.start(String(payload.command));
      // Remember who owns this task so live progress and the final reply can
      // be forwarded back to the right phone as chat messages.
      this.taskOwners.set(session.id, deviceId);
      this.reply(deviceId, envelope, "task.snapshot", {
        taskId: session.id,
        status: "queued",
        goal: String(payload.command),
        key: payload.key,
      });
    } catch (error) {
      this.replyError(deviceId, envelope, 400, error instanceof Error ? error.message : "Could not start task.");
    }
  }

  private handleTaskAction(deviceId: string, envelope: Envelope, payload: Record<string, unknown>): void {
    const taskId = String(payload.taskId);
    const action = String(payload.action);
    let ok = false;
    if (action === "stop") ok = this.deps.tasks.stop(taskId);
    else if (action === "pause") ok = this.deps.tasks.pause(taskId);
    else if (action === "resume") ok = this.deps.tasks.resume(taskId);
    else if (action === "answer" && typeof payload.text === "string") ok = this.deps.tasks.answer(taskId, payload.text);
    this.reply(deviceId, envelope, "task.snapshot", { taskId, action, ok });
  }

  private handleApprovalResolve(deviceId: string, envelope: Envelope, payload: Record<string, unknown>): void {
    const ok = this.deps.confirmations.resolve(String(payload.confirmationId), {
      approved: payload.approved === true,
      ...(payload.remember ? { remember: payload.remember as "once" | "session" } : {}),
      via: "api",
    });
    this.reply(deviceId, envelope, "approval.resolved", {
      confirmationId: payload.confirmationId,
      approved: payload.approved === true,
      ok,
    });
  }

  /**
   * Mint fresh credentials from the device's long-lived refresh token. The
   * device row itself was already re-verified (exists, same user, not revoked)
   * by `dispatch` for this envelope; the refresh token must additionally be a
   * signed `refresh` credential for THIS device. The phone connects with the
   * refresh token when its access token has expired, refreshes, and swaps to
   * the new access token — so a paired phone survives the 30-minute access
   * TTL without re-pairing.
   */
  private handleSessionRefresh(deviceId: string, envelope: Envelope, payload: Record<string, unknown>): void {
    const refresh = String(payload.refresh || "");
    const claims = verifyToken(this.deps.cfg, refresh, "refresh");
    const conn = this.conns.get(deviceId);
    if (!claims || claims.did !== deviceId || !conn || claims.uid !== conn.userId) {
      this.replyError(deviceId, envelope, 401, REMOTE_ERRORS.sessionExpired);
      return;
    }
    const creds = this.deps.pairing.issueCredentials(claims.uid, deviceId);
    this.reply(deviceId, envelope, "session.updated", { deviceId, ...creds });
  }

  // -------------------------------------------------------------------------
  // Live desktop stream (adaptive JPEG over the envelope channel)
  // -------------------------------------------------------------------------

  private handleStreamStart(deviceId: string, envelope: Envelope, payload: Record<string, unknown>): void {
    this.stopStream(deviceId);
    const requested = typeof payload.fps === "number" ? payload.fps : 10;
    const fps = Math.max(1, Math.min(requested, this.deps.cfg.maxStreamFps));
    const quality = typeof payload.quality === "number" ? payload.quality : 70;

    const state: StreamState = {
      timer: setTimeout(() => this.captureFrame(deviceId), 0),
      fps,
      quality,
      width: 0,
      height: 0,
      busy: false,
      frames: 0,
    };
    this.streams.set(deviceId, state);
    this.reply(deviceId, envelope, "stream.stats", { fps, quality, maxFps: this.deps.cfg.maxStreamFps });
  }

  private stopStream(deviceId: string): void {
    const state = this.streams.get(deviceId);
    if (!state) return;
    clearTimeout(state.timer);
    this.streams.delete(deviceId);
  }

  private async captureFrame(deviceId: string): Promise<void> {
    const state = this.streams.get(deviceId);
    if (!state) return;
    state.busy = true;
    try {
      const capture = await this.deps.callAgent("viewScreen", { max_dim: FRAME_MAX_DIM, keep_file: false });
      if (!this.streams.has(deviceId)) return; // stopped while capturing
      if (!capture.ok || !capture.result || typeof capture.result !== "object") {
        this.stopStream(deviceId);
        this.push(deviceId, "stream.stopped", { reason: capture.error || "capture_failed" });
        return;
      }
      const result = capture.result as Record<string, unknown>;
      const data = result.image_base64;
      if (typeof data !== "string" || !data) {
        this.stopStream(deviceId);
        this.push(deviceId, "stream.stopped", { reason: "no_frame" });
        return;
      }
      state.width = Number(result.width) || state.width;
      state.height = Number(result.height) || state.height;
      state.frames += 1;
      this.push(deviceId, "stream.frame", {
        mime: result.image_mime || "image/jpeg",
        data,
        width: state.width,
        height: state.height,
        quality: state.quality,
        seq: state.frames,
      });
      const interval = Math.max(FRAME_INTERVAL_FLOOR_MS, Math.floor(1000 / state.fps));
      state.timer = setTimeout(() => void this.captureFrame(deviceId), interval);
    } catch (error) {
      this.deps.log?.(`stream capture error: ${error instanceof Error ? error.message : String(error)}`);
      this.stopStream(deviceId);
      this.push(deviceId, "stream.stopped", { reason: "error" });
    }
  }

  private async handleStreamInput(deviceId: string, payload: Record<string, unknown>): Promise<void> {
    const state = this.streams.get(deviceId);
    const type = String(payload.type);
    // Pointer input is normalized against the last streamed frame. Without a
    // live frame the coordinates have no meaning, so a stray tap must never
    // translate into a click at a guessed position.
    if (!state && (type === "move" || type === "down" || type === "up" || type === "wheel")) return;
    const toPixels = (value: unknown): number => {
      const ratio = Number(value);
      if (!Number.isFinite(ratio)) return 0;
      // Normalized 0..1 against the last streamed frame's true screen size.
      return Math.round(ratio * (state?.width || 1920));
    };
    const yPixels = (value: unknown): number => {
      const ratio = Number(value);
      if (!Number.isFinite(ratio)) return 0;
      return Math.round(ratio * (state?.height || 1080));
    };

    let tool = "";
    let args: Record<string, unknown> = {};
    switch (type) {
      case "move":
        tool = "moveMouse";
        args = { x: toPixels(payload.x), y: yPixels(payload.y), duration: 0 };
        break;
      case "down":
      case "up": {
        // v1: a press is a click on button-down; releases are swallowed.
        if (type === "up") return;
        const button = Number(payload.button) || 0;
        tool = button === 2 ? "rightClick" : button === 1 ? "click" : "click";
        args = { x: toPixels(payload.x), y: yPixels(payload.y), ...(button === 2 ? {} : { button: button === 1 ? "middle" : "left" }) };
        break;
      }
      case "wheel":
        tool = "scroll";
        args = {
          amount: Math.round(Number(payload.deltaY) || 0),
          x: toPixels(payload.x),
          y: yPixels(payload.y),
        };
        break;
      case "key": {
        const key = String(payload.key || "");
        const mods: string[] = [];
        if (payload.ctrl) mods.push("ctrl");
        if (payload.alt) mods.push("alt");
        if (payload.shift) mods.push("shift");
        if (payload.meta) mods.push("win");
        tool = mods.length ? "hotkey" : "pressKey";
        args = mods.length ? { keys: [...mods, key] } : { key };
        break;
      }
      case "text":
        tool = "typeText";
        args = { text: String(payload.text) };
        break;
      default:
        return;
    }
    await this.deps.callAgent(tool, args).catch(() => undefined);
  }

  // -------------------------------------------------------------------------
  // Files (sandboxed to cfg.fileRoots when configured)
  // -------------------------------------------------------------------------

  private validateAndResolvePath(payload: Record<string, unknown>): string {
    const raw = String(payload.path || payload.name || "").trim();
    if (!raw) throw new Error("A path is required.");
    const roots = getEffectiveFileRoots(this.deps.cfg);
    const validation = validateFilePath(raw, roots);
    if (!validation.ok) {
      throw new Error(validation.error);
    }
    return validation.resolvedPath!;
  }

  private async handleFile(deviceId: string, envelope: Envelope, kind: string, payload: Record<string, unknown>): Promise<void> {
    try {
      const path = this.validateAndResolvePath(payload);
      if (kind === "file.list") {
        const result = await this.deps.callAgent("listFiles", { path });
        this.reply(deviceId, envelope, "file.entries", {
          path,
          entries: (result.result as { items?: string[] })?.items ?? [],
          ok: result.ok,
          error: result.error,
        });
        return;
      }
      if (kind === "file.read") {
        const result = await this.deps.callAgent("readFile", { path, max_chars: 200_000 });
        this.reply(deviceId, envelope, "file.data", {
          path,
          content: (result.result as { result?: string })?.result ?? "",
          ok: result.ok,
          error: result.error,
        });
        return;
      }
      if (kind === "file.write") {
        const content = typeof payload.content === "string" ? payload.content : "";
        const result = await this.deps.callAgent("createFile", { path, content, overwrite: true });
        this.reply(deviceId, envelope, "file.data", { path, ok: result.ok, error: result.error, written: content.length });
        return;
      }
      if (kind === "file.download") {
        const result = await this.deps.callAgent("readFile", { path, max_chars: 200_000 });
        this.reply(deviceId, envelope, "file.data", {
          path,
          transferId: payload.transferId,
          content: (result.result as { result?: string })?.result ?? "",
          ok: result.ok,
          error: result.error,
        });
        return;
      }
      if (kind === "file.upload") {
        const transferId = String(payload.transferId);
        const chunk = Number(payload.chunk);
        const chunks = Number(payload.chunks);
        const data = Buffer.from(String(payload.data), "base64");
        let pending = this.uploads.get(transferId);
        if (!pending) {
          // Validate path on first chunk
          const validatedPath = this.validateAndResolvePath(payload);
          pending = { path: validatedPath, chunks: new Array(chunks), total: chunks };
          this.uploads.set(transferId, pending);
        } else {
          // Validate path consistency on subsequent chunks
          const validatedPath = this.validateAndResolvePath(payload);
          if (pending.path !== validatedPath) {
            this.replyError(deviceId, envelope, 400, "Upload path mismatch.");
            return;
          }
        }
        pending.chunks[chunk] = data;
        const received = pending.chunks.filter(Boolean).length;
        if (received < pending.total) {
          this.reply(deviceId, envelope, "file.data", { transferId, received, total: pending.total, ok: true });
          return;
        }
        const full = Buffer.concat(pending.chunks.filter(Boolean) as Buffer[]);
        this.uploads.delete(transferId);
        const result = await this.deps.callAgent("createFile", {
          path: pending.path,
          content: full.toString("utf-8"),
          overwrite: true,
        });
        this.reply(deviceId, envelope, "file.data", {
          transferId,
          path: pending.path,
          bytes: full.length,
          ok: result.ok,
          error: result.error,
        });
      }
    } catch (error) {
      this.replyError(deviceId, envelope, 400, error instanceof Error ? error.message : "File operation failed.");
    }
  }

  // -------------------------------------------------------------------------
  // Applications
  // -------------------------------------------------------------------------

  private async handleApp(deviceId: string, envelope: Envelope, kind: string, payload: Record<string, unknown>): Promise<void> {
    if (kind === "app.list") {
      const result = await this.deps.callAgent("listVisibleWindows", {});
      const wins = (result.result as { windows?: Array<Record<string, unknown>> })?.windows ?? [];
      this.reply(deviceId, envelope, "app.entries", {
        entries: wins.map((w) => ({ title: String(w.title || ""), process: String(w.process || w.app || "") })),
        ok: result.ok,
        error: result.error,
      });
      return;
    }
    const application = String(payload.application || "");
    const tool = kind === "app.launch" ? "openApplication" : "closeApplication";
    const result = await this.deps.callAgent(tool, { application });
    this.reply(deviceId, envelope, kind === "app.launch" ? "notification" : "app.entries", {
      ok: result.ok,
      error: result.error,
      application,
      message: (result.result as { result?: string })?.result || undefined,
    });
  }

  // -------------------------------------------------------------------------
  // Outbound helpers
  // -------------------------------------------------------------------------

  /** Broadcast an event to a device without a triggering envelope. */
  push(deviceId: string, kind: string, payload: unknown): boolean {
    this.seq += 1;
    const envelope = makeEnvelope(deviceId, kind, payload, "pc", this.seq);
    return this.deps.send(deviceId, envelope);
  }

  private reply(deviceId: string, request: Envelope, kind: string, payload: unknown): void {
    this.seq += 1;
    const envelope = makeEnvelope(deviceId, kind, payload, "pc", this.seq, request.id);
    this.deps.send(deviceId, envelope);
  }

  private replyError(deviceId: string, request: Envelope | null, code: number, message: string): void {
    this.seq += 1;
    const envelope = makeEnvelope(deviceId, "error", { code, message }, "pc", this.seq, request?.id);
    this.deps.send(deviceId, envelope);
  }

  private forget(deviceId: string): void {
    this.conns.delete(deviceId);
    this.sessions.close(deviceId);
    this.stopStream(deviceId);
    this.uploads.clear();
  }

  /** Cheap liveness stamp (best effort; not on the hot path). */
  private touch(deviceId: string): void {
    const now = new Date().toISOString();
    void this.deps.store.update(deviceId, { lastSeenAt: now }).catch(() => undefined);
  }

  /** Tear down everything for a device whose relay connection dropped. */
  handleDisconnect(deviceId: string): void {
    this.stopStream(deviceId);
    this.sessions.close(deviceId);
    // Keep conns entry: the phone reconnects quickly and revalidates on the
    // next privileged envelope anyway.
  }

  connectedDeviceIds(): string[] {
    return [...this.conns.keys()];
  }

  /**
   * Forward a live task event (from the PC's appEvents hub) to the phone that
   * started it, as chat messages. `kind` is "task.updated" or "task.finished".
   */
  forwardTaskEvent(taskId: string, kind: "task.updated" | "task.finished", view: Record<string, unknown>): void {
    const deviceId = this.taskOwners.get(taskId);
    if (!deviceId) return;
    this.seq += 1;
    const envelope = makeEnvelope(deviceId, "chat.message", {
      taskId,
      state: view.state ?? "unknown",
      status: view.currentStatus ?? "",
      result: view.result ?? null,
      goal: view.goal ?? "",
    }, "pc", this.seq);
    this.deps.send(deviceId, envelope);
    if (kind === "task.finished") {
      this.taskOwners.delete(taskId);
      this.seq += 1;
      const done = makeEnvelope(deviceId, "chat.done", {
        taskId,
        state: view.state ?? "unknown",
        error: view.error ?? null,
      }, "pc", this.seq);
      this.deps.send(deviceId, done);
    }
  }

  /**
   * Forward an approval raised on the PC (confirmation.requested/resolved) to
   * the phone that owns the task, so the Approvals tab can answer it. Only
   * display-safe fields travel: ids, title, description and expiry — never
   * the raw `details` (which may contain action arguments).
   */
  forwardConfirmationEvent(kind: "confirmation.requested" | "confirmation.resolved", view: Record<string, unknown>): void {
    const taskId = typeof view.taskId === "string" ? view.taskId : "";
    if (!taskId) return;
    const deviceId = this.taskOwners.get(taskId);
    if (!deviceId) return;
    this.seq += 1;
    const payload = kind === "confirmation.requested"
      ? {
          id: String(view.id || ""),
          taskId,
          title: String(view.title || "Approval needed"),
          description: String(view.description || ""),
          expiresAt: view.expiresAt ?? null,
        }
      : { id: String(view.id || ""), taskId, approved: view.approved === true, via: view.via ?? null };
    const envelope = makeEnvelope(deviceId, kind === "confirmation.requested" ? "approval.requested" : "approval.resolved", payload, "pc", this.seq);
    this.deps.send(deviceId, envelope);
  }

  userIdFor(deviceId: string): string | null {
    return this.conns.get(deviceId)?.userId || null;
  }
}

function publicDevice(device: RemoteDevice): Record<string, unknown> {
  return {
    id: device.id,
    name: device.name,
    platform: device.platform,
    status: device.status,
    approvedAt: device.approvedAt,
    createdAt: device.createdAt,
  };
}

export function newEnvelopeId(): string {
  return randomUUID();
}
