/**
 * JARVIS — administrative authorization middleware.
 *
 * Provides backend-enforced role checks for every administrative API endpoint.
 * - OWNER-only endpoints require verified Owner authorization.
 * - ADMIN endpoints accept verified Owner or Admin authorization.
 * - Role changes invalidate/refresh sessions safely.
 * - Unauthorized access attempts are rejected and logged without exposing sensitive information.
 *
 * The frontend should hide/disable unavailable actions according to the verified role,
 * but frontend restrictions must NEVER replace backend authorization.
 */

import type { NextFunction, Request, Response } from "express";
import { supabase, supabaseConfigured, requireAdmin } from "./supabaseClient";
import { AUTH_ERRORS } from "./authRoutes";

/** True when the backend can bypass RLS to enforce/perform administrative work. */
function serviceRoleConfigured(): boolean {
  return Boolean(process.env.SUPABASE_SERVICE_ROLE_KEY);
}

export interface AdminAuthedRequest extends Request {
  userId?: string;
  userEmail?: string | null;
  adminRole?: "OWNER" | "ADMIN" | null;
}

/** Verified session result for admin authorization. */
export interface AdminSession {
  userId: string;
  userEmail: string | null;
  adminRole: "OWNER" | "ADMIN" | null;
  suspended: boolean;
}

/** Session verifier for admin authorization (allows test injection). */
export interface AdminSessionVerifier {
  verify(token: string): Promise<AdminSession | null>;
}

const defaultAdminVerifier: AdminSessionVerifier = {
  async verify(token) {
    const { data, error } = await supabase.auth.getUser(token);
    if (error || !data.user) return null;
    const suspended = data.user.app_metadata?.suspended === true;
    // Role lookup deferred to requireAdminRole for DB-backed check
    return { userId: data.user.id, userEmail: data.user.email ?? null, adminRole: null, suspended };
  },
};

let adminSessionVerifier: AdminSessionVerifier = defaultAdminVerifier;

/** Replace the session verifier. Tests use this; production never does. */
export function setAdminSessionVerifier(verifier: AdminSessionVerifier | null): void {
  adminSessionVerifier = verifier ?? defaultAdminVerifier;
}

/** Middleware: rejects requests without a verified Supabase session AND admin role. */
export async function requireAdminRole(req: AdminAuthedRequest, res: Response, next: NextFunction): Promise<void> {
  if (!supabaseConfigured) {
    res.status(503).json({ error: AUTH_ERRORS.notConfigured });
    return;
  }

  const header = req.headers["authorization"];
  const token = (Array.isArray(header) ? header[0] : header)?.replace(/^Bearer\s+/i, "").trim();

  if (!token) {
    res.status(401).json({ error: AUTH_ERRORS.unauthorized });
    return;
  }

  const session = await adminSessionVerifier.verify(token);
  if (!session) {
    res.status(401).json({ error: AUTH_ERRORS.sessionExpired });
    return;
  }

  // Suspended accounts are denied everywhere, on the authority of the verified
  // session's server-controlled app_metadata (set only by the backend via the
  // service role). app_metadata cannot be edited by the end user, unlike
  // user_metadata.
  if (session.suspended) {
    res.status(403).json({ error: AUTH_ERRORS.suspended });
    return;
  }

  req.userId = session.userId;
  req.userEmail = session.userEmail;

  // Administrative work requires the service role to read roles and manage
  // accounts. A client build without it must fail cleanly, never throw.
  if (!serviceRoleConfigured()) {
    res.status(503).json({ error: "Administrative features are not available on this instance." });
    return;
  }

  // Fetch the user's admin role from profiles
  const admin = requireAdmin();
  const { data: profile, error: profileError } = await admin
    .from("profiles")
    .select("admin_role")
    .eq("id", session.userId)
    .maybeSingle();

  if (profileError) {
    res.status(500).json({ error: "Could not verify administrative role." });
    return;
  }

  req.adminRole = (profile?.admin_role as "OWNER" | "ADMIN" | null) ?? null;

  if (!req.adminRole) {
    res.status(403).json({ error: "Administrative access required." });
    return;
  }

  next();
}

/** Middleware: requires verified Owner role. */
export async function requireOwner(req: AdminAuthedRequest, res: Response, next: NextFunction): Promise<void> {
  await requireAdminRole(req, res, () => {
    if (req.adminRole !== "OWNER") {
      res.status(403).json({ error: "Owner access required." });
      return;
    }
    next();
  });
}

/** Middleware: requires verified Admin or Owner role. */
export async function requireAdminOrOwner(req: AdminAuthedRequest, res: Response, next: NextFunction): Promise<void> {
  await requireAdminRole(req, res, () => {
    // requireAdminRole already ensures adminRole is OWNER or ADMIN
    next();
  });
}

/** Helper: get admin role for a user id (uses service role). */
export async function getUserAdminRole(userId: string): Promise<"OWNER" | "ADMIN" | null> {
  const admin = requireAdmin();
  const { data, error } = await admin
    .from("profiles")
    .select("admin_role")
    .eq("id", userId)
    .maybeSingle();

  if (error || !data) return null;
  return (data.admin_role as "OWNER" | "ADMIN" | null) ?? null;
}

/** Helper: check if user is Owner. */
export async function isUserOwner(userId: string): Promise<boolean> {
  const role = await getUserAdminRole(userId);
  return role === "OWNER";
}

/** Helper: check if user is Admin or Owner. */
export async function isUserAdminOrOwner(userId: string): Promise<boolean> {
  const role = await getUserAdminRole(userId);
  return role === "OWNER" || role === "ADMIN";
}

/** Helper: count active Owners (for last-Owner protection). */
export async function countActiveOwners(): Promise<number> {
  const admin = requireAdmin();
  const { data, error } = await admin.rpc("count_active_owners");
  if (error || data === null) return 0;
  return Number(data);
}