/**
 * JARVIS — per-user legacy memory file store.
 *
 * The original memories.json held every user's memories in one shared file.
 * This wrapper partitions it by scope: one file per authenticated user under
 * <data>/scoped-memories/. On first access the shared file is migrated into
 * the local scope exactly once, so a single-user install keeps its history.
 */
import fs from "node:fs/promises";
import path from "node:path";
import { dataFile } from "../server_paths";
import type { Memory } from "../src/lib/memoryTypes";
import { LOCAL_SCOPE_ID } from "../auth/memoryScope";

/**
 * Directory holding the per-user memory files.
 *
 * Resolved lazily so that a process (or a test) can repoint EVA_DATA_DIR
 * after this module is imported.
 */
function scopedDir(): string {
  return dataFile("scoped-memories");
}
function legacyFile(): string {
  return dataFile("memories.json");
}
function legacyMarker(): string {
  return dataFile(".memories-migrated");
}

function scopeFile(scopeId: string): string {
  return path.join(scopedDir(), `${scopeId}.json`);
}

/** Move the pre-multi-user shared file into the local scope, once. */
async function migrateLegacyFile(): Promise<void> {
  try {
    await fs.mkdir(scopedDir(), { recursive: true });
  } catch { /* exists */ }
  let already = false;
  try {
    await fs.access(legacyMarker());
    already = true;
  } catch { /* not migrated yet */ }
  if (already) return;
  try {
    const raw = await fs.readFile(legacyFile(), "utf-8");
    const parsed = JSON.parse(raw) as Memory[];
    if (Array.isArray(parsed) && parsed.length) {
      await fs.writeFile(scopeFile(LOCAL_SCOPE_ID), JSON.stringify(parsed, null, 2), "utf-8");
      console.log(`[Memory] Migrated ${parsed.length} shared memories into the local scope.`);
    }
  } catch {
    /* no legacy file — nothing to migrate */
  }
  await fs.writeFile(legacyMarker(), new Date().toISOString(), "utf-8").catch(() => {});
}

let migrationStarted = false;
function ensureMigration(): Promise<void> {
  if (migrationStarted) return Promise.resolve();
  migrationStarted = true;
  return migrateLegacyFile().catch((error) => console.error("[Memory] Legacy migration failed:", error));
}

/** Load one user's memories. Never reads another scope's file. */
export async function loadScopedMemories(scopeId: string): Promise<Memory[]> {
  await ensureMigration();
  try {
    const data = await fs.readFile(scopeFile(scopeId), "utf-8");
    const parsed = JSON.parse(data);
    return Array.isArray(parsed) ? (parsed as Memory[]) : [];
  } catch (error: any) {
    if (error.code === "ENOENT") return [];
    console.error(`[Memory] Error loading memories for scope ${scopeId}:`, error);
    return [];
  }
}

/** Save one user's memories to that scope's file only. */
export async function saveScopedMemories(scopeId: string, memories: Memory[]): Promise<void> {
  await ensureMigration();
  try {
    await fs.mkdir(scopedDir(), { recursive: true });
    await fs.writeFile(scopeFile(scopeId), JSON.stringify(memories, null, 2), "utf-8");
  } catch (error) {
    console.error(`[Memory] Error writing memories for scope ${scopeId}:`, error);
  }
}

/** Delete every memory for one scope. No other scope's file is touched. */
export async function clearScopedMemories(scopeId: string): Promise<void> {
  await saveScopedMemories(scopeId, []);
}

/** The file path for a scope, for tests. */
export function scopedMemoryFilePath(scopeId: string): string {
  return scopeFile(scopeId);
}
