/**
 * Durable memory: persistent preferences, work habits, frequently used paths.
 * Survives restarts; used to reduce future prompts.
 */
import { randomUUID } from "node:crypto";
import path from "node:path";
import { readJsonFile, writeJsonFile } from "../shared/jsonFile";

export interface DurablePreference {
  id: string;
  key: string;
  value: string;
  context?: string;
  createdAt: string;
  updatedAt: string;
  accessCount: number;
}

export interface FrequentPath {
  id: string;
  path: string;
  alias?: string;
  visitCount: number;
  lastVisitedAt: string;
  context?: string;
}

export interface WorkHabit {
  id: string;
  pattern: string;
  frequency: number;
  lastSeenAt: string;
  context?: string;
}

interface DurableMemoryFile {
  version: 1;
  preferences: DurablePreference[];
  frequentPaths: FrequentPath[];
  workHabits: WorkHabit[];
}

export class DurableMemoryStore {
  private preferences: DurablePreference[] = [];
  private frequentPaths: FrequentPath[] = [];
  private workHabits: WorkHabit[] = [];
  private loaded = false;
  private writeQueue: Promise<void> = Promise.resolve();
  private readonly file: string;
  private readonly scopeId: string;

  constructor(dataDir: string, scopeId: string = "local") {
    this.scopeId = scopeId;
    this.file = path.join(dataDir, "memory", "durable", `${scopeId}.v1.json`);
  }

  async initialize(): Promise<void> {
    if (this.loaded) return;
    await path.dirname(this.file);
    try {
      const parsed = await readJsonFile<DurableMemoryFile>(this.file, {
        version: 1,
        preferences: [],
        frequentPaths: [],
        workHabits: [],
      });
      this.preferences = Array.isArray(parsed.preferences) ? parsed.preferences : [];
      this.frequentPaths = Array.isArray(parsed.frequentPaths) ? parsed.frequentPaths : [];
      this.workHabits = Array.isArray(parsed.workHabits) ? parsed.workHabits : [];
    } catch (error: any) {
      if (error?.code !== "ENOENT") {
        const backup = `${this.file}.corrupt-${Date.now()}`;
        await path.dirname(this.file);
      }
      this.preferences = [];
      this.frequentPaths = [];
      this.workHabits = [];
    }
    this.loaded = true;
  }

  private assertLoaded(): void {
    if (!this.loaded) throw new Error("DurableMemoryStore.initialize() must be called first.");
  }

  async setPreference(key: string, value: string, context?: string): Promise<DurablePreference> {
    this.assertLoaded();
    const normalizedKey = key.trim().toLowerCase();
    const existing = this.preferences.find((p) => p.key === normalizedKey);
    const now = new Date().toISOString();
    if (existing) {
      existing.value = value;
      existing.context = context ?? existing.context;
      existing.updatedAt = now;
      existing.accessCount += 1;
      await this.persist();
      return structuredClone(existing);
    }
    const pref: DurablePreference = {
      id: randomUUID(),
      key: normalizedKey,
      value,
      context,
      createdAt: now,
      updatedAt: now,
      accessCount: 1,
    };
    this.preferences.push(pref);
    await this.persist();
    return structuredClone(pref);
  }

  async getPreference(key: string): Promise<DurablePreference | undefined> {
    this.assertLoaded();
    const pref = this.preferences.find((p) => p.key === key.trim().toLowerCase());
    if (pref) {
      pref.accessCount += 1;
      pref.updatedAt = new Date().toISOString();
      await this.persist();
      return structuredClone(pref);
    }
    return undefined;
  }

  listPreferences(): DurablePreference[] {
    this.assertLoaded();
    return this.preferences.map((p) => structuredClone(p));
  }

  async recordPath(pathStr: string, alias?: string, context?: string): Promise<FrequentPath> {
    this.assertLoaded();
    const normalized = pathStr.trim();
    const existing = this.frequentPaths.find((fp) => fp.path.toLowerCase() === normalized.toLowerCase());
    const now = new Date().toISOString();
    if (existing) {
      existing.visitCount += 1;
      existing.lastVisitedAt = now;
      existing.context = context ?? existing.context;
      if (alias) existing.alias = alias;
      await this.persist();
      return structuredClone(existing);
    }
    const fp: FrequentPath = {
      id: randomUUID(),
      path: normalized,
      alias,
      visitCount: 1,
      lastVisitedAt: now,
      context,
    };
    this.frequentPaths.push(fp);
    await this.persist();
    return structuredClone(fp);
  }

  getFrequentPaths(limit = 10): FrequentPath[] {
    this.assertLoaded();
    return [...this.frequentPaths]
      .sort((a, b) => b.visitCount - a.visitCount || b.lastVisitedAt.localeCompare(a.lastVisitedAt))
      .slice(0, limit)
      .map((p) => structuredClone(p));
  }

  async recordHabit(pattern: string, context?: string): Promise<WorkHabit> {
    this.assertLoaded();
    const existing = this.workHabits.find((h) => h.pattern === pattern);
    const now = new Date().toISOString();
    if (existing) {
      existing.frequency += 1;
      existing.lastSeenAt = now;
      existing.context = context ?? existing.context;
      await this.persist();
      return structuredClone(existing);
    }
    const habit: WorkHabit = {
      id: randomUUID(),
      pattern,
      frequency: 1,
      lastSeenAt: now,
      context,
    };
    this.workHabits.push(habit);
    await this.persist();
    return structuredClone(habit);
  }

  getHabits(limit = 10): WorkHabit[] {
    this.assertLoaded();
    return [...this.workHabits]
      .sort((a, b) => b.frequency - a.frequency)
      .slice(0, limit)
      .map((h) => structuredClone(h));
  }

  snapshot() {
    this.assertLoaded();
    return {
      preferences: this.listPreferences().slice(0, 20),
      frequentPaths: this.getFrequentPaths(10),
      habits: this.getHabits(10),
    };
  }

  private async persist(): Promise<void> {
    const serialized = JSON.stringify(
      {
        version: 1,
        preferences: this.preferences,
        frequentPaths: this.frequentPaths,
        workHabits: this.workHabits,
      } satisfies DurableMemoryFile,
      null,
      2,
    );
    const write = this.writeQueue.catch(() => undefined).then(async () => {
      const temp = `${this.file}.${process.pid}.${randomUUID()}.tmp`;
      try {
        await writeJsonFile(temp, JSON.parse(serialized));
        await path.dirname(this.file);
        await writeJsonFile(this.file, JSON.parse(serialized));
      } catch (error) {
        throw error;
      }
    });
    this.writeQueue = write.catch(() => undefined);
    await write;
  }
}