/**
 * JARVIS — billing & subscription REST routes.
 *
 * Bridges the browser SPA to the Supabase billing backend:
 *  - user routes  : plans, entitlement, own payments, submit a payment
 *  - owner routes : list / approve / reject payments, read the audit log
 *
 * Identity always comes from a VERIFIED session (requireAuth / requireOwner);
 * amounts are always derived server-side from the plans table, never trusted
 * from the request body. Privileged writes go through the service-role RPCs
 * (approve/reject), which re-check the OWNER role themselves.
 */
import type { Request, Response } from "express";
import { requireAdmin } from "./supabaseClient";
import { requireAuth, type AuthedRequest } from "./authRoutes";
import { requireOwner, type AdminAuthedRequest } from "./adminAuth";

const PAYMENT_STATUSES = ["pending", "approved", "rejected", "expired"] as const;
const RECEIPT_MIME: Record<string, string> = {
  "image/jpeg": "jpg",
  "image/png": "png",
  "image/webp": "webp",
};
const MAX_RECEIPT_BYTES = 5 * 1024 * 1024;

interface PaymentRequestRow {
  id: string;
  user_id: string;
  plan_id: string;
  expected_amount_pkr: number;
  submitted_amount_pkr: number | null;
  payment_reference: string;
  submitted_transaction_ref: string | null;
  payment_date: string | null;
  receipt_storage_path: string | null;
  status: string;
  rejection_reason: string | null;
  reviewed_by: string | null;
  reviewed_at: string | null;
  created_at: string;
  updated_at: string;
}

function generatePaymentReference(userId: string): string {
  const short = userId.replace(/-/g, "").slice(0, 8).toUpperCase();
  const stamp = Date.now().toString(36).toUpperCase();
  return `EVA-${short}-${stamp}`;
}

function isValidDate(value: string): boolean {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const d = new Date(`${value}T00:00:00Z`);
  return !Number.isNaN(d.getTime());
}

async function uploadReceipt(
  userId: string,
  paymentRequestId: string,
  base64: string,
  mimeType: string,
): Promise<string | null> {
  const ext = RECEIPT_MIME[mimeType];
  if (!ext) return null;
  const buffer = Buffer.from(base64, "base64");
  if (buffer.length === 0 || buffer.length > MAX_RECEIPT_BYTES) return null;
  const path = `${userId}/${paymentRequestId}.${ext}`;
  const admin = requireAdmin();
  const { error } = await admin.storage
    .from("payment-receipts")
    .upload(path, buffer, { contentType: mimeType, upsert: false });
  if (error) return null;
  return path;
}

export function registerBillingRoutes(app: import("express").Express): void {
  // --- plans (any signed-in user) --------------------------------------
  app.get("/api/billing/plans", requireAuth, async (_req: AuthedRequest, res: Response) => {
    const admin = requireAdmin();
    const { data, error } = await admin
      .from("plans")
      .select("id, name, description, price_pkr, duration_days, allowances, features")
      .eq("is_active", true)
      .order("price_pkr", { ascending: true });
    if (error) {
      res.status(500).json({ error: "Could not load plans." });
      return;
    }
    res.json({ plans: data ?? [] });
  });

  // --- caller's entitlement --------------------------------------------
  app.get("/api/billing/entitlement", requireAuth, async (req: AuthedRequest, res: Response) => {
    const admin = requireAdmin();
    const { data, error } = await admin.rpc("get_user_entitlement", { p_user_id: req.userId });
    if (error) {
      res.status(500).json({ error: "Could not resolve your subscription." });
      return;
    }
    res.json({ entitlement: data });
  });

  // --- caller's own payment requests -----------------------------------
  app.get("/api/billing/payments", requireAuth, async (req: AuthedRequest, res: Response) => {
    const admin = requireAdmin();
    const { data, error } = await admin
      .from("payment_requests")
      .select("*")
      .eq("user_id", req.userId)
      .order("created_at", { ascending: false });
    if (error) {
      res.status(500).json({ error: "Could not load your payment requests." });
      return;
    }
    res.json({ payments: (data ?? []) as PaymentRequestRow[] });
  });

  // --- submit a JazzCash payment ---------------------------------------
  app.post("/api/billing/payments", requireAuth, async (req: AuthedRequest, res: Response) => {
    const userId = req.userId!;
    const admin = requireAdmin();

    const txnRef = typeof req.body?.submitted_transaction_ref === "string"
      ? req.body.submitted_transaction_ref.trim().slice(0, 100)
      : null;
    const paymentDateRaw = String(req.body?.payment_date || "").trim();
    const receiptBase64 = typeof req.body?.receipt_base64 === "string" ? req.body.receipt_base64 : null;
    const receiptMime = String(req.body?.receipt_mime_type || "");

    if (paymentDateRaw && !isValidDate(paymentDateRaw)) {
      res.status(400).json({ error: "Invalid payment_date. Use YYYY-MM-DD." });
      return;
    }
    if (paymentDateRaw && new Date(`${paymentDateRaw}T00:00:00Z`) > new Date()) {
      res.status(400).json({ error: "payment_date cannot be in the future." });
      return;
    }

    // One pending request per user (mirrors the partial unique index).
    const { data: existingPending } = await admin
      .from("payment_requests")
      .select("id")
      .eq("user_id", req.userId)
      .eq("status", "pending")
      .maybeSingle();
    if (existingPending) {
      res.status(409).json({ error: "You already have a pending payment request." });
      return;
    }

    // Price comes from the database, never the client.
    const { data: plan, error: planError } = await admin
      .from("plans")
      .select("id, price_pkr")
      .eq("id", "pro")
      .eq("is_active", true)
      .maybeSingle();
    if (planError || !plan) {
      res.status(503).json({ error: "Pro plan is not available right now." });
      return;
    }

    const paymentReference = generatePaymentReference(req.userId!);
    const { data: created, error: insertError } = await admin
      .from("payment_requests")
      .insert({
        user_id: req.userId,
        plan_id: plan.id,
        expected_amount_pkr: plan.price_pkr,
        payment_reference: paymentReference,
        submitted_transaction_ref: txnRef || null,
        payment_date: paymentDateRaw || null,
        status: "pending",
      })
      .select("*")
      .single();
    if (insertError || !created) {
      res.status(500).json({ error: "Could not submit the payment request." });
      return;
    }

    if (req.body?.receipt_base64 && RECEIPT_MIME[req.body?.receipt_mime_type]) {
      const path = await uploadReceipt(
        req.userId!,
        created.id,
        req.body.receipt_base64,
        req.body.receipt_mime_type,
      );
      if (path) {
        await admin.from("payment_requests").update({ receipt_storage_path: path }).eq("id", created.id);
        created.receipt_storage_path = path;
      }
    }

    await admin.from("billing_audit_events").insert({
      event_type: "payment_submitted",
      actor_user_id: req.userId,
      target_user_id: req.userId,
      payment_request_id: created.id,
      metadata: { payment_reference: paymentReference, expected_amount_pkr: plan.price_pkr },
    });

    res.status(201).json({ payment: created as PaymentRequestRow });
  });

  // --- OWNER: list payment requests ------------------------------------
  app.get("/api/billing/admin/payments", requireOwner, async (req: AdminAuthedRequest, res: Response) => {
    const admin = requireAdmin();
    const status = typeof req.query.status === "string" ? req.query.status : "";
    if (status && !PAYMENT_STATUSES.includes(status as (typeof PAYMENT_STATUSES)[number])) {
      res.status(400).json({ error: "Invalid status filter." });
      return;
    }
    let query = admin
      .from("payment_requests")
      .select("*")
      .order("created_at", { ascending: false })
      .limit(200);
    if (status) query = query.eq("status", status);
    const { data, error } = await query;
    if (error) {
      res.status(500).json({ error: "Could not load payment requests." });
      return;
    }
    const payments = (data ?? []) as PaymentRequestRow[];

    // Attach the submitter's email for the review UI.
    const userIds = [...new Set(payments.map((p) => p.user_id))];
    const emails: Record<string, string | null> = {};
    if (userIds.length) {
      const { data: users } = await admin.auth.admin.listUsers({ perPage: 1000 });
      for (const u of users?.users ?? []) {
        if (userIds.includes(u.id)) emails[u.id] = u.email ?? null;
      }
    }
    res.json({ payments: payments.map((p) => ({ ...p, user_email: emails[p.user_id] ?? null })) });
  });

  // --- owner: approve ---------------------------------------------------
  app.post("/api/billing/admin/payments/:id/approve", requireOwner, async (req: AdminAuthedRequest, res: Response) => {
    const admin = requireAdmin();
    const { data, error } = await admin.rpc("approve_payment_request", {
      p_payment_request_id: req.params.id,
      p_actor_id: req.userId,
    });
    if (error) {
      res.status(500).json({ error: "Could not approve the payment." });
      return;
    }
    const result = data as { success?: boolean; error?: string } | null;
    if (!result?.success) {
      res.status(400).json({ error: result?.error || "Could not approve the payment." });
      return;
    }
    res.json({ ok: true, result });
  });

  // --- owner: reject ----------------------------------------------------
  app.post("/api/billing/admin/payments/:id/reject", requireOwner, async (req: AdminAuthedRequest, res: Response) => {
    const reason = String(req.body?.reason || "").trim();
    if (reason.length < 3) {
      res.status(400).json({ error: "A rejection reason of at least 3 characters is required." });
      return;
    }
    const admin = requireAdmin();
    const { data, error } = await admin.rpc("reject_payment_request", {
      p_payment_request_id: req.params.id,
      p_rejection_reason: reason,
      p_actor_id: req.userId,
    });
    if (error) {
      res.status(500).json({ error: "Could not reject the payment." });
      return;
    }
    const result = data as { success?: boolean; error?: string } | null;
    if (!result?.success) {
      res.status(400).json({ error: result?.error || "Could not reject the payment." });
      return;
    }
    res.json({ ok: true, result });
  });

  // --- owner: billing audit log ----------------------------------------
  app.get("/api/billing/admin/audit", requireOwner, async (_req: AdminAuthedRequest, res: Response) => {
    const admin = requireAdmin();
    const { data, error } = await admin
      .from("billing_audit_events")
      .select("*")
      .order("created_at", { ascending: false })
      .limit(100);
    if (error) {
      res.status(500).json({ error: "Could not load the billing audit log." });
      return;
    }
    res.json({ events: data ?? [] });
  });

  // --- owner: receipt preview (short-lived signed URL) ------------------
  app.get("/api/billing/admin/payments/:id/receipt", requireOwner, async (req: Request, res: Response) => {
    const admin = requireAdmin();
    const { data: payment, error } = await admin
      .from("payment_requests")
      .select("receipt_storage_path")
      .eq("id", req.params.id)
      .maybeSingle();
    if (error || !payment?.receipt_storage_path) {
      res.status(404).json({ error: "No receipt for this payment." });
      return;
    }
    const { data: signed, error: signError } = await admin.storage
      .from("payment-receipts")
      .createSignedUrl(payment.receipt_storage_path, 120);
    if (signError || !signed?.signedUrl) {
      res.status(500).json({ error: "Could not create a receipt link." });
      return;
    }
    res.json({ url: signed.signedUrl });
  });
}
