/**
 * JARVIS — local memory operations, scoped per user.
 *
 * Replaces the Mem0 REST API wrapper with the application's native
 * per-user scoped memory store. All operations use the verified user
 * scope derived from Supabase authentication, so memories are never
 * shared across accounts.
 *
 * The backend routes already resolve a `memoryScope` on the request
 * via `requireMemoryScope` middleware. This module uses that scope
 * to key all local-memory operations.
 */
import { Memory } from "../src/lib/memoryTypes";
import { loadScopedMemories, saveScopedMemories, clearScopedMemories } from "../memory/legacyMemoryStore";

/** Scope used when Supabase is not configured (local single-user install). */
export const LOCAL_SCOPE_ID = "jarvis_user_local";

/** Load memories for the authenticated user's scope. */
export async function recallLocalMemory(query: string, limit = 10, scopeId: string = "jarvis_user_local"): Promise<Memory[]> {
  try {
    const memories = await loadScopedMemories(scopeId);
    // Simple query-based filtering
    if (!query) return memories;
    const lowerQuery = query.toLowerCase();
    return memories.filter((m) => m.text.toLowerCase().includes(lowerQuery));
  } catch (error) {
    console.error("[Memory] recallLocalMemory failed:", error);
    return [];
  }
}

/** Store memories derived from a conversation, for the authenticated user only.
 * Only saves user messages (role === "user"), not assistant responses. */
export async function rememberLocalConversation(scopeId: string, messages: Array<{ role: string; content: string }>): Promise<void> {
  try {
    // Ensure the scope file exists with current memories
    const currentMemories = await loadScopedMemories(scopeId);
    const updatedMemories = [...currentMemories];
    
    // Add new memories from USER messages only (filter out assistant responses)
    const timestamp = new Date().toISOString();
    messages
      .filter(msg => msg.role === "user")
      .forEach((msg) => {
        const trimmed = msg.content.trim();
        if (!trimmed) return;
        // Check if memory already exists
        const alreadyExists = updatedMemories.some(
          (m) => m.text.toLowerCase() === trimmed.toLowerCase() && m.category === "preference"
        );
        if (!alreadyExists) {
          updatedMemories.push({
            id: Math.random().toString(36).substring(2, 11),
            category: "preference",
            text: trimmed,
            createdAt: timestamp,
            updatedAt: timestamp
          });
        }
      });
    
    await saveScopedMemories(scopeId, updatedMemories);
  } catch (error) {
    console.error("[Memory] rememberLocalConversation failed:", error);
  }
}

/** Fetch the memories a user can browse and manage. */
export async function listMemories(scopeId: string, limit = 50): Promise<Memory[]> {
  try {
    const memories = await loadScopedMemories(scopeId);
    return memories.slice(0, limit);
  } catch (error) {
    console.error("[Memory] listMemories failed:", error);
    return [];
  }
}

/** Delete one memory by id for the authenticated user only. */
export async function deleteLocalMemory(scopeId: string, memoryId: string): Promise<void> {
  try {
    const memories = await loadScopedMemories(scopeId);
    const updated = memories.filter((m) => m.id !== memoryId);
    await saveScopedMemories(scopeId, updated);
  } catch (error) {
    console.error("[Memory] deleteLocalMemory failed:", error);
  }
}

/** Delete every memory for the authenticated user's identity only. */
export async function deleteAllLocalMemories(scopeId: string): Promise<void> {
  try {
    await clearScopedMemories(scopeId);
  } catch (error) {
    console.error("[Memory] deleteAllLocalMemories failed:", error);
  }
}

/** Check if memory is configured/available for the given scope. */
export async function memoryConfigured(scopeId: string): Promise<boolean> {
  try {
    const memories = await loadScopedMemories(scopeId);
    return !!memories.length || true; // Local memory is always "configured" as it's file-based
  } catch {
    return true; // If we can't read it, assume it exists/configured
  }
}

/** Error thrown when local memory operations fail. */
export class LocalMemoryUnavailableError extends Error {
  constructor(message = "Local memory is temporarily unavailable.") {
    super(message);
    this.name = "LocalMemoryUnavailableError";
  }
}

/** @deprecated Use recallLocalMemory instead. */
export async function recallMemory(query: string, limit = 10, scopeId: string = "jarvis_user_local"): Promise<Memory[]> {
  return recallLocalMemory(query, limit, scopeId);
}

/** @deprecated Use rememberLocalConversation instead. */
export async function rememberConversation(scopeId: string, messages: Array<{ role: string; content: string }>): Promise<void> {
  return rememberLocalConversation(scopeId, messages);
}

/** @deprecated Use deleteLocalMemory instead. */
export async function deleteMemory(scopeId: string, memoryId: string): Promise<void> {
  return deleteLocalMemory(scopeId, memoryId);
}

/** @deprecated Use deleteAllLocalMemories instead. */
export async function deleteAllMemories(scopeId: string): Promise<void> {
  return deleteAllLocalMemories(scopeId);
}

/** @deprecated Use LocalMemoryUnavailableError instead. */
export class Mem0UnavailableError extends LocalMemoryUnavailableError {
  constructor(message = "Memory is temporarily unavailable.") {
    super(message);
    this.name = "Mem0UnavailableError";
  }
}

/** @deprecated Use memoryConfigured instead. */
export const mem0Configured = memoryConfigured;