/**
 * JARVIS — protected workspace routes.
 *
 * Connections, files and dashboard data. Each handler resolves the caller from
 * a verified session and scopes every query by their user id. Ownership is
 * checked server-side before any connection is used or file touched: a
 * connection id or file name supplied by the browser is never trusted.
 */
import type { Express, Request, Response } from "express";
import fs from "fs";
import { requireAuth, type AuthedRequest } from "./authRoutes";
import { supabase, requireAdmin } from "./supabaseClient";
import { appEvents } from "../shared/appEvents";
import { composioEntityId as composioEntityIdFor } from "./composioTools";

/**
 * Composio settings are read LAZILY, on every request.
 *
 * A module-level `process.env.X` read would be evaluated while the import
 * graph is still being wired up, before server.ts loads .env — silently
 * capturing an empty value even when the key is present in .env. Reading at
 * request time always sees the final environment.
 */
function composioBaseUrl(): string {
  return process.env.COMPOSIO_BASE_URL || "https://backend.composio.dev";
}

function composioApiKey(): string {
  return (process.env.COMPOSIO_API_KEY || "").trim();
}

export function isComposioConfigured(): boolean {
  return composioApiKey().length > 0;
}

function composioHeaders(): Record<string, string> {
  return { "x-api-key": composioApiKey(), "Content-Type": "application/json" };
}

/**
 * Composio v3 calls every app a "toolkit". This maps a toolkit object onto the
 * flat shape the marketplace UI consumes (key/name/description/logo/...).
 */
function normalizeToolkit(toolkit: any): {
  key: string;
  name: string;
  description: string;
  logo: string;
  categories: string[];
  auth_scheme: string;
  tools_count: number;
  triggers_count: number;
  no_auth: boolean;
} {
  const meta = toolkit?.meta ?? {};
  const categories = Array.isArray(meta.categories)
    ? meta.categories
        .map((c: any) => (typeof c === "string" ? c : c?.slug ?? c?.id ?? c?.name))
        .filter((c: any) => typeof c === "string" && c.length > 0)
    : [];
  const authSchemes = Array.isArray(toolkit?.auth_schemes) ? toolkit.auth_schemes : [];
  const auth_scheme = authSchemes.length > 0 ? String(authSchemes[0]) : toolkit?.no_auth ? "NO_AUTH" : "";
  return {
    key: String(toolkit?.slug || ""),
    name: String(toolkit?.name || toolkit?.slug || ""),
    description: String(meta?.description || ""),
    logo: String(meta?.logo || ""),
    categories,
    auth_scheme,
    tools_count: Number(meta?.tools_count) || 0,
    triggers_count: Number(meta?.triggers_count) || 0,
    no_auth: Boolean(toolkit?.no_auth),
  };
}

/** Cache for marketplace data to avoid repeated API calls. */
let marketplaceCache: { data: { apps: any[]; categories: string[] }; expiresAt: number } | null = null;
const MARKETPLACE_CACHE_TTL_MS = 10 * 60 * 1000; // 10 minutes

async function fetchComposioMarketplace(): Promise<{ apps: any[]; categories: string[] }> {
  if (!isComposioConfigured()) throw new Error("Composio is not configured.");
  const now = Date.now();
  if (marketplaceCache && marketplaceCache.expiresAt > now) {
    return marketplaceCache.data;
  }

  // Composio paginates toolkits; collect every page (bounded to stay safe).
  const toolkits: any[] = [];
  let cursor: string | null = null;
  for (let page = 0; page < 5; page++) {
    const url = new URL(`${composioBaseUrl()}/api/v3/toolkits`);
    url.searchParams.set("limit", "1000");
    if (cursor) url.searchParams.set("cursor", cursor);
    const res = await fetch(url.toString(), { headers: composioHeaders(), cache: "no-store" });
    if (!res.ok) throw new Error(`Composio marketplace fetch failed: ${res.status}`);
    const data = await res.json();
    const items = Array.isArray(data?.items) ? data.items : Array.isArray(data) ? data : [];
    toolkits.push(...items);
    cursor = data?.next_cursor ?? null;
    if (!cursor || items.length === 0) break;
  }

  const apps = toolkits.map(normalizeToolkit).filter((app) => app.key);
  const categorySet = new Set<string>();
  for (const app of apps) {
    for (const cat of app.categories) categorySet.add(cat);
  }
  const result = { apps, categories: Array.from(categorySet).sort() };
  marketplaceCache = { data: result, expiresAt: now + MARKETPLACE_CACHE_TTL_MS };
  return result;
}

async function fetchComposioAppDetails(appKey: string): Promise<any> {
  if (!isComposioConfigured()) throw new Error("Composio is not configured.");
  const slug = appKey.trim().toLowerCase();
  const res = await fetch(`${composioBaseUrl()}/api/v3/toolkits/${encodeURIComponent(slug)}`, {
    headers: composioHeaders(),
    cache: "no-store",
  });
  if (!res.ok) throw new Error(`Composio app details fetch failed: ${res.status}`);
  const toolkit = await res.json();
  const app = normalizeToolkit(toolkit);

  // The tools ("actions") for a toolkit are a separate, paginated resource.
  let tools: Array<{ name: string; description: string }> = [];
  try {
    const toolsRes = await fetch(
      `${composioBaseUrl()}/api/v3/tools?toolkit_slug=${encodeURIComponent(slug)}&limit=1000`,
      { headers: composioHeaders(), cache: "no-store" },
    );
    if (toolsRes.ok) {
      const toolsData = await toolsRes.json();
      const items = Array.isArray(toolsData?.items) ? toolsData.items : [];
      tools = items.map((t: any) => ({
        name: String(t?.name || t?.slug || ""),
        description: String(t?.description || ""),
      }));
    }
  } catch {
    // Tools are best-effort; the app header still renders without them.
  }

  return { ...app, tools, actions: tools };
}

/**
 * Ensure a Composio-managed auth config exists for the toolkit, creating one on
 * demand. A link (the OAuth consent URL) can only be minted from an auth config.
 */
async function ensureComposioAuthConfig(provider: string): Promise<string> {
  const slug = provider.trim().toLowerCase();

  const listRes = await fetch(
    `${composioBaseUrl()}/api/v3/auth_configs?toolkit_slug=${encodeURIComponent(slug)}&is_composio_managed=true&limit=50`,
    { headers: composioHeaders(), cache: "no-store" },
  );
  if (listRes.ok) {
    const data = await listRes.json();
    const items = Array.isArray(data?.items) ? data.items : [];
    const enabled = items.find((i: any) => String(i?.status || "").toUpperCase() === "ENABLED") ?? items[0];
    const existingId = enabled?.id ?? enabled?.auth_config?.id ?? enabled?.nanoid;
    if (existingId) return String(existingId);
  }

  const createRes = await fetch(`${composioBaseUrl()}/api/v3/auth_configs`, {
    method: "POST",
    headers: composioHeaders(),
    body: JSON.stringify({
      toolkit: { slug },
      auth_config: { type: "use_composio_managed_auth" },
    }),
    cache: "no-store",
  });
  if (!createRes.ok) {
    const text = await createRes.text().catch(() => "");
    throw new Error(`Could not prepare the ${provider} auth config: ${createRes.status} ${text}`);
  }
  const created = await createRes.json();
  const id = created?.auth_config?.id ?? created?.id ?? created?.auth_config_id;
  if (!id) throw new Error(`Composio did not return an auth config for ${provider}.`);
  return String(id);
}

async function initiateComposioConnection(userId: string, provider: string, state: string): Promise<{ redirectUrl: string; connectionId: string }> {
  if (!isComposioConfigured()) throw new Error("Composio is not configured.");
  const appUrl = (process.env.EVA_APP_URL || `http://127.0.0.1:${process.env.EVA_PORT || 3000}`).replace(/\/$/, "");
  const authConfigId = await ensureComposioAuthConfig(provider);
  const res = await fetch(`${composioBaseUrl()}/api/v3/connected_accounts/link`, {
    method: "POST",
    headers: composioHeaders(),
    body: JSON.stringify({
      auth_config_id: authConfigId,
      user_id: composioEntityId(userId),
      callback_url: `${appUrl}/api/workspace/integrations/callback?state=${encodeURIComponent(state)}`,
    }),
    cache: "no-store",
  });
  if (!res.ok) {
    const text = await res.text().catch(() => "");
    throw new Error(`Composio connection initiate failed: ${res.status} ${text}`);
  }
  const data = await res.json();
  const redirectUrl = String(data?.redirect_url || "");
  if (!redirectUrl) throw new Error("Composio did not return a redirect URL.");
  return { redirectUrl, connectionId: String(data?.connected_account_id || "") };
}

/** Stable per-user identity inside Composio. */
function composioEntityId(userId: string): string {
  return composioEntityIdFor(userId);
}

/**
 * Reconcile our connection table with Composio's connected accounts for this
 * user. Called after an OAuth redirect returns to the app (the browser landing
 * has no bearer token, so the SPA re-syncs once it is authenticated again).
 */
async function syncComposioConnections(userId: string, client: any): Promise<number> {
  const res = await fetch(
    `${composioBaseUrl()}/api/v3/connected_accounts?user_ids=${encodeURIComponent(composioEntityId(userId))}&limit=100`,
    { headers: composioHeaders(), cache: "no-store" },
  );
  if (!res.ok) throw new Error(`Composio connection list failed: ${res.status}`);
  const data = await res.json();
  const items = Array.isArray(data?.items) ? data.items : [];

  // One read up front so an app only logs "connected" when it is genuinely new.
  const { data: existingRows } = await client
    .from("integration_connections")
    .select("provider,status")
    .eq("user_id", userId);
  const previous = new Map<string, string>(
    (existingRows ?? []).map((row: any) => [String(row.provider), String(row.status)]),
  );

  let changed = 0;
  for (const account of items) {
    const provider = String(account?.toolkit?.slug || "").trim().toLowerCase();
    if (!provider) continue;
    const rawStatus = String(account?.status || "").toUpperCase();
    const status = rawStatus === "ACTIVE" ? "connected" : rawStatus === "FAILED" || rawStatus === "EXPIRED" ? "error" : "pending";
    const connectionId = String(account?.id || "");
    const { error } = await client
      .from("integration_connections")
      .upsert(
        { user_id: userId, provider, connection_id: connectionId, status, metadata: {}, updated_at: new Date().toISOString() },
        { onConflict: "user_id,provider" },
      );
    if (error) continue;
    changed++;
    if (status === "connected" && previous.get(provider) !== "connected") {
      await logActivity(client, userId, "app.connected", `Connected ${provider}`);
    }
  }
  return changed;
}

/** Client scoped to the caller's own token, so RLS enforces their isolation. */
async function userClient(accessToken: string) {
  const { createClient } = await import("@supabase/supabase-js");
  return createClient(process.env.SUPABASE_URL || "", process.env.SUPABASE_ANON_KEY || "", {
    auth: { persistSession: false, autoRefreshToken: false },
    global: { headers: { Authorization: `Bearer ${accessToken}` } },
  });
}

function tokenOf(req: Request): string {
  return String(req.headers["authorization"] || "").replace(/^Bearer\s+/i, "").trim();
}

// ---- Dashboard activity ---------------------------------------------------
// Coarse, non-sensitive timeline rows for the "Recent activity" card.
// Message content and credentials are deliberately never logged here.
async function logActivity(client: any, userId: string, eventType: string, summary: string): Promise<void> {
  const { error } = await client.from("user_activity").insert({
    user_id: userId,
    event_type: eventType,
    summary: summary.slice(0, 200),
  });
  if (error) console.warn("[Workspace] activity row skipped:", error.message);
}

// ---- User file storage ----------------------------------------------------
// File contents live in a private bucket under <uid>/<uuid>/<name>, which is
// exactly the owner-scoped layout the migration's storage policies require
// (they key on the first folder segment). Rows only store metadata.
const USER_FILES_BUCKET = "user-files";
const MAX_STORED_FILE_BYTES = 25 * 1024 * 1024; // keep cloud copies small on purpose

const MIME_BY_EXT: Record<string, string> = {
  pdf: "application/pdf",
  doc: "application/msword",
  docx: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
  xls: "application/vnd.ms-excel",
  xlsx: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
  csv: "text/csv",
  ppt: "application/vnd.ms-powerpoint",
  pptx: "application/vnd.openxmlformats-officedocument.presentationml.presentation",
  txt: "text/plain",
  md: "text/markdown",
  json: "application/json",
  html: "text/html",
  htm: "text/html",
  rtf: "application/rtf",
  odt: "application/vnd.oasis.opendocument.text",
  ods: "application/vnd.oasis.opendocument.spreadsheet",
  odp: "application/vnd.oasis.opendocument.presentation",
  png: "image/png",
  jpg: "image/jpeg",
  jpeg: "image/jpeg",
  gif: "image/gif",
  webp: "image/webp",
  svg: "image/svg+xml",
  bmp: "image/bmp",
  ico: "image/x-icon",
  tiff: "image/tiff",
  zip: "application/zip",
};

function sanitizeFileName(name: string): string {
  const cleaned = name.replace(/[\\/:*?"<>|\u0000-\u001f]/g, "_").trim();
  return cleaned || "file";
}

function mimeForFile(name: string): string {
  const ext = name.split(".").pop()?.toLowerCase() || "";
  return MIME_BY_EXT[ext] || "application/octet-stream";
}

/**
 * Copy a file produced on this machine into the caller's own bucket folder.
 * Returns null (and logs) when the file is absent, empty or oversized, so the
 * caller can fall back to recording metadata only instead of failing the save.
 */
async function uploadToUserBucket(
  client: any,
  userId: string,
  fileName: string,
  localPath: string,
): Promise<{ path: string; size: number } | null> {
  if (!localPath) return null;
  try {
    const stat = await fs.promises.stat(localPath);
    if (!stat.isFile() || stat.size <= 0 || stat.size > MAX_STORED_FILE_BYTES) return null;
    const buffer = await fs.promises.readFile(localPath);
    const objectPath = `${userId}/${crypto.randomUUID()}/${sanitizeFileName(fileName)}`;
    const { error } = await client.storage.from(USER_FILES_BUCKET).upload(objectPath, buffer, {
      contentType: mimeForFile(fileName),
      cacheControl: "3600",
      upsert: false,
    });
    if (error) {
      console.warn("[Workspace] storage upload skipped:", error.message);
      return null;
    }
    return { path: objectPath, size: stat.size };
  } catch (err) {
    console.warn("[Workspace] storage upload skipped:", err instanceof Error ? err.message : String(err));
    return null;
  }
}

export function registerWorkspaceRoutes(app: Express): void {
  // ---- Dashboard aggregate: profile, recent conversations, files, activity --
  app.get("/api/workspace/dashboard", requireAuth, async (req: AuthedRequest, res: Response) => {
    const client = await userClient(tokenOf(req));

    const [profileRes, conversationsRes, filesRes, activityRes, connectionsRes] = await Promise.all([
      client.from("profiles").select("*").eq("id", req.userId).maybeSingle(),
      client.from("conversations").select("id,title,updated_at").order("updated_at", { ascending: false }).limit(6),
      client.from("user_files").select("id,file_name,kind,size_bytes,storage_path,created_at").order("created_at", { ascending: false }).limit(6),
      client.from("user_activity").select("id,event_type,summary,created_at").order("created_at", { ascending: false }).limit(8),
      client.from("integration_connections").select("id,provider,status,created_at").order("created_at", { ascending: false }),
    ]);

    res.json({
      profile: profileRes.data ?? null,
      conversations: conversationsRes.data ?? [],
      files: filesRes.data ?? [],
      activity: activityRes.data ?? [],
      connections: connectionsRes.data ?? [],
    });
  });

  // ---- Conversations ----------------------------------------------------
  app.get("/api/workspace/conversations", requireAuth, async (req: AuthedRequest, res: Response) => {
    const client = await userClient(tokenOf(req));
    const { data, error } = await client
      .from("conversations")
      .select("id,title,created_at,updated_at")
      .order("updated_at", { ascending: false });
    if (error) return res.status(500).json({ error: "Could not load conversations." });
    res.json({ conversations: data ?? [] });
  });

  app.post("/api/workspace/conversations", requireAuth, async (req: AuthedRequest, res: Response) => {
    const client = await userClient(tokenOf(req));
    const title = String(req.body?.title || "New conversation").trim() || "New conversation";
    const { data, error } = await client
      .from("conversations")
      .insert({ user_id: req.userId, title })
      .select("id,title,created_at,updated_at")
      .single();
    if (error) return res.status(500).json({ error: "Could not create the conversation." });
    res.status(201).json({ conversation: data });
    // Emit workspace changed event for real-time UI updates
    appEvents.publish("workspace.changed", { userId: req.userId, type: "conversation_created", conversation: data });
    await logActivity(client, req.userId, "conversation.started", `Started a conversation: ${title}`);
  });

  // Messages are reachable only through a conversation the caller owns.
  app.get("/api/workspace/conversations/:id/messages", requireAuth, async (req: AuthedRequest, res: Response) => {
    const client = await userClient(tokenOf(req));
    const conversationId = req.params.id;

    const { data: conversation } = await client
      .from("conversations")
      .select("id")
      .eq("id", conversationId)
      .maybeSingle();

    if (!conversation) {
      return res.status(404).json({ error: "Conversation not found." });
    }

    const { data, error } = await client
      .from("conversation_messages")
      .select("id,role,content,created_at")
      .eq("conversation_id", conversationId)
      .order("created_at", { ascending: true });

    if (error) return res.status(500).json({ error: "Could not load messages." });
    res.json({ messages: data ?? [] });
  });

  // Append a message to a conversation the caller owns.
  //
  // Ownership is enforced twice: the conversation is looked up through the
  // caller's RLS-scoped client first (404 if it is not theirs), and the insert
  // policy re-checks the parent conversation's owner. Bumping the parent
  // conversation's updated_at is what moves it to the top of the dashboard.
  app.post("/api/workspace/conversations/:id/messages", requireAuth, async (req: AuthedRequest, res: Response) => {
    const client = await userClient(tokenOf(req));
    const conversationId = String(req.params.id || "").trim();
    const role = String(req.body?.role || "").trim();
    const content = String(req.body?.content || "").trim();

    if (role !== "user" && role !== "assistant") {
      return res.status(400).json({ error: "Role must be 'user' or 'assistant'." });
    }
    if (!content) {
      return res.status(400).json({ error: "Message content is required." });
    }

    const { data: conversation, error: convError } = await client
      .from("conversations")
      .select("id,title")
      .eq("id", conversationId)
      .maybeSingle();

    if (convError) return res.status(500).json({ error: "Could not reach the conversation." });
    if (!conversation) return res.status(404).json({ error: "Conversation not found." });

    const { data, error } = await client
      .from("conversation_messages")
      .insert({ conversation_id: conversationId, user_id: req.userId, role, content })
      .select("id,role,content,created_at")
      .single();
    if (error) return res.status(500).json({ error: "Could not save the message." });

    // Surface this conversation first in "Recent conversations".
    await client
      .from("conversations")
      .update({ updated_at: new Date().toISOString() })
      .eq("id", conversationId);

    res.status(201).json({ message: data });
    appEvents.publish("workspace.changed", { userId: req.userId, type: "message_created", conversationId });
    await logActivity(
      client,
      req.userId,
      "message.saved",
      `${role === "user" ? "You sent a message" : "Eva replied"} in "${conversation.title || "New conversation"}"`,
    );
  });

  // ---- Files (metadata + ownership) -------------------------------------
  // Listing is already user-scoped by RLS; the explicit filter documents intent.
  app.get("/api/workspace/files", requireAuth, async (req: AuthedRequest, res: Response) => {
    const client = await userClient(tokenOf(req));
    const { data, error } = await client
      .from("user_files")
      .select("id,file_name,kind,mime_type,size_bytes,storage_path,created_at,updated_at")
      .order("created_at", { ascending: false });
    if (error) return res.status(500).json({ error: "Could not load files." });
    res.json({ files: data ?? [] });
  });

  // Register a generated document. A filename is never proof of ownership —
  // the caller is resolved from the session and the row is theirs alone.
  app.post("/api/workspace/files", requireAuth, async (req: AuthedRequest, res: Response) => {
    const client = await userClient(tokenOf(req));
    const fileName = String(req.body?.fileName || "").trim();
    const storagePath = String(req.body?.storagePath || "").trim();
    const kind = String(req.body?.kind || "document");
    const mimeType = req.body?.mimeType ? String(req.body.mimeType) : null;
    const sizeBytes = Number(req.body?.sizeBytes) || null;

    if (!fileName) return res.status(400).json({ error: "A file name is required." });

    // Copy the real bytes into the private bucket when the file exists on this
    // machine. If it is missing or oversized we still record the metadata, so
    // the workspace lists it either way.
    const upload = await uploadToUserBucket(client, req.userId, fileName, storagePath);
    const storedPath = upload?.path ?? storagePath;
    const storedSize = upload?.size ?? sizeBytes;
    const storedMime = mimeType ?? (upload ? mimeForFile(fileName) : null);

    const { data, error } = await client
      .from("user_files")
      .insert({ user_id: req.userId, file_name: fileName, storage_path: storedPath, kind, mime_type: storedMime, size_bytes: storedSize })
      .select("id,file_name,kind,created_at")
      .single();
    if (error) return res.status(500).json({ error: "Could not record the file." });
    res.status(201).json({ file: data });
    appEvents.publish("workspace.changed", { userId: req.userId, type: "file_created", file: data });
    await logActivity(client, req.userId, "file.created", `Added ${fileName}`);
  });

  // Deleting or overwriting a document requires owning that exact row.
  app.delete("/api/workspace/files/:id", requireAuth, async (req: AuthedRequest, res: Response) => {
    const client = await userClient(tokenOf(req));
    const { data: file } = await client
      .from("user_files")
      .select("file_name,storage_path")
      .eq("id", req.params.id)
      .maybeSingle();

    const { error, count } = await client
      .from("user_files")
      .delete({ count: "exact" })
      .eq("id", req.params.id);

    if (error) return res.status(500).json({ error: "Could not delete the file." });
    if (count === 0) return res.status(404).json({ error: "File not found." });

    // Drop the stored copy too; RLS only allows the owner to remove their path.
    const objectPath = String(file?.storage_path || "");
    if (objectPath.startsWith(`${req.userId}/`)) {
      const { error: removeError } = await client.storage.from(USER_FILES_BUCKET).remove([objectPath]);
      if (removeError) console.warn("[Workspace] storage delete skipped:", removeError.message);
    }

    res.json({ ok: true });
    appEvents.publish("workspace.changed", { userId: req.userId, type: "file_deleted", fileId: req.params.id });
    await logActivity(client, req.userId, "file.deleted", `Removed ${file?.file_name || "a document"}`);
  });

  // Signed URL for a stored copy. Rows without an owner-scoped object path
  // (metadata-only records) report why a download is unavailable.
  app.get("/api/workspace/files/:id/download", requireAuth, async (req: AuthedRequest, res: Response) => {
    const client = await userClient(tokenOf(req));
    const { data: file } = await client
      .from("user_files")
      .select("file_name,storage_path")
      .eq("id", req.params.id)
      .maybeSingle();

    if (!file) return res.status(404).json({ error: "File not found." });

    const objectPath = String(file.storage_path || "");
    if (!objectPath.startsWith(`${req.userId}/`)) {
      return res.status(410).json({ error: "This file is kept on your PC only and has no cloud copy yet." });
    }

    const { data: signed, error } = await client.storage.from(USER_FILES_BUCKET).createSignedUrl(objectPath, 600);
    if (error || !signed?.signedUrl) {
      console.error("[Workspace] signed URL failed:", error?.message);
      return res.status(502).json({ error: "Could not create a download link." });
    }
    res.json({ url: signed.signedUrl, fileName: file.file_name });
  });

  // ---- Composio connections ---------------------------------------------
  // Composio remains the credential authority; this table records which
  // connected account belongs to which JARVIS user.
  app.get("/api/workspace/connections", requireAuth, async (req: AuthedRequest, res: Response) => {
    const client = await userClient(tokenOf(req));
    const { data, error } = await client
      .from("integration_connections")
      .select("id,provider,connection_id,status,metadata,created_at,updated_at")
      .order("created_at", { ascending: false });
    if (error) return res.status(500).json({ error: "Could not load connections." });
    res.json({ connections: data ?? [] });
  });

  app.post("/api/workspace/connections", requireAuth, async (req: AuthedRequest, res: Response) => {
    const client = await userClient(tokenOf(req));
    const provider = String(req.body?.provider || "").trim();
    const connectionId = String(req.body?.connectionId || "").trim();
    const metadata = req.body?.metadata && typeof req.body.metadata === "object" ? req.body.metadata : {};

    if (!provider || !connectionId) {
      return res.status(400).json({ error: "Provider and connection id are required." });
    }

    const { data, error } = await client
      .from("integration_connections")
      .upsert(
        { user_id: req.userId, provider, connection_id: connectionId, status: "connected", metadata },
        { onConflict: "user_id,provider" },
      )
      .select("id,provider,status,created_at")
      .single();
    if (error) return res.status(500).json({ error: "Could not save the connection." });
    res.status(201).json({ connection: data });
    appEvents.publish("workspace.changed", { userId: req.userId, type: "connection_updated", connection: data });
  });

  app.delete("/api/workspace/connections/:id", requireAuth, async (req: AuthedRequest, res: Response) => {
    const client = await userClient(tokenOf(req));
    const { data: existing } = await client
      .from("integration_connections")
      .select("provider")
      .eq("id", req.params.id)
      .maybeSingle();

    const { error, count } = await client
      .from("integration_connections")
      .delete({ count: "exact" })
      .eq("id", req.params.id);
    if (error) return res.status(500).json({ error: "Could not disconnect." });
    if (count === 0) return res.status(404).json({ error: "Connection not found." });
    res.json({ ok: true });
    appEvents.publish("workspace.changed", { userId: req.userId, type: "connection_deleted", connectionId: req.params.id });
    await logActivity(client, req.userId, "app.disconnected", `Disconnected ${existing?.provider || "an app"}`);
  });

  // ---- Execute a Composio tool ------------------------------------------
  // Ownership chain: verified user -> their stored connection -> the tool.
  // A connection id from the frontend is only used to locate the caller's OWN
  // row; it is never used directly.
  app.post("/api/workspace/tools/execute", requireAuth, async (req: AuthedRequest, res: Response) => {
    if (!isComposioConfigured()) {
      return res.status(503).json({ error: "Integrations are not configured on this instance." });
    }
    const client = await userClient(tokenOf(req));
    const provider = String(req.body?.provider || "").trim();
    const tool = String(req.body?.tool || "").trim();
    const args = req.body?.args && typeof req.body.args === "object" ? req.body.args : {};

    if (!provider || !tool) {
      return res.status(400).json({ error: "Provider and tool are required." });
    }

    // 1. Find the caller's connection for this provider — RLS guarantees it
    //    is theirs and nobody else's.
    const { data: connection, error: connError } = await client
      .from("integration_connections")
      .select("connection_id,status")
      .eq("user_id", req.userId)
      .eq("provider", provider)
      .maybeSingle();

    if (connError || !connection) {
      return res.status(404).json({ error: `Connect ${provider} first, then try again.` });
    }
    if (connection.status !== "connected") {
      return res.status(409).json({ error: `Your ${provider} connection is not active.` });
    }

    // 2. Execute the tool through Composio with the caller's connection.
    try {
      const result = await fetch(`${composioBaseUrl()}/api/v3/tools/execute/${encodeURIComponent(tool)}`, {
        method: "POST",
        headers: composioHeaders(),
        body: JSON.stringify({
          connected_account_id: connection.connection_id,
          // Composio v3 requires the user id the connection was created
          // under, in addition to the connected account id.
          user_id: composioEntityId(req.userId!),
          arguments: args,
        }),
        cache: "no-store",
      });

      if (!result.ok) {
        return res.status(502).json({ error: `${provider} did not respond. Try again in a moment.` });
      }
      const data = await result.json().catch(() => ({}));
      res.json({ ok: true, result: data });
    } catch {
      res.status(502).json({ error: `${provider} is unavailable right now.` });
    }
  });

  // ---- Composio Marketplace -----------------------------------------------
  // Discover available integrations, categories, and initiate OAuth.
  app.get("/api/workspace/integrations/marketplace", requireAuth, async (_req: AuthedRequest, res: Response) => {
    if (!isComposioConfigured()) {
      return res.status(503).json({ error: "Integrations are not configured on this instance." });
    }
    try {
      const { apps, categories } = await fetchComposioMarketplace();
      res.json({ apps, categories });
    } catch (err) {
      console.error("[Workspace] Marketplace fetch failed:", err);
      res.status(502).json({ error: err instanceof Error ? err.message : "Could not load marketplace." });
    }
  });

  app.get("/api/workspace/integrations/marketplace/:provider", requireAuth, async (req: AuthedRequest, res: Response) => {
    if (!isComposioConfigured()) {
      return res.status(503).json({ error: "Integrations are not configured on this instance." });
    }
    const provider = String(req.params.provider || "").trim().toLowerCase();
    if (!provider) return res.status(400).json({ error: "Provider is required." });
    try {
      const details = await fetchComposioAppDetails(provider);
      res.json(details);
    } catch (err) {
      console.error("[Workspace] App details fetch failed:", err);
      res.status(502).json({ error: err instanceof Error ? err.message : "Could not load app details." });
    }
  });

  app.post("/api/workspace/integrations/connect", requireAuth, async (req: AuthedRequest, res: Response) => {
    if (!isComposioConfigured()) {
      return res.status(503).json({ error: "Integrations are not configured on this instance." });
    }
     const provider = String(req.body?.provider || "").trim().toLowerCase();
     if (!provider) return res.status(400).json({ error: "Provider is required." });
     try {
       const state = (await import("node:crypto")).randomBytes(16).toString("hex");
       const { redirectUrl, connectionId } = await initiateComposioConnection(req.userId, provider, state);
       // Store a pending connection row so we can complete it on callback
       const client = await userClient(tokenOf(req));
       await client.from("integration_connections").upsert(
         { user_id: req.userId, provider, connection_id: connectionId, status: "pending", metadata: { state } },
         { onConflict: "user_id,provider" },
       );
       res.json({ redirectUrl, connectionId, state });
     } catch (err) {
      console.error("[Workspace] Connect initiate failed:", err);
      res.status(502).json({ error: err instanceof Error ? err.message : "Could not start connection." });
    }
  });

  // Reconcile the caller's stored connections with Composio's live connected
  // accounts. The OAuth redirect lands back in the SPA (which has no bearer
  // token at that instant), so the authenticated SPA calls this once it loads.
  app.post("/api/workspace/integrations/reconcile", requireAuth, async (req: AuthedRequest, res: Response) => {
    if (!isComposioConfigured()) {
      return res.status(503).json({ error: "Integrations are not configured on this instance." });
    }
    try {
      const client = await userClient(tokenOf(req));
      const changed = await syncComposioConnections(req.userId, client);
      if (changed > 0) {
        appEvents.publish("workspace.changed", { userId: req.userId, type: "connection_updated" });
      }
      res.json({ ok: true, changed });
    } catch (err) {
      console.error("[Workspace] Reconcile failed:", err);
      res.status(502).json({ error: err instanceof Error ? err.message : "Could not sync integrations." });
    }
  });

  // Callback handler for Composio OAuth.
  //
  // This endpoint is deliberately UNauthenticated: the OAuth flow completes in
  // the user's external browser, which has no bearer token. Safety comes from
  // the random, single-use `state` nonce that was generated when the connection
  // was started and stored on the pending row. Only that exact user's pending
  // connection can be completed. The browser is then sent back to the app.
  app.get("/api/workspace/integrations/callback", async (req: Request, res: Response) => {
    const state = String(req.query.state || "").trim();
    const connectionId = String(
      req.query.connection_id || req.query.connected_account_id || "",
    ).trim();
    const rawStatus = String(req.query.status || "").trim().toUpperCase();
    const appUrl = process.env.EVA_APP_URL || `http://127.0.0.1:${process.env.EVA_PORT || 3000}`;
    const back = `${appUrl.replace(/\/$/, "")}/integrations`;

    if (!state) return res.redirect(`${back}?connected=error`);

    try {
      const admin = requireAdmin();
      // Locate the pending row that carries this exact state nonce.
      const { data: rows } = await admin
        .from("integration_connections")
        .select("id,user_id,provider,metadata")
        .eq("status", "pending");
      const match = (rows ?? []).find(
        (r: any) => (r?.metadata as { state?: string } | null)?.state === state,
      );
      if (!match) return res.redirect(`${back}?connected=error`);

      let newStatus: "connected" | "error" | "pending" = "pending";
      if (["CONNECTED", "SUCCESS", "ACTIVE", "INITIALIZED"].includes(rawStatus)) {
        newStatus = "connected";
      } else if (["FAILED", "ERROR", "EXPIRED"].includes(rawStatus)) {
        newStatus = "error";
      }

      // If the provider did not tell us a definitive status, ask Composio.
      if (connectionId && newStatus === "pending" && isComposioConfigured()) {
        try {
          const r = await fetch(
            `${composioBaseUrl()}/api/v3/connected_accounts/${encodeURIComponent(connectionId)}`,
            { headers: composioHeaders(), cache: "no-store" },
          );
          if (r.ok) {
            const body = await r.json();
            const st = String(body?.status || "").toUpperCase();
            newStatus = st === "ACTIVE"
              ? "connected"
              : st === "FAILED" || st === "EXPIRED"
                ? "error"
                : "pending";
          }
        } catch {
          /* keep pending — reconcile will settle it later */
        }
      }

      await admin
        .from("integration_connections")
        .update({
          status: newStatus,
          ...(connectionId ? { connection_id: connectionId } : {}),
          updated_at: new Date().toISOString(),
          metadata: { state: null },
        })
        .eq("id", match.id);

      appEvents.publish("workspace.changed", {
        userId: match.user_id,
        type: "connection_updated",
        provider: match.provider,
        status: newStatus,
      });

      return res.redirect(`${back}?connected=${newStatus}&provider=${encodeURIComponent(match.provider)}`);
    } catch (err) {
      console.error("[Workspace] Callback failed:", err);
      return res.redirect(`${back}?connected=error`);
    }
  });
}
