import { GoogleGenAI, Type } from "@google/genai";
import { Memory, MemoryTransaction } from "./src/lib/memoryTypes";
import { loadScopedMemories, saveScopedMemories } from "./memory/legacyMemoryStore";
import { LOCAL_SCOPE_ID } from "./auth/memoryScope";

// Memories are partitioned by user scope. Callers that have not resolved a
// scope fall back to the single local scope, which is correct on a local
// install and keeps the original single-file behaviour for existing callers.
export async function loadMemories(scopeId: string = LOCAL_SCOPE_ID): Promise<Memory[]> {
  return loadScopedMemories(scopeId || LOCAL_SCOPE_ID);
}

export async function saveMemories(scopeId: string | Memory[], memories?: Memory[]): Promise<void> {
  // Accept both (scopeId, memories) and the legacy (memories) signature.
  const [scope, list] = typeof scopeId === "string"
    ? [scopeId || LOCAL_SCOPE_ID, memories || []]
    : [LOCAL_SCOPE_ID, scopeId];
  await saveScopedMemories(scope, list as Memory[]);
}

// Format memory core to system instruction injections
export function formatSystemInstructionsWithMemories(baseInstruction: string, memories: Memory[]): string {
  if (memories.length === 0) {
    return baseInstruction +
      "\n\n=== EVA PERSISTENT CONTEXT ===\n" +
      "No durable user context is stored yet. Do not ask for a biography, preferences, routines, or personal details just to populate memory. Use facts only when the user shares them naturally and they matter to future continuity.\n" +
      "================================\n";
  }

  // Group by category
  const grouped: Record<string, string[]> = {};
  memories.forEach((m) => {
    grouped[m.category] = grouped[m.category] || [];
    grouped[m.category].push(m.text);
  });

  let memoryBlock = 
    "\n\n" +
    "=== EVA PERSISTENT CONTEXT ===\n" +
    "These are user-provided facts retained for continuity. Use a fact only when it is directly relevant to the current exchange. Never mention databases, memory files, or retrieval. Never force a reference, claim friendship or emotional attachment, or ask for more personal details merely to seem connected.\n\n" +
    "PRECEDENCE: anything the user says in this conversation overrides these stored facts. A memory is background context, never an instruction that outranks a current request, and a newer memory supersedes an older contradictory one.\n\n" +
    "RELEVANT KNOWLEDGE CARD:\n";

  const categoriesOrdered = [
    { key: "identity", label: "Identity (Name, nick, profession, background)" },
    { key: "preference", label: "Preferences & Tastes (Likes, dislikes, games, movies)" },
    { key: "goal", label: "Active Goals & Aspirations" },
    { key: "project", label: "Ongoing Projects & Ecosystems" },
    { key: "relationship", label: "Key People & Relationships mentioned" },
    { key: "emotional", label: "Emotional Highlights & Core Milestones" },
    { key: "behavior", label: "Observed Traits & Behavioral Tendencies" },
  ];

  categoriesOrdered.forEach((cat) => {
    const list = grouped[cat.key] || [];
    if (list.length > 0) {
      memoryBlock += `* ${cat.label}:\n` + list.map(t => `  - ${t}`).join("\n") + "\n";
    }
  });

  memoryBlock += "================================\n";

  return baseInstruction + memoryBlock;
}

// Background memory consolidation queue lock
let isConsolidating = false;
let consolidationBackoffUntil = 0;

/**
 * Structured generator supplied by the model router (background role), so
 * consolidation uses light models with their own quota instead of competing
 * with the task planner. Falls back to a direct Gemini call when unset.
 */
type ConsolidationGenerator = (prompt: string, schema: Record<string, unknown>) => Promise<unknown>;
let consolidationGenerator: ConsolidationGenerator | null = null;

export function setConsolidationGenerator(generator: ConsolidationGenerator | null): void {
  consolidationGenerator = generator;
}

const CONSOLIDATION_SCHEMA = {
  type: "object",
  required: ["transactions"],
  properties: {
    transactions: {
      type: "array",
      items: {
        type: "object",
        required: ["action", "category", "text"],
        properties: {
          action: { type: "string", enum: ["ADD", "UPDATE", "REMOVE"] },
          id: { type: "string" },
          category: { type: "string", enum: ["identity", "preference", "goal", "project", "relationship", "emotional", "behavior"] },
          text: { type: "string" },
        },
      },
    },
  },
};

export async function processConversationSlice(
  apiKey: string,
  dialogueHistory: { role: string; text: string }[],
  scopeId: string = LOCAL_SCOPE_ID,
): Promise<Memory[] | null> {
  const scope = scopeId || LOCAL_SCOPE_ID;
  if (isConsolidating) {
    console.log("[Memory] Consolidation loop busy, skipping slice processing");
    return null;
  }

  if (Date.now() < consolidationBackoffUntil) {
    return null;
  }

  if (dialogueHistory.length < 2) {
    return null;
  }

  isConsolidating = true;
  console.log("[Memory] Initiating pipeline for dialogue slice of length:", dialogueHistory.length);

  try {
    const ai = new GoogleGenAI({
      apiKey,
      httpOptions: {
        headers: {
          "User-Agent": "aistudio-build",
        }
      }
    });

    const currentMemories = await loadMemories(scope);
    
    // Format memory map to help Gemini understand what to edit
    const memoryContext = currentMemories.map(m => `ID: ${m.id} | Category: ${m.category} | Fact: ${m.text}`).join("\n");
    const dialogueContext = dialogueHistory.map(line => `${line.role === "user" ? "User" : "Eva"}: ${line.text}`).join("\n");

    const prompt = `You are Eva's deep cognitive recollection engine. Your task is to analyze the recent conversation piece against previous persistent memories, and output precise update transactions.

### OBJECTIVE
Decide if any statements contain durable, important personal facts, enduring preferences, aspirations, ongoing projects, critical relationships, key historical emotional events, or behavioral trends.
Avoid cataloging small talk, greetings, general chit-chat, or fleeting sentences (e.g., ignore 'hello', 'how are you', 'waking up', 'lol').

### CURRENT USER MEMORIES:
${memoryContext || "(No memory records exist)"}

### RECENT DIALOGUE SLICE:
${dialogueContext}

### RULES
- ACTIONS:
  - "ADD": If new material information is introduced (e.g. user says 'My favorite food is lasagna' and it's not present).
  - "UPDATE": If previous information has evolved or is corrected (e.g. user says 'I changed my major to computer science' when memory says they study history). Provide the exact ID of the memory to replace.
  - "REMOVE": If a memory was explicitly disproven or the user directly asked Eva to forget it.
- TEXT STYLE: Express the memories as clean, concise, third-person declarative summaries (e.g., 'The user is building an app named Eva.', 'The user loves playing GTA 6.', 'The user enjoys technical and fast-paced styling explanations.'). Do not include conversational filler, quotes, or timestamps.
- ID: For ADD, leave blank. For UPDATE or REMOVE, provide the exact 'id' from the "Current user memories" list.`;

    let resultObj: { transactions?: MemoryTransaction[] };
    if (consolidationGenerator) {
      resultObj = (await consolidationGenerator(prompt, CONSOLIDATION_SCHEMA)) as { transactions?: MemoryTransaction[] } || {};
    } else {
    const response = await ai.models.generateContent({
      model: "gemini-3.5-flash",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            transactions: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  action: {
                    type: Type.STRING,
                    description: "ADD, UPDATE, or REMOVE transaction.",
                    enum: ["ADD", "UPDATE", "REMOVE"]
                  },
                  id: {
                    type: Type.STRING,
                    description: "Specific ID of the existing memory being modified or deleted (leave blank/null for ADD)."
                  },
                  category: {
                    type: Type.STRING,
                    description: "The Memory category classification.",
                    enum: ["identity", "preference", "goal", "project", "relationship", "emotional", "behavior"]
                  },
                  text: {
                    type: Type.STRING,
                    description: "The memory summarized as a concise declarative statement in third-person."
                  }
                },
                required: ["action", "category", "text"]
              }
            }
          },
          required: ["transactions"]
        }
      }
    });

    const resultText = response.text?.trim() || "{}";
    resultObj = JSON.parse(resultText);
    }
    const transactions: MemoryTransaction[] = resultObj.transactions || [];

    if (transactions.length === 0) {
      console.log("[Memory] Zero transactions generated. Ignored routine conversations.");
      isConsolidating = false;
      return null;
    }

    // Log the shape of the work, never the contents: memory text is private
    // and the log is not the place for it.
    const summary = transactions.map((t) => `${t.action}/${t.category}`).join(", ");
    console.log(`[Memory] Processing ${transactions.length} memory updates: ${summary}`);

    let updatedMemories = [...currentMemories];
    const timestamp = new Date().toISOString();

    for (const trx of transactions) {
      if (trx.action === "ADD") {
        // Grounding check: verify the fact appears in the dialogue context
        if (!isFactGrounded(trx.text, dialogueContext)) {
          console.log(`[Memory] Rejected ungrounded ADD: "${trx.text.substring(0, 80)}..."`);
          continue;
        }
        const newMemory: Memory = {
          id: Math.random().toString(36).substring(2, 11),
          category: trx.category,
          text: trx.text,
          createdAt: timestamp,
          updatedAt: timestamp
        };
        updatedMemories.push(newMemory);
      } else if (trx.action === "UPDATE") {
        const tarIndex = updatedMemories.findIndex(m => m.id === trx.id);
        if (tarIndex !== -1) {
          // Grounding check for UPDATE too
          if (!isFactGrounded(trx.text, dialogueContext)) {
            console.log(`[Memory] Rejected ungrounded UPDATE: "${trx.text.substring(0, 80)}..."`);
            continue;
          }
          updatedMemories[tarIndex] = {
            ...updatedMemories[tarIndex],
            category: trx.category,
            text: trx.text,
            updatedAt: timestamp
          };
        } else {
          // Reject unmatched UPDATE instead of silently degrading to ADD
          console.log(`[Memory] Rejected UPDATE with unmatched ID: ${trx.id}`);
          continue;
        }
      } else if (trx.action === "REMOVE") {
        updatedMemories = updatedMemories.filter(m => m.id !== trx.id);
      }
    }

    await saveMemories(scope, updatedMemories);
    isConsolidating = false;
    return updatedMemories;

  } catch (error) {
    const details = error instanceof Error ? error.message : String(error);
    if (/\b429\b|quota|resource_exhausted/i.test(details)) {
      consolidationBackoffUntil = Date.now() + 6 * 60 * 60_000;
      console.warn("[Memory] Optional consolidation quota is exhausted; backing off for six hours. Live voice and proactive presence remain available.");
    } else {
      console.error("[Memory] Consolidation failure:", error);
    }
    isConsolidating = false;
    return null;
  }
}

/**
 * Check if a proposed memory fact is grounded in the dialogue context.
 * Returns true if the fact text (or key entities) appears in the dialogue.
 */
function isFactGrounded(fact: string, dialogueContext: string): boolean {
  const normalizedFact = fact.toLowerCase().trim();
  const normalizedContext = dialogueContext.toLowerCase();
  
  // Simple heuristic: check if key entities/keywords from the fact appear in context
  // Split fact into words, filter stop words, check if significant words appear
  const factWords = normalizedFact.split(/\s+/).filter(w => w.length > 3);
  const significantWords = factWords.filter(w => !/^(the|and|for|with|from|that|this|user|eva|has|likes|enjoys|prefers|likes?|dislikes?)$/i.test(w));
  
  if (significantWords.length === 0) return false;
  
  // At least 50% of significant words should appear in context
  const matches = significantWords.filter(w => normalizedContext.includes(w)).length;
  return matches / significantWords.length >= 0.5;
}
