import { getGeminiApiKey } from "../../server_paths";
import { providerSettings } from "../config";
import type { LLMProvider, ProviderHealth } from "../types";
export class GeminiProvider implements LLMProvider {
  id="gemini"; name="Google Gemini";
  async health():Promise<ProviderHealth>{
    return {id:this.id,name:this.name,status:getGeminiApiKey() || providerSettings.GEMINI_API_KEY ? "configured":"unconfigured"};
  }
}
