/**
 * JARVIS — protected memory REST routes.
 *
 * Every route resolves the caller from a verified Supabase session, derives
 * their local memory scope, and scopes the operation to it. A user can never
 * see, edit or delete another user's memories, because the scope comes from
 * the verified session and not the request body.
 */
import type { Express, Request, Response } from "express";
import { requireAuth, type AuthedRequest } from "./authRoutes";
import { resolveMemoryScopeFromRequest, type MemoryScope } from "./memoryScope";
import {
  recallMemory,
  rememberConversation,
  listMemories,
  memoryConfigured,
  deleteMemory,
  deleteAllMemories,
} from "./mem0Service";

/** Resolve the caller's memory scope, or 401/403 with a safe message. */
async function scopeOrError(
  req: AuthedRequest,
  res: Response,
): Promise<MemoryScope | null> {
  const scope = await resolveMemoryScopeFromRequest(req);
  if (!scope) {
    res.status(401).json({ error: "Your session has expired. Please sign in again." });
    return null;
  }
  if (!scope.memoryEnabled) {
    res.status(403).json({ error: "Memory is turned off in your settings." });
    return null;
  }
  return scope;
}

function friendlyMemoryError(error: unknown): string {
  if (error instanceof Error) return error.message;
  return "Memory is temporarily unavailable.";
}

/** Get the scopeId from the request's memoryScope, falling back to local scope. */
function getScopeId(scope: MemoryScope): string {
  return scope.scopeId || "jarvis_user_local";
}

export function registerMemoryRoutes(app: Express): void {
  // Status: is memory configured and enabled for the caller?
  app.get("/api/memory/status", requireAuth, async (req: AuthedRequest, res: Response) => {
    const scope = await scopeOrError(req, res);
    if (!scope) return;
    const configured = await memoryConfigured(getScopeId(scope));
    res.json({
      configured,
      enabled: scope.memoryEnabled,
      message: configured ? null : "Memory is not configured on this instance.",
    });
  });

  // List the caller's own memories for the memory dashboard.
  app.get("/api/memory", requireAuth, async (req: AuthedRequest, res: Response) => {
    const scope = await scopeOrError(req, res);
    if (!scope) return;
    try {
      const memories = await listMemories(getScopeId(scope));
      res.json({ memories, configured: true });
    } catch (error) {
      res.status(503).json({ error: friendlyMemoryError(error), configured: false });
    }
  });

  // Retrieve memories relevant to a query (used when composing a reply).
  app.post("/api/memory/recall", requireAuth, async (req: AuthedRequest, res: Response) => {
    const scope = await scopeOrError(req, res);
    if (!scope) return;
    const query = String(req.body?.query || "");
    if (!query) return res.status(400).json({ error: "A query is required." });
    try {
      const memories = await recallMemory(query, 8, getScopeId(scope));
      res.json({ memories, configured: true });
    } catch (error) {
      // Memory failing must not break ordinary chat.
      res.status(503).json({ error: friendlyMemoryError(error), memories: [] });
    }
  });

  // Save memories derived from a conversation the caller just had.
  app.post("/api/memory/remember", requireAuth, async (req: AuthedRequest, res: Response) => {
    const scope = await scopeOrError(req, res);
    if (!scope) return;
    const raw = Array.isArray(req.body?.messages) ? req.body.messages : [];
    const messages = raw
      .filter((m: any) => m && typeof m.content === "string")
      .map((m: any) => ({ role: String(m.role || "user"), content: String(m.content) }));
    if (!messages.length) return res.status(400).json({ error: "No messages to remember." });
    try {
      await rememberConversation(getScopeId(scope), messages);
      res.json({ ok: true, configured: true });
    } catch (error) {
      res.status(503).json({ error: friendlyMemoryError(error) });
    }
  });

  // Forget one memory. The id is only ever applied to the caller's identity.
  app.delete("/api/memory/:id", requireAuth, async (req: AuthedRequest, res: Response) => {
    const scope = await scopeOrError(req, res);
    if (!scope) return;
    try {
      await deleteMemory(getScopeId(scope), String(req.params.id || ""));
      res.json({ ok: true });
    } catch (error) {
      res.status(503).json({ error: friendlyMemoryError(error) });
    }
  });

  // Clear the caller's own memory store. Affects no other user.
  app.delete("/api/memory", requireAuth, async (req: AuthedRequest, res: Response) => {
    const scope = await scopeOrError(req, res);
    if (!scope) return;
    try {
      await deleteAllMemories(getScopeId(scope));
      res.json({ ok: true });
    } catch (error) {
      res.status(503).json({ error: friendlyMemoryError(error) });
    }
  });
}