/**
 * JARVIS — Google OAuth sign-in.
 *
 * Supabase handles the OAuth handshake; this route just builds the authorize
 * URL with the correct redirect target, and exchanges the code Supabase hands
 * back for a session. The resulting user id is what everything else keys off.
 */
import type { Express, Request, Response } from "express";
import { supabase, supabaseConfigured } from "./supabaseClient";
import { initializeWorkspace } from "./workspace";
import { ensureOwnerRole } from "./ownerBootstrap";

function friendlyAuthError(message: string): string {
  const m = message.toLowerCase();
  if (m.includes("expired")) return "The sign-in link expired. Please try again.";
  if (m.includes("denied") || m.includes("aborted")) return "Google sign-in was cancelled.";
  return "Google sign-in failed. Please try again.";
}

export function registerGoogleRoutes(app: Express): void {
  if (!supabaseConfigured) return;

  const redirectBase = process.env.EVA_APP_URL || `http://127.0.0.1:${process.env.EVA_PORT || 3000}`;
  const redirectUrl = `${redirectBase.replace(/\/$/, "")}/auth/callback`;

  // Begin Google sign-in. Returns the URL the browser should navigate to.
  app.get("/api/auth/google", async (_req: Request, res: Response) => {
    const { data, error } = await supabase.auth.signInWithOAuth({
      provider: "google",
      options: {
        redirectTo: redirectUrl,
        // Ask for a fresh consent screen so returning users can switch accounts.
        queryParams: { prompt: "select_account" },
      },
    });

    if (error || !data?.url) {
      res.status(500).json({ error: friendlyAuthError(error?.message || "no url") });
      return;
    }
    res.json({ url: data.url });
  });

  // Exchange the code Google/Supabase returned for a usable session.
  app.post("/api/auth/google/callback", async (req: Request, res: Response) => {
    const code = String(req.body?.code || "");
    if (!code) {
      res.status(400).json({ error: "The sign-in response is missing required information." });
      return;
    }

    const { data, error } = await supabase.auth.exchangeCodeForSession(code);
    if (error || !data.user || !data.session) {
      res.status(401).json({ error: friendlyAuthError(error?.message || "exchange failed") });
      return;
    }

    // First Google sign-in for this account: create the workspace. Idempotent,
    // so a returning user keeps everything they already had.
    const workspace = await initializeWorkspace(data.user.id, data.session.access_token).catch((err) => {
      console.error("[Auth] Google workspace init failed:", err);
      return null;
    });

    // Allowlisted Owner accounts get full rights automatically, even via Google.
    await ensureOwnerRole(data.user.id, data.user.email);

    res.status(200).json({
      user: { id: data.user.id, email: data.user.email },
      session: {
        accessToken: data.session.access_token,
        refreshToken: data.session.refresh_token,
        expiresAt: data.session.expires_at,
      },
      workspace,
    });
  });
}
