import { GeminiProvider } from "./gemini";
import { AtriaDawnProvider } from "./atria";
import { ComposioProvider } from "./composio";

const providers = {
  gemini: new GeminiProvider(),
  atria: new AtriaDawnProvider(),
  composio: new ComposioProvider(),
};

export { providers };

export async function providerHealthSafe(): Promise<Array<{ id: string; name: string; status: string }>> {
  const results = [];
  for (const [key, provider] of Object.entries(providers)) {
    try {
      const health = await provider.health();
      results.push({ id: health.id, name: health.name, status: health.status });
    } catch (e) {
      results.push({ id: key, name: key, status: "error" });
    }
  }
  return results;
}