/**
 * Device credential minting/verification for the remote gateway.
 *
 * Thin wrapper over remote/tokenCore.mjs that knows the config secret, the
 * token lifetimes, and — critically — consults the device store: a valid
 * signature is NOT authorization. The device row must be 'active' (or
 * 'pending'/'link_sent' for the narrowly-scoped pairing handshake).
 *
 * Lifetimes (rotatable via env where noted):
 *   access  — 30 minutes; short so a stolen URL/ID can't outlive a revocation
 *   refresh — 30 days; revocable instantly via the device row
 *   pair    — 10 minutes, single claim (the emailed link)
 *   host    — 30 days; the PC re-mints on every boot
 */
import path from "node:path";
import { loadOrCreateSecret, remoteConfig, type RemoteConfig } from "./config";
import { mintDeviceToken, tokenExpiresInSeconds, verifyDeviceToken } from "./tokenCore.mjs";
import type { DeviceStore, RemoteDevice } from "./devices";

export interface TokenClaims {
  uid: string;
  did: string;
  k: "access" | "refresh" | "pair" | "host";
  iat: number;
  exp: number;
  jti: string;
}

const seconds = (value: string | undefined, fallback: number): number => {
  const parsed = Number(value);
  return Number.isFinite(parsed) && parsed > 0 ? Math.floor(parsed) : fallback;
};

export function accessTtlSeconds(): number {
  return seconds(process.env.EVA_REMOTE_ACCESS_TTL_SEC, 30 * 60);
}
export function refreshTtlSeconds(): number {
  return seconds(process.env.EVA_REMOTE_REFRESH_TTL_SEC, 30 * 24 * 60 * 60);
}
export function pairTtlSeconds(): number {
  return seconds(process.env.EVA_REMOTE_PAIR_TTL_SEC, 10 * 60);
}

export function mintAccess(cfg: RemoteConfig, userId: string, deviceId: string): string {
  return mintDeviceToken({ userId, deviceId, secret: cfg.hmacSecret, ttlSeconds: accessTtlSeconds(), kind: "access" });
}

export function mintRefresh(cfg: RemoteConfig, userId: string, deviceId: string): string {
  return mintDeviceToken({ userId, deviceId, secret: cfg.hmacSecret, ttlSeconds: refreshTtlSeconds(), kind: "refresh" });
}

export function mintPair(cfg: RemoteConfig, userId: string, deviceId: string, nonce: string): string {
  return mintDeviceToken({
    userId, deviceId, secret: cfg.hmacSecret, ttlSeconds: pairTtlSeconds(), kind: "pair", nonce,
  });
}

export function mintHost(cfg: RemoteConfig, installId: string): string {
  // uid "*" — the relay lets a host bind only rooms the backend asks for,
  // and only the backend (holder of the secret) can mint host tokens.
  return mintDeviceToken({ userId: "*", deviceId: installId, secret: cfg.hmacSecret, ttlSeconds: refreshTtlSeconds(), kind: "host" });
}

export function verifyToken(cfg: RemoteConfig, token: string, kind?: TokenClaims["k"]): TokenClaims | null {
  return verifyDeviceToken(token, cfg.hmacSecret, kind ? { kind } : undefined) as TokenClaims | null;
}

export function tokenExpiry(token: string): number | null {
  const secs = tokenExpiresInSeconds(token);
  return secs === null ? null : Date.now() + secs * 1000;
}

export type SessionVerdict =
  | { ok: true; claims: TokenClaims; device: RemoteDevice | "host" }
  | { ok: false; reason: "invalid" | "unknown_device" | "not_active" | "user_mismatch" };

/**
 * Verify a connection token against the store.
 *
 * - `access`/`refresh`: device must be active and belong to the token user.
 * - `pair`: device must still be awaiting claim/approval (link_sent/pending).
 * - `host`: accepted as-is (only the backend can mint host tokens).
 */
export async function verifySessionToken(
  cfg: RemoteConfig,
  store: DeviceStore,
  token: string,
): Promise<SessionVerdict> {
  const claims = verifyToken(cfg, token);
  if (!claims) return { ok: false, reason: "invalid" };

  if (claims.k === "host") return { ok: true, claims, device: "host" };

  const device = await store.get(claims.did).catch(() => null);
  if (!device) return { ok: false, reason: "unknown_device" };
  if (device.userId !== claims.uid) return { ok: false, reason: "user_mismatch" };

  if (claims.k === "pair") {
    if (device.status !== "link_sent" && device.status !== "pending") return { ok: false, reason: "not_active" };
    return { ok: true, claims, device };
  }

  // access / refresh. 'pending' stays usable for the pairing handshake only
  // (the dispatcher refuses every non-pairing kind until status is 'active').
  if (device.status !== "active" && device.status !== "pending") return { ok: false, reason: "not_active" };
  return { ok: true, claims, device };
}

/** Stable per-install id used for the host (PC) relay identity. */
export function installId(dataDir: string): string {
  return loadOrCreateSecret(path.join(dataDir, "remote", "install.id"), 16).slice(0, 32);
}

export { remoteConfig };
