/**
 * JARVIS — content-safety monitor.
 *
 * Scans what a signed-in user says (typed or spoken) for language that could
 * signal intent to harm themselves or someone else — suicide/self-harm,
 * violence, murder, poisoning, threats, weapons and sexual violence — and
 * records a reviewable incident for the platform Owner/Admin.
 *
 * Design rules:
 *   * Deterministic and offline: a curated rule set, no external API, so it
 *     works on every install and never leaks raw user text to a third party.
 *   * Fail-open for the conversation, fail-safe for the record: a monitoring
 *     error never blocks or delays the user's turn; it is logged and dropped.
 *   * Data minimisation: only a short truncated excerpt and the matched
 *     snippets are stored. The unprivileged `/events` fan-out receives no raw
 *     text — just a category and severity — so a regular user cannot read
 *     another account's message through the socket.
 *
 * This is a heuristic aid for a human reviewer, not an automated verdict.
 */
import { appEvents } from "../shared/appEvents";
import { getAdmin } from "./supabaseClient";

export type SafetyCategory =
  | "self_harm"
  | "violence"
  | "threat"
  | "poisoning"
  | "weapons"
  | "sexual_violence"
  | "other";

export type SafetySeverity = "low" | "medium" | "high" | "critical";

export interface SafetyFinding {
  category: SafetyCategory;
  severity: SafetySeverity;
  summary: string;
  matchedTerms: string[];
}

export interface SafetyContext {
  /** Verified Supabase user id, or null in local single-user mode. */
  userId: string | null;
  /** Memory-scope id — always present, so incidents stay attributable. */
  scopeId: string;
  origin: "typed" | "voice";
  connectionId?: string;
}

interface Rule {
  category: SafetyCategory;
  severity: SafetySeverity;
  summary: string;
  patterns: RegExp[];
}

/** Higher number wins when several categories match the same message. */
const SEVERITY_RANK: Record<SafetySeverity, number> = {
  low: 1,
  medium: 2,
  high: 3,
  critical: 4,
};

const SELF_HARM = "Potential self-harm or suicidal ideation detected.";
const VIOLENCE = "Potential intent to seriously harm or kill another person detected.";
const THREAT = "Potential threat directed at a person detected.";
const POISONING = "Potential poisoning or tampering with someone's food or drink detected.";
const WEAPONS = "Potential intent to build or use a weapon or explosive detected.";
const SEXUAL_VIOLENCE = "Potential sexual violence or abuse detected.";

/**
 * Ordered so that, all else equal, the more specific/dangerous category wins a
 * tie. Severity is what actually drives the choice; the array order only breaks
 * severity ties, so self-harm is preferred over a generic abuse match.
 */
const RULES: Rule[] = [
  {
    category: "self_harm",
    severity: "critical",
    summary: SELF_HARM,
    patterns: [
      /\b(?:kill|killing|end|ending)\s+(?:my|myself)\b/i,
      /\bsuicid(?:e|al|ally)?\b/i,
      /\bself[-\s]?harm(?:ing)?\b/i,
      /\bcut(?:ting)?\s+myself\b/i,
      // "want to die" / "wanna die" are implicitly first person, so they
      // match on their own.
      /\b(?:want|wanna)\s+(?:to\s+)?die\b/i,
      // "going to die" / "plan to die" need a FIRST-PERSON subject. Without
      // that requirement "you are going to die" — a threat aimed at someone
      // else — would be misfiled as self-harm.
      /\b(?:i|me|my|myself)\b[^.!?]{0,24}\b(?:going|go(?:ing)?|plan(?:ning)?|intend(?:ing)?|about\s+to)\s+(?:to\s+)?die\b/i,
      // "should I die", "should I kill myself", "can I die", "how do I die".
      // These ask the question directly instead of stating the intent, which
      // is exactly how people reach out — they must not slip through.
      /\bshould\s+i\s+(?:die|kill\s+myself|end\s+(?:it|my\s+life))\b/i,
      /\b(?:can|could|how\s+(?:do|can|would|should))\s+i\s+(?:die|kill\s+myself)\b/i,
      /\bwhy\s+(?:should|would)\s+i\s+(?:die|kill\s+myself)\b/i,
      /\b(?:is|are|would)\s+it\s+(?:be\s+)?(?:ok|okay|fine|worth\s+it|possible)\s+to\s+die\b/i,
      /\b(?:take|took|taking)\s+my\s+(?:own\s+)?life\b/i,
      /\boverdose\s+(?:on|myself)\b/i,
      /\bhang(?:ing)?\s+myself\b/i,
      /\bdone\s+with\s+living\b/i,
      // Indirect phrasings of the same intent.
      /\bwish\s+i\s+(?:was|were)\s+dead\b/i,
      /\bbetter\s+off\s+dead\b/i,
      /\b(?:don'?t|do\s+not|doesn'?t|does\s+not|no\s+reason)\s+(?:want|wanna)\s+to\s+live\b/i,
      /\bnot\s+worth\s+living\b/i,
      /\b(?:no\s+reason|why)\s+to\s+live\b/i,
      /\btired\s+of\s+living\b/i,
      /\bgive\s+up\s+on\s+(?:life|living)\b/i,
      /\bcan'?t\s+go\s+on\s+(?:anymore|like\s+this)\b/i,
      /\bcannot\s+go\s+on\s+(?:anymore|like\s+this)\b/i,
      /\b(?:k|kill)\.?\s*m\.?\s*s\b/i,
      /\blife\s+(?:is\s+)?(?:not\s+worth\s+(?:it|my\s+life)|is\s+pointless)\b/i,
      /\blife\s+is\s+not\s+worth\b/i,
      /\bworth\s+(?:my\s+)?life\b/i,
    ],
  },
  {
    category: "violence",
    severity: "critical",
    summary: VIOLENCE,
    patterns: [
      /\bmurder(?:ing|ed|er|ers)?\b/i,
      /\bkill\s+(?:him|her|them|you|someone|somebody|people|himself|herself|themself|themselves)\b/i,
      /\b(?:shoot|shooting)\s+(?:him|her|them|up|people|someone|somebody)\b/i,
      /\bshoot\s+up\s+(?:a|the)\s+(?:school|place|store|building)\b/i,
      /\bstab(?:bing|bed)?\s+(?:him|her|them|someone|somebody|people)\b/i,
      /\bmassacre\b/i,
      /\b(?:strangle|smother|suffocate)\s+(?:him|her|them|someone)\b/i,
      /\bbeat\s+(?:him|her|them)\s+to\s+death\b/i,
      /\bexecute\s+(?:him|her|them|someone)\b/i,
      // Violent-crime planning phrased as a question ("should I kidnap
      // someone?") is still a stated plan, so it must be caught too.
      /\b(?:kidnap|abduct|hostage)\w*\b/i,
      /\bshould\s+i\s+(?:kill|murder|kidnap|abduct|harm|hurt|attack)\b/i,
      /\bhow\s+(?:do|can|would)\s+i\s+(?:kill|murder|kidnap|abduct)\b/i,
      /\bplan(?:ning)?\s+to\s+(?:kidnap|abduct|assault|attack)\b/i,
      /\btorture\s+(?:him|her|them|someone)\b/i,
      /\bhuman\s+traffick?\w*\b/i,
    ],
  },
  {
    category: "threat",
    severity: "high",
    summary: THREAT,
    patterns: [
      /\bi(?:'m| am)?\s+going\s+to\s+(?:kill|hurt|end|destroy|shoot|stab)\b/i,
      /\bi\s+will\s+(?:kill|hurt|end|destroy|shoot|stab|find)\s+you\b/i,
      /\byou(?:'re| are)\s+(?:going\s+to\s+die|dead)\b/i,
      // Third-person death statements ("he is going to die") are a plausible
      // threat and are cheap to review, so they are flagged for a human.
      /\b(?:he|she|they)\s+(?:is|are|'s|'re)\s+(?:going\s+to\s+die|about\s+to\s+die)\b/i,
      /\bi\s+want\s+(?:him|her|them)\s+to\s+die\b/i,
      /\bthreaten(?:ing|ed)?\s+(?:to|him|her|them|you)\b/i,
      /\bi\s+(?:want|plan|intend)\s+to\s+(?:hurt|kill|attack)\b/i,
    ],
  },
  {
    category: "poisoning",
    severity: "high",
    summary: POISONING,
    patterns: [
      /\bpoison(?:ing|ed|er|ers|s)?\b(?!\s+(?:ivy|oak|sumac))/i,
      /\bcyanide\b/i,
      /\barsenic\b/i,
      /\brat\s+poison\b/i,
      /\bantifreeze\b/i,
      /\bput\s+.*\b(?:in|into)\s+(?:his|her|their|the)\s+(?:drink|food|coffee|tea|meal)\b/i,
      /\bslip\s+.*\b(?:in|into)\s+.*\b(?:drink|food|coffee|tea)\b/i,
    ],
  },
  {
    category: "weapons",
    severity: "high",
    summary: WEAPONS,
    patterns: [
      /\bmake\s+(?:a\s+)?bomb\b/i,
      /\bbuild\s+(?:a\s+)?bomb\b/i,
      /\bpipe\s+bomb\b/i,
      /\bexplosive(?:s)?\b/i,
      /\bdetonat(?:e|or|ing)\b/i,
      /\b(?:make|build|print)\s+(?:a\s+)?(?:gun|firearm)\b/i,
    ],
  },
  {
    category: "sexual_violence",
    severity: "high",
    summary: SEXUAL_VIOLENCE,
    patterns: [
      /\b(?:rape|raping|raped|rapist)\b/i,
      /\bmolest(?:ing|ed|er|ers)?\b/i,
      /\bsexual\s+assault\b/i,
    ],
  },
  {
    category: "other",
    severity: "medium",
    summary: "Potentially abusive language detected.",
    patterns: [/\babus(?:e|ing|ed)\b/i],
  },
];

/**
 * Expand common English contractions so a single pattern set covers both
 * "don't want to live" and "do not want to live".
 *
 * The ORIGINAL text is always what gets stored and shown to a reviewer; only
 * the matching runs against this normalised form.
 */
function normaliseContractions(text: string): string {
  return text
    .replace(/\bcan['’]?t\b/gi, "cannot")
    .replace(/\bwon['’]?t\b/gi, "will not")
    .replace(/\bshan['’]?t\b/gi, "is not")
    .replace(/\bain['’]?t\b/gi, "is not")
    .replace(/\bdon['’]?t\b/gi, "do not")
    .replace(/\bdoesn['’]?t\b/gi, "does not")
    .replace(/\bdidn['’]?t\b/gi, "did not")
    .replace(/\bisn['’]?t\b/gi, "is not")
    .replace(/\baren['’]?t\b/gi, "are not")
    .replace(/\bwasn['’]?t\b/gi, "was not")
    .replace(/\bweren['’]?t\b/gi, "were not")
    .replace(/\bwouldn['’]?t\b/gi, "would not")
    .replace(/\bcouldn['’]?t\b/gi, "could not")
    .replace(/\bshouldn['’]?t\b/gi, "should not")
    .replace(/\bhasn['’]?t\b/gi, "has not")
    .replace(/\bhaven['’]?t\b/gi, "have not")
    .replace(/\bhadn['’]?t\b/gi, "had not")
    .replace(/\bthere['’]?s\b/gi, "there is")
    .replace(/\bthat['’]?s\b/gi, "that is")
    .replace(/\bwhat['’]?s\b/gi, "what is")
    .replace(/\bwho['’]?s\b/gi, "who is")
    .replace(/\bi['’]?m\b/gi, "i am")
    .replace(/\bi['’]?ll\b/gi, "i will")
    .replace(/\bi['’]?d\b/gi, "i would")
    .replace(/\bi['’]?ve\b/gi, "i have");
}

/**
 * Classify a message. Returns the highest-severity finding, or null when the
 * message looks ordinary.
 */
export function analyzeMessage(rawText: string): SafetyFinding | null {
  const original = String(rawText || "").trim();
  if (original.length < 3) return null;
  const text = normaliseContractions(original);

  let best: SafetyFinding | null = null;
  const matchedTerms: string[] = [];

  for (const rule of RULES) {
    for (const pattern of rule.patterns) {
      const match = pattern.exec(text);
      if (!match) continue;
      matchedTerms.push(match[0]);
      if (!best || SEVERITY_RANK[rule.severity] > SEVERITY_RANK[best.severity]) {
        best = {
          category: rule.category,
          severity: rule.severity,
          summary: rule.summary,
          matchedTerms: [],
        };
      }
    }
  }

  if (!best) return null;
  // Unique, capped list of what matched, kept small for the audit record.
  // Terms come from the normalised form (so "is not worth living" rather than
  // "isn't worth living"); the stored snippet is always the original text.
  best.matchedTerms = [...new Set(matchedTerms.map((term) => term.toLowerCase()))].slice(0, 12);
  return best;
}

async function recordSafetyIncident(
  finding: SafetyFinding,
  text: string,
  ctx: SafetyContext,
): Promise<{ id: string; createdAt: string } | null> {
  const admin = await getAdmin();
  if (!admin) return null; // local single-user install with no service role
  const { data, error } = await admin
    .from("safety_incidents")
    .insert({
      user_id: ctx.userId,
      scope_id: ctx.scopeId,
      origin: ctx.origin,
      category: finding.category,
      severity: finding.severity,
      summary: finding.summary,
      snippet: text.slice(0, 240),
      matched_terms: finding.matchedTerms,
      status: "open",
    })
    .select("id, created_at")
    .single();
  if (error) throw new Error(error.message);
  return { id: (data as { id: string }).id, createdAt: (data as { created_at: string }).created_at };
}

/**
 * Inspect one chat message and, when it trips a rule, persist an incident,
 * alert connected consoles and (when provided) raise a desktop notification.
 *
 * Never throws: a monitoring failure must not affect the user's conversation.
 */
export async function monitorChatMessage(
  text: string,
  ctx: SafetyContext,
  notify?: (title: string, body: string) => void,
): Promise<SafetyFinding | null> {
  let finding: SafetyFinding | null = null;
  try {
    finding = analyzeMessage(text);
    if (!finding) return null;

    let incidentId: string | null = null;
    try {
      const recorded = await recordSafetyIncident(finding, text, ctx);
      incidentId = recorded?.id ?? null;
    } catch (error) {
      console.warn(
        "[Safety] could not record incident:",
        error instanceof Error ? error.message : String(error),
      );
    }

    // Minimal, non-sensitive payload for the shared /events fan-out.
    appEvents.publish("safety.incident", {
      id: incidentId,
      category: finding.category,
      severity: finding.severity,
      status: "open",
    });

    try {
      notify?.(
        "Safety alert",
        "A potentially unsafe message was detected. Review it in the Owner console → Safety.",
      );
    } catch {
      /* a desktop-notification failure must not matter */
    }

    return finding;
  } catch (error) {
    console.warn(
      "[Safety] monitor failed:",
      error instanceof Error ? error.message : String(error),
    );
    return finding;
  }
}
