/**
 * JARVIS — Supabase server-side client and identity resolution.
 *
 * Two clients, deliberately:
 *  - supabase      : anon-key client, used to VERIFY an incoming session.
 *                    It cannot read another user's data: RLS applies to it.
 *  - supabaseAdmin : service-role client for trusted initialization and
 *                    account deletion ONLY. Never use it in a request path
 *                    that acts on a client-supplied user id without first
 *                    resolving the identity from a verified session.
 *
 * The service role key comes from the environment and is never bundled into
 * the frontend build.
 */
import fs from "fs";
import path from "path";
import { createClient, type SupabaseClient } from "@supabase/supabase-js";

/**
 * In development the values come from .env (loaded before this module is
 * imported). In the packaged desktop app there is no .env, so a build-time
 * generated `supabase.config.json` (shipped next to the bundle) supplies the
 * PUBLIC project URL and anon key. The service role key is deliberately never
 * written to that file — see scripts/write-supabase-config.mjs.
 */
function loadBundledSupabaseConfig(): void {
  if (process.env.SUPABASE_URL && process.env.SUPABASE_ANON_KEY) return;
  const candidates: string[] = [];
  if (process.env.EVA_APP_ROOT) {
    candidates.push(path.join(process.env.EVA_APP_ROOT, "supabase.config.json"));
    candidates.push(path.join(process.env.EVA_APP_ROOT, "dist", "supabase.config.json"));
  }
  candidates.push(path.join(process.cwd(), "supabase.config.json"));
  try {
    // __dirname is defined in the bundled CJS output; guard for ESM dev runs.
    if (typeof __dirname !== "undefined") candidates.push(path.join(__dirname, "supabase.config.json"));
  } catch {
    /* __dirname unavailable under ESM */
  }
  for (const file of candidates) {
    try {
      if (!fs.existsSync(file)) continue;
      const config = JSON.parse(fs.readFileSync(file, "utf-8")) as {
        url?: string;
        anonKey?: string;
      };
      if (config.url && !process.env.SUPABASE_URL) process.env.SUPABASE_URL = config.url;
      if (config.anonKey && !process.env.SUPABASE_ANON_KEY) process.env.SUPABASE_ANON_KEY = config.anonKey;
      return;
    } catch {
      /* try the next candidate */
    }
  }
}

loadBundledSupabaseConfig();

const SUPABASE_URL = process.env.SUPABASE_URL || "";
const SUPABASE_ANON_KEY = process.env.SUPABASE_ANON_KEY || "";
const SUPABASE_SERVICE_KEY = process.env.SUPABASE_SERVICE_ROLE_KEY || "";

export const supabaseConfigured = Boolean(SUPABASE_URL && SUPABASE_ANON_KEY);

/**
 * Lazily built. createClient throws on an empty URL, and the module is
 * imported by tests and by instances that have not configured Supabase yet —
 * those must not crash on import.
 */
let anonClient: SupabaseClient | null = null;
export function getSupabase(): SupabaseClient {
  if (!anonClient) anonClient = createClient(SUPABASE_URL, SUPABASE_ANON_KEY, {
    auth: { persistSession: false, autoRefreshToken: false },
  });
  return anonClient;
}

/** Anon client. RLS applies to it, so it cannot read another user's data. */
export const supabase: SupabaseClient = new Proxy({} as SupabaseClient, {
  get(_target, prop) { return Reflect.get(getSupabase(), prop); },
});

/**
 * Anon client scoped to a single user's verified access token. RLS then
 * resolves auth.uid() to that user, so "select own row" policies apply.
 * Used for read paths (e.g. /api/auth/me) where the token-less anon client
 * would otherwise see nothing.
 */
export function userClient(accessToken: string): SupabaseClient {
  return createClient(SUPABASE_URL, SUPABASE_ANON_KEY, {
    auth: { persistSession: false, autoRefreshToken: false },
    global: { headers: { Authorization: `Bearer ${accessToken}` } },
  });
}

/** Trusted client. Bypasses RLS — use only for workspace init and deletion. */
let adminClient: SupabaseClient | null = null;
export function requireAdmin(): SupabaseClient {
  if (!SUPABASE_URL || !SUPABASE_SERVICE_KEY) {
    throw new Error("Supabase service role is not configured.");
  }
  if (!adminClient) adminClient = createClient(SUPABASE_URL, SUPABASE_SERVICE_KEY, {
    auth: { persistSession: false, autoRefreshToken: false },
  });
  return adminClient;
}

/**
 * Lazy accessor for tests and trusted paths. Prefer requireAdmin(), which
 * fails loudly when the service role is missing.
 */
export async function getAdmin(): Promise<SupabaseClient | null> {
  if (!SUPABASE_URL || !SUPABASE_SERVICE_KEY) return null;
  return requireAdmin();
}

/**
 * Resolve the authenticated user from a request's Authorization bearer token
 * by asking Supabase to verify it. Never trust a user id supplied by the
 * browser: the id below comes from a verified JWT.
 */
export async function resolveUserFromRequest(req: {
  headers: Record<string, string | string[] | undefined>;
}): Promise<{ id: string; email: string | null } | null> {
  const header = req.headers["authorization"] || req.headers["Authorization"];
  const token = Array.isArray(header) ? header[0] : header;
  if (!token || !/^Bearer\s+/i.test(token)) return null;

  const { data, error } = await supabase.auth.getUser(token.replace(/^Bearer\s+/i, "").trim());
  if (error || !data.user) return null;
  return { id: data.user.id, email: data.user.email ?? null };
}
