/**
 * JARVIS — the single source of truth for "whose memory is this?".
 *
 * Every memory path in the product — the REST routes, the /live WebSocket,
 * the background consolidation job, the structured cognition store and the
 * Mem0 client — resolves through here. The scope id is derived from a
 * VERIFIED Supabase session and is never taken from the client, so two users
 * can never land in the same memory namespace.
 *
 * Instances without Supabase configured stay single-user: they resolve to a
 * fixed local scope so the product keeps working, and because there is only
 * ever one user there is nothing to isolate.
 */
import type { NextFunction, Request, Response } from "express";
import { supabase, supabaseConfigured } from "./supabaseClient";
/** Deterministic Mem0 identity for a verified Supabase user. */
export function mem0IdentityFor(userId: string): string {
  return `jarvis_user_${userId}`;
}

/** Scope used when Supabase is not configured (local single-user install). */
export const LOCAL_SCOPE_ID = "jarvis_user_local";

export interface MemoryScope {
  /** Stable namespace id used to key every memory store and cache. */
  scopeId: string;
  /** Verified Supabase user id, or null in local single-user mode. */
  userId: string | null;
  /** Mem0 identity for this user (equals scopeId). */
  mem0UserId: string;
  /** False when the user has turned memory off in their settings. */
  memoryEnabled: boolean;
  /** True for local single-user installs (no Supabase). */
  readonly local: boolean;
}

/** Build the scope for a verified user id, trusting nothing but the id. */
export function scopeForUser(userId: string, memoryEnabled = true): MemoryScope {
  const mem0UserId = mem0IdentityFor(userId);
  return { scopeId: mem0UserId, userId, mem0UserId, memoryEnabled, local: false };
}

/** The scope used by local single-user installs. */
export function localScope(): MemoryScope {
  return {
    scopeId: LOCAL_SCOPE_ID,
    userId: null,
    mem0UserId: LOCAL_SCOPE_ID,
    memoryEnabled: true,
    local: true,
  };
}

/**
 * Resolve a memory scope from a raw bearer token.
 *
 * The token is verified by Supabase; the user id in the returned scope comes
 * from that verification and from nothing else. When Supabase is not
 * configured the caller gets the local scope.
 */
/**
 * Verify a bearer token and return the authenticated user id.
 *
 * The default implementation asks Supabase. Tests inject a stub here so the
 * authorization contract can be exercised without a live Supabase project.
 * This is the ONLY place user identity enters the memory system, and it is
 * the ONLY thing a caller can never supply for themselves.
 */
export interface SessionVerifier {
  verify(accessToken: string): Promise<{ userId: string; memoryEnabled: boolean } | null>;
}

const defaultVerifier: SessionVerifier = {
  async verify(accessToken) {
    const { data: authData, error: authError } = await supabase.auth.getUser(accessToken);
    if (authError || !authData.user) return null;
    const userId = authData.user.id;

    // Read the user's own settings row through the anon client so RLS confines
    // the lookup to their row. A missing row falls back to the derived identity.
    const { data } = await supabase
      .from("user_memory_settings")
      .select("mem0_user_id, memory_enabled")
      .eq("user_id", userId)
      .maybeSingle();

    return { userId, memoryEnabled: data?.memory_enabled ?? true };
  },
};

let sessionVerifier: SessionVerifier = defaultVerifier;

/** Replace the session verifier. Tests use this; production never does. */
export function setSessionVerifier(verifier: SessionVerifier | null): void {
  sessionVerifier = verifier ?? defaultVerifier;
}

export async function resolveMemoryScopeFromToken(token: string | undefined | null): Promise<MemoryScope | null> {
  // Without Supabase the instance is single-user, so there is nothing to
  // isolate. An explicitly installed verifier (tests) overrides this and
  // forces the multi-user path.
  if (!supabaseConfigured && sessionVerifier === defaultVerifier) return localScope();
  const accessToken = String(token || "").replace(/^Bearer\s+/i, "").trim();
  if (!accessToken) return null;

  const session = await sessionVerifier.verify(accessToken);
  if (!session) return null;

  const userId = session.userId;
  const expected = mem0IdentityFor(userId);

  // Defense in depth: a stored identity that does not match the derived one is
  // ignored — the derived identity is authoritative.
  return {
    scopeId: expected,
    userId,
    mem0UserId: expected,
    memoryEnabled: session.memoryEnabled,
    local: false,
  };
}

/**
 * Resolve a memory scope from a request's Authorization header.
 *
 * Accepts the minimal header shape so it works for both Express requests and
 * the raw IncomingMessage of a WebSocket upgrade — the WS handshake cannot set
 * headers in the browser, so the token may also arrive as a `?token=` query
 * parameter.
 */
export async function resolveMemoryScopeFromRequest(req: {
  headers?: Record<string, string | string[] | undefined>;
  url?: string | null;
}): Promise<MemoryScope | null> {
  const header = req.headers?.["authorization"];
  const headerToken = Array.isArray(header) ? header[0] : header;
  if (headerToken) return resolveMemoryScopeFromToken(headerToken);

  // Browsers cannot attach headers to a WebSocket handshake, so the client
  // passes the token in the query string instead.
  try {
    const url = new URL(req.url || "", "http://localhost");
    const queryToken = url.searchParams.get("token");
    if (queryToken) return resolveMemoryScopeFromToken(queryToken);
  } catch { /* malformed url — no token */ }
  return null;
}

export interface ScopedRequest extends Request {
  memoryScope?: MemoryScope;
}

/**
 * Middleware: resolve the caller's memory scope and refuse the request when
 * no verified session exists. On local single-user installs it always passes,
 * because there is only one possible user.
 */
export async function requireMemoryScope(req: ScopedRequest, res: Response, next: NextFunction): Promise<void> {
  const scope = await resolveMemoryScopeFromRequest(req);
  if (!scope) {
    res.status(401).json({ error: "Your session has expired. Please sign in again." });
    return;
  }
  if (!scope.memoryEnabled) {
    res.status(403).json({ error: "Memory is turned off in your settings." });
    return;
  }
  req.memoryScope = scope;
  next();
}
