/**
 * EVA — the accent/background themes.
 *
 * Shared by the backend (which validates a stored theme value) and the
 * frontend (which renders the picker and the ambient background), so the
 * list of valid themes can never drift between the two.
 */

export interface ThemeColor {
  id: string;
  label: string;
  /** Tailwind class for the swatch in the theme picker. */
  swatch: string;
}

export const THEME_COLORS: readonly ThemeColor[] = [
  { id: "charcoal", label: "Charcoal", swatch: "bg-slate-400" },
  { id: "violet", label: "Violet", swatch: "bg-violet-400" },
  { id: "crimson", label: "Crimson", swatch: "bg-rose-500" },
  { id: "emerald", label: "Emerald", swatch: "bg-emerald-400" },
  { id: "celestial", label: "Celestial", swatch: "bg-sky-400" },
  { id: "gold", label: "Gold", swatch: "bg-amber-400" },
  { id: "rose", label: "Rose", swatch: "bg-pink-400" },
];

export const THEME_COLOR_IDS: readonly string[] = THEME_COLORS.map((color) => color.id);

export const DEFAULT_THEME_COLOR = "charcoal";

export function isThemeColor(value: unknown): value is string {
  return typeof value === "string" && THEME_COLOR_IDS.includes(value);
}
