/**
 * Device credential tokens — dependency-free HMAC-SHA256 signed tokens.
 *
 * Plain ESM (no TypeScript) so both the EVA backend (`remote/tokens.ts`) and
 * the standalone relay (`relay/server.mjs`) import the exact same code. The
 * relay only ever verifies; only the EVA backend mints.
 *
 * Payload claim names are intentionally short: they travel on every WS
 * handshake. Never put secrets in a claim — the token is a bearer credential.
 */
import { createHmac, randomBytes, timingSafeEqual } from "node:crypto";

const HEADER = b64urlEncode(JSON.stringify({ alg: "HS256", typ: "EVA-DEVICE" }));
const SUBPROTOCOL = "eva-relay.v1";

function b64urlEncode(value) {
  return Buffer.from(value, "utf-8").toString("base64url");
}

function b64urlDecode(value) {
  return Buffer.from(value, "base64url").toString("utf-8");
}

function hmac(data, secret) {
  return createHmac("sha256", String(secret)).update(data).digest("base64url");
}

function safeEqual(a, b) {
  const left = Buffer.from(String(a), "utf-8");
  const right = Buffer.from(String(b), "utf-8");
  if (left.length !== right.length) return false;
  return timingSafeEqual(left, right);
}

/**
 * Build the subprotocol string for WebSocket handshake.
 * Format: "eva-relay.v1|<token>"
 */
export function buildSubprotocol(token) {
  return `${SUBPROTOCOL}|${token}`;
}

/**
 * Extract token from subprotocol string.
 * Returns null if not in expected format.
 */
export function extractTokenFromSubprotocol(proto) {
  if (!proto || !proto.startsWith(`${SUBPROTOCOL}|`)) return null;
  return proto.slice(SUBPROTOCOL.length + 1);
}

/**
 * Mint a signed token.
 *
 * @param {object} input
 * @param {string} input.userId     Supabase user id owning the device
 * @param {string} input.deviceId   Paired device id
 * @param {string} input.secret     HMAC secret shared with the relay
 * @param {number} input.ttlSeconds Lifetime from now
 * @param {"access"|"refresh"|"pair"|"host"} [input.kind]
 * @param {string} [input.nonce]    Optional caller-supplied jti (pairing tokens pin one)
 * @returns {string} compact token "header.payload.signature"
 */
export function mintDeviceToken({ userId, deviceId, secret, ttlSeconds, kind = "access", nonce }) {
  if (!userId || !deviceId || !secret || !Number.isFinite(ttlSeconds) || ttlSeconds <= 0) {
    throw new Error("mintDeviceToken: userId, deviceId, secret and a positive ttlSeconds are required.");
  }
  const nowSeconds = Math.floor(Date.now() / 1000);
  const payload = b64urlEncode(
    JSON.stringify({
      uid: userId,
      did: deviceId,
      k: kind,
      iat: nowSeconds,
      exp: nowSeconds + Math.floor(ttlSeconds),
      jti: nonce || randomBytes(9).toString("base64url"),
    }),
  );
  const data = `${HEADER}.${payload}`;
  return `${data}.${hmac(data, secret)}`;
}

/**
 * Verify a token against the shared secret.
 *
 * Returns the decoded claims, or null for any failure (malformed, bad
 * signature, expired, wrong kind). Callers must never treat null as a
 * recoverable state — it is an outright rejection.
 *
 * @param {string} token
 * @param {string} secret
 * @param {{ kind?: "access"|"refresh"|"pair"|"host", nowSeconds?: number, maxClockSkewSeconds?: number }} [options]
 * @returns {{ uid: string, did: string, k: string, iat: number, exp: number, jti: string } | null}
 */
export function verifyDeviceToken(token, secret, options = {}) {
  if (typeof token !== "string" || token.length > 4096) return null;
  const parts = token.split(".");
  if (parts.length !== 3) return null;
  const [header, payload, signature] = parts;
  if (header !== HEADER) return null;
  if (!safeEqual(signature, hmac(`${header}.${payload}`, secret))) return null;

  let claims;
  try {
    claims = JSON.parse(b64urlDecode(payload));
  } catch {
    return null;
  }
  if (!claims || typeof claims !== "object") return null;
  if (typeof claims.uid !== "string" || typeof claims.did !== "string") return null;
  if (typeof claims.iat !== "number" || typeof claims.exp !== "number") return null;

  const now = options.nowSeconds ?? Math.floor(Date.now() / 1000);
  const skew = options.maxClockSkewSeconds ?? 60;
  if (now > claims.exp + skew) return null;
  if (claims.iat - skew > now) return null;
  if (options.kind && claims.k !== options.kind) return null;
  if (claims.k !== "access" && claims.k !== "refresh" && claims.k !== "pair" && claims.k !== "host") return null;

  return {
    uid: claims.uid,
    did: claims.did,
    k: claims.k,
    iat: claims.iat,
    exp: claims.exp,
    jti: typeof claims.jti === "string" ? claims.jti : "",
  };
}

/** Seconds until a token expires (negative once expired). */
export function tokenExpiresInSeconds(token) {
  const parts = typeof token === "string" ? token.split(".") : [];
  if (parts.length !== 3) return null;
  try {
    const claims = JSON.parse(b64urlDecode(parts[1]));
    return typeof claims.exp === "number" ? claims.exp - Math.floor(Date.now() / 1000) : null;
  } catch {
    return null;
  }
}

export { SUBPROTOCOL };
