/**
 * Feature registration for Remote Control.
 *
 * Called once from server.ts. When the feature is disabled (default) this
 * registers nothing at all: no routes, no connector, no timers.
 *
 * When enabled it wires:
 *   - RemoteGateway      dispatch/authorization for phone envelopes
 *   - RelayConnector     outbound-only PC -> relay WebSocket (host token)
 *   - PairingService     email link -> claim -> local approval
 *   - /api/remote/*      LOCAL-ONLY REST for the PC's own dashboard UI
 *                        (list devices, start pairing, approve/deny/revoke)
 *
 * The REST surface is additionally guarded by `requireLoopback` so it can
 * never be reached through a port-forward or the relay itself.
 */
import type { Express, NextFunction, Request, Response } from "express";
import { requireAuth, type AuthedRequest } from "../auth/authRoutes";
import { requireOwner } from "../auth/adminAuth";
import { getSupabase, supabaseConfigured } from "../auth/supabaseClient";
import { remoteConfig, type RemoteConfig } from "./config";
import { createDeviceStore, type DeviceStore } from "./devices";
import { RemoteGateway } from "./gateway";
import { PairingService } from "./pairing";
import { RelayConnector } from "./relayConnector";
import { installId, mintHost } from "./tokens";
import { createLogger } from "../shared/logger";

const log = createLogger("remote");

export interface RemoteAccessHandle {
  cfg: RemoteConfig;
  store: DeviceStore;
  pairing: PairingService;
  gateway: RemoteGateway;
  connector: RelayConnector;
  shutdown: () => void;
}

/** Reject anything that is not loopback. Defense in depth on top of the
 *  server binding to 127.0.0.1 for these routes. */
function requireLoopback(req: Request, res: Response, next: NextFunction): void {
  const address = req.socket?.remoteAddress || "";
  const isLoopback = address === "127.0.0.1" || address === "::1" || address === "::ffff:127.0.0.1";
  if (!isLoopback) {
    res.status(403).json({ error: "This endpoint is only available on the local computer." });
    return;
  }
  next();
}

export function registerRemoteAccess(app: Express, dataDir: string, bridges: {
  tasks: ConstructorParameters<typeof RemoteGateway>[0]["tasks"];
  confirmations: ConstructorParameters<typeof RemoteGateway>[0]["confirmations"];
  callAgent: ConstructorParameters<typeof RemoteGateway>[0]["callAgent"];
}): RemoteAccessHandle | null {
  const cfg = remoteConfig(dataDir);
  if (!cfg.enabled) {
    log.info("remote access disabled (set EVA_ENABLE_REMOTE=true and EVA_RELAY_URL to enable)");
    return null;
  }

  const store = createDeviceStore(dataDir);

  let gateway!: RemoteGateway; // assigned below; PairingService events reference it lazily

  const connector = new RelayConnector({
    relayUrl: cfg.relayUrl,
    hostToken: mintHost(cfg, installId(dataDir)),
    rooms: () => store.ownerIds(),
    onEnvelope: (raw) => gateway.handleRaw(raw),
    onStatus: (connected) => log.info(connected ? "relay connected" : "relay disconnected"),
  });

  const pairing = new PairingService(cfg, store, (event) => {
    if (event.type === "pairing.approved") gateway.notifyPairingApproved(event.device);
    else if (event.type === "pairing.revoked") gateway.notifyPairingRevoked(event.device);
    else if (event.type === "pairing.started") connector.refreshRooms();
    log.info(`pairing ${event.type}`, { device: event.device.name, status: event.device.status });
  });

  gateway = new RemoteGateway({
    cfg,
    store,
    pairing,
    send: (deviceId, envelope) => connector.send(envelope),
    connected: () => connector.connected,
    tasks: bridges.tasks,
    confirmations: bridges.confirmations,
    callAgent: bridges.callAgent,
    verifyUser: supabaseConfigured
      ? async (token: string) => {
          const { data, error } = await getSupabase().auth.getUser(token);
          return error || !data.user ? null : data.user.id;
        }
      : undefined,
    log: (message, extra) => log.warn(message, extra),
  });

  // -------------------------------------------------------------------------
  // PC-local REST (dashboard UI + pairing approval live here)
  // -------------------------------------------------------------------------

  // Status probe (loopback only, OWNER only): tells the dashboard whether the
  // feature is on without leaking configuration.
  app.get("/api/remote/status", requireLoopback, requireOwner, (_req: Request, res: Response) => {
    res.json({
      enabled: true,
      relayConnected: connector.connected,
      deviceBackend: store.backend,
      smtpConfigured: Boolean(cfg.smtpUrl),
    });
  });

  // Everything below requires a signed-in OWNER user AND loopback.
  const guard = [requireLoopback, requireOwner];

  app.get("/api/remote/devices", ...guard, async (req: AuthedRequest, res: Response) => {
    try {
      const devices = await store.listForUser(req.userId!);
      // Live relay presence for THIS user's devices only (never other users').
      const live = new Set(gateway.connectedDeviceIds());
      res.json({
        devices,
        connectedIds: devices.filter((d) => live.has(d.id)).map((d) => d.id),
      });
    } catch (error) {
      res.status(500).json({ error: error instanceof Error ? error.message : "Could not list devices." });
    }
  });

  app.post("/api/remote/pair/start", ...guard, async (req: AuthedRequest, res: Response) => {
    try {
      const label = String(req.body?.name || "New device");
      const result = await pairing.start(req.userId!, req.userEmail ?? null, label);
      res.json(result);
    } catch (error) {
      res.status(500).json({ error: error instanceof Error ? error.message : "Could not start pairing." });
    }
  });

  app.post("/api/remote/devices/:id/approve", ...guard, async (req: AuthedRequest, res: Response) => {
    try {
      const device = await pairing.approve(req.userId!, String(req.params.id));
      if (!device) {
        res.status(404).json({ error: "No pending device with that id." });
        return;
      }
      res.json({ device });
    } catch (error) {
      res.status(500).json({ error: error instanceof Error ? error.message : "Could not approve device." });
    }
  });

  app.post("/api/remote/devices/:id/deny", ...guard, async (req: AuthedRequest, res: Response) => {
    try {
      const device = await pairing.deny(req.userId!, String(req.params.id));
      if (!device) {
        res.status(404).json({ error: "No pending device with that id." });
        return;
      }
      res.json({ device });
    } catch (error) {
      res.status(500).json({ error: error instanceof Error ? error.message : "Could not deny device." });
    }
  });

  app.post("/api/remote/devices/:id/revoke", ...guard, async (req: AuthedRequest, res: Response) => {
    try {
      const device = await pairing.revoke(req.userId!, String(req.params.id));
      if (!device) {
        res.status(404).json({ error: "Unknown device." });
        return;
      }
      res.json({ device });
    } catch (error) {
      res.status(500).json({ error: error instanceof Error ? error.message : "Could not revoke device." });
    }
  });

  // -------------------------------------------------------------------------
  // Go live. The connector starts only after the device store has finished
  // loading: the first `host.hello` binds relay rooms from store.ownerIds(),
  // and binding before the store is ready would leave the PC unreachable to
  // a phone that pairs immediately after boot (until the 30s room refresh).
  // -------------------------------------------------------------------------

  void store.initialize()
    .catch((error) => {
      log.error("device store init failed", { error: error instanceof Error ? error.message : String(error) });
    })
    .finally(() => {
      connector.start();
      log.info("remote access enabled", { relay: cfg.relayUrl });
    });

  return {
    cfg,
    store,
    pairing,
    gateway,
    connector,
    shutdown: () => connector.stop(),
  };
}
