/**
 * JARVIS — Feature Management REST API.
 *
 * All endpoints are backend-enforced:
 *  - Read access to the registry is OWNER/ADMIN (the Feature Management section
 *    lives in the Owner console).
 *  - Mutations (activate / disable / retry / refresh) are OWNER-only.
 *  - Nothing here exposes secrets, and no endpoint installs arbitrary code.
 *
 * The frontend Feature Management dashboard consumes this API; the backend
 * remains the security boundary — hiding a button is never the authorization.
 *
 * Route ordering matters: the literal paths (/api/features/active,
 * /api/features/config) are registered before the parameterised /:id so they
 * are never swallowed by the catch-all.
 */
import type { Express, Request, Response } from "express";
import type { FeatureRegistry } from "./registry";
import { requireOwner, requireAdminOrOwner, type AdminAuthedRequest } from "../auth/adminAuth";
import { requireAuth, type AuthedRequest } from "../auth/authRoutes";
import { supabaseConfigured } from "../auth/supabaseClient";

export interface FeatureRoutesOptions {
  registry: FeatureRegistry;
  /** Where to send a notification for owner action / failure. */
  notify?: (title: string, body: string) => void;
}

export function registerFeatureRoutes(app: Express, options: FeatureRoutesOptions): void {
  const { registry, notify } = options;

  // ---------------------------------------------------------------------------
  // Public-ish (authenticated user) surface: which active features have a
  // frontend entry and what navigation they contribute. This is what the
  // renderer launcher renders. It never exposes manifests, tools or secrets —
  // only the user-facing presence of an active feature.
  // ---------------------------------------------------------------------------
  app.get("/api/features/active", requireAuth, (_req: AuthedRequest, res: Response) => {
    const active = registry.activeFrontend();
    res.json({
      appVersion: process.env.EVA_APP_VERSION || "1.0.0",
      features: active.map((manifest) => ({
        id: manifest.id,
        name: manifest.name,
        version: manifest.version,
        description: manifest.description,
        navigation: manifest.navigation,
        frontendEntry: manifest.frontendEntry,
        settings: manifest.settings,
      })),
    });
  });

  // A tiny "features configured" probe for the renderer to know the API exists
  // even before auth is fully wired (never leaks feature internals).
  app.get("/api/features/config", (_req: Request, res: Response) => {
    res.json({ configured: true, supabaseConfigured });
  });

  // ---------------------------------------------------------------------------
  // Read: list / single feature. Admin or Owner (dashboard is in the console).
  // ---------------------------------------------------------------------------
  app.get("/api/features", requireAdminOrOwner, (_req: AdminAuthedRequest, res: Response) => {
    try {
      res.json({
        appVersion: process.env.EVA_APP_VERSION || "1.0.0",
        features: registry.list(),
      });
    } catch (error) {
      res.status(500).json({ error: error instanceof Error ? error.message : "Could not load features." });
    }
  });

  app.get("/api/features/:id", requireAdminOrOwner, (req: AdminAuthedRequest, res: Response) => {
    const feature = registry.get(String(req.params.id));
    if (!feature) return res.status(404).json({ error: "Feature not found." });
    res.json(feature);
  });

  // ---------------------------------------------------------------------------
  // Owner-only mutations
  // ---------------------------------------------------------------------------

  // Activate a feature (Owner). In production this is the approval action.
  app.post("/api/features/:id/activate", requireOwner, async (req: AdminAuthedRequest, res: Response) => {
    try {
      const feature = await registry.activate(String(req.params.id));
      notify?.(`Feature activated`, `"${feature.manifest.name}" v${feature.manifest.version} is now active.`);
      res.json(feature);
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      res.status(409).json({ error: message });
    }
  });

  // Disable a feature (Owner). Keeps data; removes registrations.
  app.post("/api/features/:id/disable", requireOwner, async (req: AdminAuthedRequest, res: Response) => {
    try {
      const feature = await registry.disable(String(req.params.id));
      notify?.(`Feature disabled`, `"${feature.manifest.name}" is disabled. Its data is preserved.`);
      res.json(feature);
    } catch (error) {
      res.status(409).json({ error: error instanceof Error ? error.message : String(error) });
    }
  });

  // Re-discover / re-validate a feature's manifest on disk (Owner).
  app.post("/api/features/:id/refresh", requireOwner, async (req: AdminAuthedRequest, res: Response) => {
    try {
      const feature = await registry.refresh(String(req.params.id));
      res.json(feature);
    } catch (error) {
      res.status(400).json({ error: error instanceof Error ? error.message : String(error) });
    }
  });

  // Health probe (Owner).
  app.get("/api/features/:id/health", requireOwner, async (req: AdminAuthedRequest, res: Response) => {
    const ok = await registry.checkHealth(String(req.params.id));
    res.json({ ok });
  });
}
