/**
 * Loads .env as early as possible.
 *
 * server.ts must import this FIRST, before any module that reads
 * process.env at module-evaluation time (auth/workspaceRoutes.ts,
 * auth/mem0Service.ts (now local memory service), auth/supabaseClient.ts). Otherwise the imported
 * modules capture empty values and keys supplied via .env are ignored.
 *
 * Two locations are supported:
 *  - the working directory (.env), for development and `npm run serve`.
 *  - EVA_DATA_DIR/.env, for the packaged desktop app, which ships no .env.
 *    Keys live in %APPDATA%\Eva on each PC, so a user can set integration
 *    keys (e.g. COMPOSIO_API_KEY) there without rebuilding the app.
 *
 * Values already present in the real environment are never overwritten.
 */
import fs from "fs";
import path from "path";
import dotenv from "dotenv";

// Working-directory .env first (dotenv does not override existing vars).
dotenv.config();

// Per-user .env shipped next to the app's writable data folder.
const dataDir = process.env.EVA_DATA_DIR;
if (dataDir) {
  const userEnv = path.join(dataDir, ".env");
  try {
    if (fs.existsSync(userEnv)) dotenv.config({ path: userEnv });
  } catch {
    /* unreadable user .env — fall back to the real environment */
  }
}
