/**
 * Remote-control configuration.
 *
 * Every value comes from the environment; nothing here is a secret *source*
 * (the HMAC secret and agent token are loaded/generated on disk by
 * `secretFrom` helpers below and never serialized to the client).
 *
 * The feature is opt-in: `EVA_ENABLE_REMOTE=true` plus a configured relay URL
 * are both required before any remote surface is registered.
 */
import fs from "node:fs";
import path from "node:path";
import { randomBytes } from "node:crypto";

export interface RemoteConfig {
  enabled: boolean;
  /** WSS endpoint of the EVA relay, e.g. wss://relay.example.com */
  relayUrl: string;
  /** HMAC secret shared with the relay for device tokens. */
  hmacSecret: string;
  /** Shared secret required on every desktop-agent HTTP call. */
  agentToken: string;
  /** Base URL used when composing emailed pairing links. */
  appUrl: string;
  smtpUrl: string;
  smtpFrom: string;
  rateLimitPerMinute: number;
  maxStreamFps: number;
  fileRoots: string[];
  uploadMaxBytes: number;
}

const FLAG_TRUE = /^(1|true|yes|on)$/i;

function positiveInt(value: string | undefined, fallback: number): number {
  const parsed = Number(value);
  return Number.isFinite(parsed) && parsed > 0 ? Math.floor(parsed) : fallback;
}

/** Load-or-generate a durable local secret (hex file under `dir`). */
export function loadOrCreateSecret(filePath: string, bytes = 32): string {
  try {
    const existing = fs.readFileSync(filePath, "utf-8").trim();
    // Exactly `bytes` hex characters; anything else is corrupt and replaced.
    if (new RegExp(`^[0-9a-f]{${bytes * 2}}$`, "i").test(existing)) return existing;
  } catch {
    /* missing file — fall through to creation */
  }
  const generated = randomBytes(bytes).toString("hex");
  try {
    fs.mkdirSync(path.dirname(filePath), { recursive: true });
    fs.writeFileSync(filePath, `${generated}\n`, { encoding: "utf-8", mode: 0o600 });
  } catch {
    /* read-only data dir: the process-lifetime secret still works */
  }
  return generated;
}

let cached: RemoteConfig | null = null;

export function remoteConfig(dataDir: string): RemoteConfig {
  if (cached) return cached;
  const relayUrl = (process.env.EVA_RELAY_URL || "").trim().replace(/\/+$/, "");
  const enabled = FLAG_TRUE.test(process.env.EVA_ENABLE_REMOTE || "") && relayUrl.length > 0;
  const configuredRoots = (process.env.EVA_REMOTE_FILE_ROOTS || "")
    .split(",")
    .map((entry) => entry.trim())
    .filter(Boolean);

  cached = {
    enabled,
    relayUrl,
    hmacSecret: (process.env.EVA_RELAY_HMAC_SECRET || "").trim()
      || loadOrCreateSecret(path.join(dataDir, "remote", "relay.secret")),
    agentToken: loadOrCreateSecret(path.join(dataDir, "remote", "agent.token")),
    appUrl: (process.env.EVA_APP_URL || process.env.APP_URL || "").trim().replace(/\/+$/, ""),
    smtpUrl: (process.env.EVA_SMTP_URL || "").trim(),
    smtpFrom: (process.env.EVA_SMTP_FROM || "EVA-JARVIS <no-reply@eva.local>").trim(),
    rateLimitPerMinute: positiveInt(process.env.EVA_REMOTE_RATE_LIMIT, 120),
    maxStreamFps: positiveInt(process.env.EVA_REMOTE_MAX_STREAM_FPS, 15),
    fileRoots: configuredRoots,
    uploadMaxBytes: positiveInt(process.env.EVA_REMOTE_UPLOAD_MAX_BYTES, 50 * 1024 * 1024),
  };
  return cached;
}

/** Test hook: forget the memoized config so a new dataDir/env applies. */
export function resetRemoteConfigForTests(): void {
  cached = null;
}

export const REMOTE_ERRORS = {
  disabled: "Remote access is disabled on this instance.",
  unauthorized: "Sign in to continue.",
  deviceRequired: "A paired device credential is required.",
  deviceRevoked: "This device no longer has access. Pair it again.",
  deviceUnknown: "Unknown device.",
  forbidden: "You do not have access to that resource.",
  notFound: "Not found.",
  rateLimited: "Too many requests. Slow down.",
  pairingExpired: "That pairing link is invalid, used, or expired.",
  pairingNeedsApproval: "Waiting for approval on the PC.",
  relayUnreachable: "The relay is unreachable from this computer.",
  sessionExpired: "Your session expired. Pair this device again.",
} as const;
