/**
 * JARVIS — administrative REST routes.
 *
 * Every endpoint is protected by backend-enforced role checks.
 * - OWNER-only endpoints require verified Owner authorization.
 * - ADMIN endpoints accept verified Owner or Admin authorization.
 * - Role changes are audited and sessions are invalidated.
 */

import type { Express, Response } from "express";
import type { SupabaseClient } from "@supabase/supabase-js";
import { requireAdminRole, requireOwner, requireAdminOrOwner, type AdminAuthedRequest } from "./adminAuth";
import { requireAdmin as requireAdminClient, supabase } from "./supabaseClient";
import { analyzeMessage } from "./safetyMonitor";
import { AUTH_ERRORS } from "./authRoutes";

interface TargetProfile {
  admin_role: "OWNER" | "ADMIN" | null;
}

/**
 * Read a target account's administrative role.
 *
 * NOTE: profiles has NO email column — email lives in auth.users. Selecting a
 * nonexistent column made PostgREST error out and every role-management call
 * reported "User not found". The error is surfaced instead of swallowed.
 */
async function loadTargetProfile(admin: SupabaseClient, targetId: string): Promise<TargetProfile | null> {
  const { data, error } = await admin
    .from("profiles")
    .select("admin_role")
    .eq("id", targetId)
    .maybeSingle();
  if (error) throw new Error(`Could not read target profile: ${error.message}`);
  return (data as TargetProfile | null) ?? null;
}

/** Resolve a target's email from the authoritative store (auth.users). */
async function loadTargetEmail(admin: SupabaseClient, targetId: string): Promise<string | null> {
  try {
    const { data } = await admin.auth.admin.getUserById(targetId);
    return data.user?.email ?? null;
  } catch {
    return null;
  }
}

/**
 * True when a Supabase/PostgREST error means the TABLE does not exist,
 * rather than a permission or transient failure.
 *
 * This is how a missing database migration presents itself, and it needs a
 * different remedy (apply the migration) from every other error.
 */
export function isMissingTableError(error: unknown): boolean {
  if (!error || typeof error !== "object") return false;
  const e = error as { code?: string; message?: string; details?: string; hint?: string };
  if (e.code === "42P01" || e.code === "PGRST205") return true;
  const text = `${e.message || ""} ${e.details || ""} ${e.hint || ""}`;
  return /does not exist|not found in the schema cache|relation .* does not exist/i.test(text);
}

export function registerAdminRoutes(app: Express): void {
  if (!supabase) return; // Supabase not configured

  // ========================================================================
  // USER DIRECTORY (Admin + Owner)
  // ========================================================================

  // List all users with their admin roles (Owner sees all, Admin sees permitted)
  app.get("/api/admin/users", requireAdminOrOwner, async (req: AdminAuthedRequest, res: Response) => {
    try {
      const admin = requireAdminClient();
      const { data, error } = await admin.rpc("get_all_users_with_roles");

      if (error) {
        console.error("[Admin] get_all_users_with_roles failed:", error.message);
        return res.status(500).json({ error: "Could not load user directory." });
      }

      // Filter: Admins cannot see Owner accounts (only Owner can)
      const filtered = (data || []).filter((user: any) => {
        if (req.adminRole === "OWNER") return true;
        // Admin: hide Owner accounts
        return user.admin_role !== "OWNER";
      });

      res.json({ users: filtered });
    } catch (err) {
      console.error("[Admin] users list error:", err);
      res.status(500).json({ error: "Could not load user directory." });
    }
  });

  // Get single user details (Admin + Owner)
  app.get("/api/admin/users/:userId", requireAdminOrOwner, async (req: AdminAuthedRequest, res: Response) => {
    try {
      const targetId = req.params.userId;
      const admin = requireAdminClient();

      // Check if target is Owner and requester is Admin
      const targetProfile = await loadTargetProfile(admin, targetId);

      if (!targetProfile) {
        return res.status(404).json({ error: "User not found." });
      }

      // Admins cannot view Owner accounts
      if (req.adminRole === "ADMIN" && targetProfile.admin_role === "OWNER") {
        return res.status(403).json({ error: "Cannot view Owner accounts." });
      }

      // Get full user details
      const { data: authUser } = await admin.auth.admin.getUserById(targetId);
      if (!authUser.user) {
        return res.status(404).json({ error: "User not found." });
      }

      const { data: profile } = await admin
        .from("profiles")
        .select("*")
        .eq("id", targetId)
        .maybeSingle();

      const { data: memorySettings } = await admin
        .from("user_memory_settings")
        .select("*")
        .eq("user_id", targetId)
        .maybeSingle();

      const { data: prefs } = await admin
        .from("user_preferences")
        .select("*")
        .eq("user_id", targetId)
        .maybeSingle();

      const { data: connections } = await admin
        .from("integration_connections")
        .select("provider, status, created_at")
        .eq("user_id", targetId);

      const { data: files } = await admin
        .from("user_files")
        .select("id, file_name, kind, size_bytes, created_at")
        .eq("user_id", targetId)
        .order("created_at", { ascending: false })
        .limit(10);

      const { data: conversations } = await admin
        .from("conversations")
        .select("id, title, updated_at")
        .eq("user_id", targetId)
        .order("updated_at", { ascending: false })
        .limit(10);

      const { data: activity } = await admin
        .from("user_activity")
        .select("event_type, summary, created_at")
        .eq("user_id", targetId)
        .order("created_at", { ascending: false })
        .limit(20);

      res.json({
        user: {
          id: authUser.user.id,
          email: authUser.user.email,
          last_sign_in_at: authUser.user.last_sign_in_at,
          created_at: authUser.user.created_at,
        },
        profile,
        memorySettings,
        preferences: prefs,
        connections: connections || [],
        files: files || [],
        conversations: conversations || [],
        activity: activity || [],
      });
    } catch (err) {
      console.error("[Admin] user detail error:", err);
      res.status(500).json({ error: "Could not load user details." });
    }
  });

  // ========================================================================
  // ROLE MANAGEMENT (Owner only)
  // ========================================================================

  // Promote user to Admin
  app.post("/api/admin/users/:userId/promote-admin", requireOwner, async (req: AdminAuthedRequest, res: Response) => {
    try {
      const targetId = req.params.userId;
      const requesterId = req.userId!;

      if (targetId === requesterId) {
        return res.status(400).json({ error: "Cannot promote yourself." });
      }

      const admin = requireAdminClient();

      // Verify target exists and get current role
      const targetProfile = await loadTargetProfile(admin, targetId);

      if (!targetProfile) {
        return res.status(404).json({ error: "User not found." });
      }

      if (targetProfile.admin_role === "OWNER") {
        return res.status(400).json({ error: "Cannot promote an Owner." });
      }

      if (targetProfile.admin_role === "ADMIN") {
        return res.status(400).json({ error: "User is already an Admin." });
      }

      // Promote
      const { error: promoteError } = await admin.rpc("promote_to_admin", { p_target_user_id: targetId });
      if (promoteError) throw promoteError;

      const targetEmail = await loadTargetEmail(admin, targetId);

      // Audit log
      await admin.rpc("log_admin_action", {
        p_actor_id: requesterId,
        p_actor_email: req.userEmail,
        p_target_id: targetId,
        p_target_email: targetEmail,
        p_action: "PROMOTE_ADMIN",
        p_previous_role: targetProfile.admin_role,
        p_new_role: "ADMIN",
        p_metadata: { promoted_by: requesterId },
      });

      res.json({ ok: true, message: "User promoted to Admin." });
    } catch (err: any) {
      console.error("[Admin] promote admin error:", err);
      res.status(500).json({ error: err.message || "Could not promote user." });
    }
  });

  // Demote Admin to regular user
  app.post("/api/admin/users/:userId/demote-admin", requireOwner, async (req: AdminAuthedRequest, res: Response) => {
    try {
      const targetId = req.params.userId;
      const requesterId = req.userId!;

      if (targetId === requesterId) {
        return res.status(400).json({ error: "Cannot demote yourself." });
      }

      const admin = requireAdminClient();

      // Verify target is Admin
      const targetProfile = await loadTargetProfile(admin, targetId);

      if (!targetProfile) {
        return res.status(404).json({ error: "User not found." });
      }

      if (targetProfile.admin_role !== "ADMIN") {
        return res.status(400).json({ error: "User is not an Admin." });
      }

      // Demote
      const { error: demoteError } = await admin.rpc("demote_admin", { p_target_user_id: targetId });
      if (demoteError) throw demoteError;

      const targetEmail = await loadTargetEmail(admin, targetId);

      // Audit log
      await admin.rpc("log_admin_action", {
        p_actor_id: requesterId,
        p_actor_email: req.userEmail,
        p_target_id: targetId,
        p_target_email: targetEmail,
        p_action: "DEMOTE_ADMIN",
        p_previous_role: "ADMIN",
        p_new_role: null,
        p_metadata: { demoted_by: requesterId },
      });

      res.json({ ok: true, message: "Admin demoted to regular user." });
    } catch (err: any) {
      console.error("[Admin] demote admin error:", err);
      res.status(500).json({ error: err.message || "Could not demote user." });
    }
  });

  // Promote user to Owner (Owner only, with audit)
  app.post("/api/admin/users/:userId/promote-owner", requireOwner, async (req: AdminAuthedRequest, res: Response) => {
    try {
      const targetId = req.params.userId;
      const requesterId = req.userId!;

      if (targetId === requesterId) {
        return res.status(400).json({ error: "Cannot promote yourself to Owner." });
      }

      const admin = requireAdminClient();

      // Verify target exists
      const targetProfile = await loadTargetProfile(admin, targetId);

      if (!targetProfile) {
        return res.status(404).json({ error: "User not found." });
      }

      if (targetProfile.admin_role === "OWNER") {
        return res.status(400).json({ error: "User is already an Owner." });
      }

      // Promote
      const { error: promoteError } = await admin.rpc("promote_to_owner", { p_target_user_id: targetId });
      if (promoteError) throw promoteError;

      const targetEmail = await loadTargetEmail(admin, targetId);

      // Audit log
      await admin.rpc("log_admin_action", {
        p_actor_id: requesterId,
        p_actor_email: req.userEmail,
        p_target_id: targetId,
        p_target_email: targetEmail,
        p_action: "PROMOTE_OWNER",
        p_previous_role: targetProfile.admin_role,
        p_new_role: "OWNER",
        p_metadata: { promoted_by: requesterId },
      });

      res.json({ ok: true, message: "User promoted to Owner." });
    } catch (err: any) {
      console.error("[Admin] promote owner error:", err);
      res.status(500).json({ error: err.message || "Could not promote user to Owner." });
    }
  });

  // Revoke Owner access (Owner only, with last-Owner protection)
  app.post("/api/admin/users/:userId/revoke-owner", requireOwner, async (req: AdminAuthedRequest, res: Response) => {
    try {
      const targetId = req.params.userId;
      const requesterId = req.userId!;

      if (targetId === requesterId) {
        return res.status(400).json({ error: "Cannot revoke your own Owner access. Transfer ownership first." });
      }

      const admin = requireAdminClient();

      // Verify target is Owner
      const targetProfile = await loadTargetProfile(admin, targetId);

      if (!targetProfile) {
        return res.status(404).json({ error: "User not found." });
      }

      if (targetProfile.admin_role !== "OWNER") {
        return res.status(400).json({ error: "User is not an Owner." });
      }

      // Revoke (includes last-Owner protection)
      const { error: revokeError } = await admin.rpc("revoke_owner", { p_target_user_id: targetId, p_requester_id: requesterId });
      if (revokeError) throw revokeError;

      const targetEmail = await loadTargetEmail(admin, targetId);

      // Audit log
      await admin.rpc("log_admin_action", {
        p_actor_id: requesterId,
        p_actor_email: req.userEmail,
        p_target_id: targetId,
        p_target_email: targetEmail,
        p_action: "REVOKE_OWNER",
        p_previous_role: "OWNER",
        p_new_role: null,
        p_metadata: { revoked_by: requesterId },
      });

      res.json({ ok: true, message: "Owner access revoked." });
    } catch (err: any) {
      console.error("[Admin] revoke owner error:", err);
      // Postgres raises insufficient_privilege (SQLSTATE 42501) for self-revoke
      // and last-Owner protection; surface it as a 403, not a 500.
      const code = err?.code ?? "";
      const message = String(err?.message ?? "Could not revoke Owner access.");
      if (code === "42501" || code === "insufficient_privilege" || /Owner access|last active Owner/i.test(message)) {
        return res.status(403).json({ error: message });
      }
      res.status(500).json({ error: message || "Could not revoke Owner access." });
    }
  });

  // ========================================================================
  // USER ACCOUNT MANAGEMENT (Admin + Owner for suspension)
  // ========================================================================

  // Suspend user account (Admin + Owner)
  app.post("/api/admin/users/:userId/suspend", requireAdminOrOwner, async (req: AdminAuthedRequest, res: Response) => {
    try {
      const targetId = req.params.userId;
      const requesterId = req.userId!;

      if (targetId === requesterId) {
        return res.status(400).json({ error: "Cannot suspend yourself." });
      }

      const admin = requireAdminClient();

      // Verify target exists and is not Owner
      const targetProfile = await loadTargetProfile(admin, targetId);

      if (!targetProfile) {
        return res.status(404).json({ error: "User not found." });
      }

      // Admins cannot suspend Owners
      if (req.adminRole === "ADMIN" && targetProfile.admin_role === "OWNER") {
        return res.status(403).json({ error: "Cannot suspend an Owner." });
      }

      // Suspend via Supabase Auth admin
       const { error } = await admin.auth.admin.updateUserById(targetId, { app_metadata: { suspended: true } });
      if (error) throw error;

      res.json({ ok: true, message: "User account suspended." });
    } catch (err: any) {
      console.error("[Admin] suspend error:", err);
      res.status(500).json({ error: err.message || "Could not suspend user." });
    }
  });

  // Reinstate user account (Admin + Owner)
  app.post("/api/admin/users/:userId/reinstate", requireAdminOrOwner, async (req: AdminAuthedRequest, res: Response) => {
    try {
      const targetId = req.params.userId;
      const admin = requireAdminClient();

      // Verify target exists; Admins may not touch Owner accounts.
      const targetProfile = await loadTargetProfile(admin, targetId);
      if (!targetProfile) {
        return res.status(404).json({ error: "User not found." });
      }
      if (req.adminRole === "ADMIN" && targetProfile.admin_role === "OWNER") {
        return res.status(403).json({ error: "Cannot reinstate an Owner." });
      }

      const { error } = await admin.auth.admin.updateUserById(targetId, { app_metadata: { suspended: false } });
      if (error) throw error;

      res.json({ ok: true, message: "User account reinstated." });
    } catch (err: any) {
      console.error("[Admin] reinstate error:", err);
      res.status(500).json({ error: err.message || "Could not reinstate user." });
    }
  });

  // ========================================================================
  // AUDIT LOG (Owner only)
  // ========================================================================

  app.get("/api/admin/audit-log", requireOwner, async (req: AdminAuthedRequest, res: Response) => {
    try {
      const limit = Math.min(Number(req.query.limit) || 100, 500);
      const offset = Number(req.query.offset) || 0;

      const admin = requireAdminClient();
      const { data, error } = await admin
        .from("admin_audit_log")
        .select("*")
        .order("created_at", { ascending: false })
        .range(offset, offset + limit - 1);

      if (error) throw error;

      res.json({ entries: data || [], limit, offset });
    } catch (err) {
      console.error("[Admin] audit log error:", err);
      res.status(500).json({ error: "Could not load audit log." });
    }
  });

  // ========================================================================
  // PLATFORM ANALYTICS (Owner only)
  // ========================================================================

  app.get("/api/admin/analytics", requireOwner, async (req: AdminAuthedRequest, res: Response) => {
    try {
      const admin = requireAdminClient();

      // Total users
      const { count: totalUsers } = await admin
        .from("profiles")
        .select("*", { count: "exact", head: true });

      // Users by role
      const { data: roleCounts } = await admin
        .from("profiles")
        .select("admin_role");

      const roleStats = (roleCounts || []).reduce((acc: Record<string, number>, row: any) => {
        const role = row.admin_role || "USER";
        acc[role] = (acc[role] || 0) + 1;
        return acc;
      }, {});

      // Active users (signed in last 30 days)
      const thirtyDaysAgo = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString();
      const { count: activeUsers } = await admin
        .from("profiles")
        .select("*", { count: "exact", head: true })
        .gte("updated_at", thirtyDaysAgo);

      // Conversations count
      const { count: totalConversations } = await admin
        .from("conversations")
        .select("*", { count: "exact", head: true });

      // Messages count
      const { count: totalMessages } = await admin
        .from("conversation_messages")
        .select("*", { count: "exact", head: true });

      // Files count
      const { count: totalFiles } = await admin
        .from("user_files")
        .select("*", { count: "exact", head: true });

      // Integration connections
      const { count: totalConnections } = await admin
        .from("integration_connections")
        .select("*", { count: "exact", head: true })
        .eq("status", "connected");

      // Storage usage
      const { data: storageUsage } = await admin
        .from("user_files")
        .select("size_bytes")
        .not("size_bytes", "is", null);

      const totalStorageBytes = (storageUsage || []).reduce((sum: number, row: any) => sum + Number(row.size_bytes || 0), 0);

      res.json({
        users: {
          total: totalUsers || 0,
          active: activeUsers || 0,
          byRole: roleStats,
        },
        conversations: totalConversations || 0,
        messages: totalMessages || 0,
        files: {
          count: totalFiles || 0,
          storageBytes: totalStorageBytes,
          storageGB: Math.round(totalStorageBytes / 1024 / 1024 / 1024 * 100) / 100,
        },
        integrations: totalConnections || 0,
        generatedAt: new Date().toISOString(),
      });
    } catch (err) {
      console.error("[Admin] analytics error:", err);
      res.status(500).json({ error: "Could not load analytics." });
    }
  });

  // ========================================================================
  // SYSTEM HEALTH (Owner only)
  // ========================================================================

  app.get("/api/admin/system-health", requireOwner, async (req: AdminAuthedRequest, res: Response) => {
    try {
      const admin = requireAdminClient();

      // Check Supabase connection
      const { error: dbError } = await admin.from("profiles").select("id").limit(1);
      const dbHealthy = !dbError;

      // Check auth
      const { data: authTest } = await admin.auth.admin.listUsers({ page: 1, perPage: 1 });
      const authHealthy = !!authTest;

      // Check storage
      const { data: buckets } = await admin.storage.listBuckets();
      const storageHealthy = Array.isArray(buckets);

      res.json({
        database: dbHealthy ? "healthy" : "degraded",
        auth: authHealthy ? "healthy" : "degraded",
        storage: storageHealthy ? "healthy" : "degraded",
        timestamp: new Date().toISOString(),
      });
    } catch (err) {
      console.error("[Admin] system health error:", err);
      res.status(500).json({ error: "Could not load system health." });
    }
  });

  // ========================================================================
  // SAFETY / MODERATION (Admin + Owner)
  // ========================================================================

  // Get safety incidents / guardrail triggers (Admin + Owner)
  app.get("/api/admin/safety-incidents", requireAdminOrOwner, async (req: AdminAuthedRequest, res: Response) => {
    try {
      const limit = Math.min(Number(req.query.limit) || 50, 200);
      const offset = Math.max(Number(req.query.offset) || 0, 0);
      const status = typeof req.query.status === "string" ? req.query.status : null;
      const category = typeof req.query.category === "string" ? req.query.category : null;
      const severity = typeof req.query.severity === "string" ? req.query.severity : null;

      const admin = requireAdminClient();

      let query = admin
        .from("safety_incidents")
        .select("id, user_id, scope_id, origin, category, severity, summary, snippet, matched_terms, status, notes, created_at, updated_at, resolved_at, resolved_by", { count: "exact" })
        .order("created_at", { ascending: false })
        .range(offset, offset + limit - 1);
      if (status) query = query.eq("status", status);
      if (category) query = query.eq("category", category);
      if (severity) query = query.eq("severity", severity);

      const { data, error, count } = await query;
      if (error) {
        // A missing table means the database migration was never applied.
        // Say so plainly instead of hiding it behind a generic failure, so
        // the console can tell the operator exactly what to do.
        if (isMissingTableError(error)) {
          console.error("[Admin] safety_incidents table is missing:", error.message);
          res.status(503).json({
            error: "The safety incident log is not available on this server.",
            reason: "database_migration_missing",
            detail: "Table 'safety_incidents' does not exist. Apply supabase/migrations/0004_safety_incidents.sql to this Supabase project, then retry.",
          });
          return;
        }
        throw new Error(error.message);
      }

      // Attach the account email (auth.users) where we can, without a join the
      // Data API cannot express. Cached so a page of incidents costs one call
      // per distinct user.
      const rows = (data ?? []) as Array<Record<string, unknown>>;
      const emails = new Map<string, string | null>();
      await Promise.all(
        [...new Set(rows.map((row) => row.user_id).filter((id): id is string => typeof id === "string"))].map(
          async (id) => { emails.set(id, await loadTargetEmail(admin, id)); },
        ),
      );

      const incidents = rows.map((row) => ({
        ...row,
        user_email: typeof row.user_id === "string" ? emails.get(row.user_id) ?? null : null,
      }));

      res.json({ incidents, limit, offset, total: count ?? incidents.length });
    } catch (err) {
      console.error("[Admin] safety incidents error:", err);
      res.status(500).json({ error: "Could not load safety incidents." });
    }
  });

  // Dry-run the content-safety classifier without recording anything. Lets an
  // Owner/Admin verify detection works on a sample phrase instantly, without
  // needing a second account or a stored incident.
  app.post("/api/admin/safety-incidents/test", requireAdminOrOwner, async (req: AdminAuthedRequest, res: Response) => {
    try {
      const text = String((req.body as { text?: unknown } | undefined)?.text ?? "").trim();
      if (!text) return res.status(400).json({ error: "Text is required." });
      const finding = analyzeMessage(text);
      res.json({ finding });
    } catch (err) {
      console.error("[Admin] safety test error:", err);
      res.status(500).json({ error: "Could not run the safety classifier." });
    }
  });

  // Count safety incidents for the console badge (Admin + Owner)
  app.get("/api/admin/safety-incidents/count", requireAdminOrOwner, async (_req: AdminAuthedRequest, res: Response) => {
    try {
      const admin = requireAdminClient();
      const [open, total] = await Promise.all([
        admin.from("safety_incidents").select("id", { count: "exact", head: true }).eq("status", "open"),
        admin.from("safety_incidents").select("id", { count: "exact", head: true }),
      ]);
      // Check the ORIGINAL error objects: re-throwing as a plain Error would
      // discard the PostgREST code that identifies a missing table.
      if (isMissingTableError(open.error) || isMissingTableError(total.error)) {
        console.error("[Admin] safety_incidents table is missing.");
        res.status(503).json({
          error: "The safety incident log is not available on this server.",
          reason: "database_migration_missing",
          detail: "Table 'safety_incidents' does not exist. Apply supabase/migrations/0004_safety_incidents.sql to this Supabase project, then retry.",
        });
        return;
      }
      if (open.error) throw new Error(open.error.message);
      if (total.error) throw new Error(total.error.message);
      res.json({ open: open.count ?? 0, total: total.count ?? 0 });
    } catch (err) {
      console.error("[Admin] safety count error:", err);
      res.status(500).json({ error: "Could not load safety incident count." });
    }
  });

  // Update an incident's review status (Admin + Owner)
  app.post("/api/admin/safety-incidents/:id/status", requireAdminOrOwner, async (req: AdminAuthedRequest, res: Response) => {
    try {
      const incidentId = req.params.id;
      if (!/^[0-9a-f-]{36}$/i.test(incidentId)) {
        return res.status(400).json({ error: "Invalid incident id." });
      }
      const status = String((req.body as { status?: string } | undefined)?.status ?? "");
      if (!["open", "reviewed", "resolved"].includes(status)) {
        return res.status(400).json({ error: "Status must be open, reviewed or resolved." });
      }
      const notes = typeof (req.body as { notes?: unknown })?.notes === "string"
        ? String((req.body as { notes: string }).notes).slice(0, 2000)
        : null;

      const admin = requireAdminClient();
      const resolved = status === "resolved";
      const { data, error } = await admin
        .from("safety_incidents")
        .update({
          status,
          notes,
          resolved_at: resolved ? new Date().toISOString() : null,
          resolved_by: resolved ? req.userId! : null,
        })
        .eq("id", incidentId)
        .select("id, status")
        .maybeSingle();
      if (error) throw new Error(error.message);
      if (!data) return res.status(404).json({ error: "Incident not found." });

      try {
        await admin.rpc("log_admin_action", {
          p_actor_id: req.userId!,
          p_actor_email: req.userEmail,
          p_target_id: null,
          p_target_email: null,
          p_action: `SAFETY_${status.toUpperCase()}`,
          p_previous_role: null,
          p_new_role: null,
          p_metadata: { incident_id: incidentId },
        });
      } catch {
        /* auditing is best-effort here */
      }

      res.json({ ok: true, message: `Incident marked ${status}.` });
    } catch (err) {
      console.error("[Admin] safety status error:", err);
      res.status(500).json({ error: "Could not update the incident." });
    }
  });

  // ========================================================================
  // PLATFORM CONFIGURATION (Owner only)
  // ========================================================================

  // Get platform settings (Owner only)
  app.get("/api/admin/platform-config", requireOwner, async (req: AdminAuthedRequest, res: Response) => {
    try {
      const admin = requireAdminClient();

      // In a real system, this would query a platform_config table
      // For now, return environment-based config
      res.json({
        supabaseConfigured: true,
        composioConfigured: Boolean(process.env.COMPOSIO_API_KEY),
        // Mem0 replaced by local persistent memory
        localMemoryConfigured: true,
        geminiConfigured: Boolean(process.env.GEMINI_API_KEY),
        features: {
          cognition: process.env.EVA_ENABLE_COGNITION !== "false",
          initiative: process.env.EVA_ENABLE_INITIATIVE !== "false",
          proactiveSpeech: process.env.EVA_ENABLE_PROACTIVE_SPEECH !== "false",
          skillLearning: process.env.EVA_ENABLE_SKILL_LEARNING !== "false",
          reflection: process.env.EVA_ENABLE_REFLECTION !== "false",
          desktopAwareness: process.env.EVA_ENABLE_DESKTOP_AWARENESS !== "false",
          screenAwareness: process.env.EVA_ENABLE_SCREEN_AWARENESS === "true",
        },
        limits: {
          maxPlanDepth: Number(process.env.EVA_MAX_PLAN_DEPTH) || 8,
          maxRetries: Number(process.env.EVA_MAX_RETRIES) || 2,
          maxToolCalls: Number(process.env.EVA_MAX_TOOL_CALLS) || 24,
          taskTimeoutMs: Number(process.env.EVA_TASK_TIMEOUT_MS) || 300000,
        },
      });
    } catch (err) {
      console.error("[Admin] platform config error:", err);
      res.status(500).json({ error: "Could not load platform configuration." });
    }
  });

  // ========================================================================
  // DATA RETENTION (Owner only)
  // ========================================================================

  app.get("/api/admin/data-retention", requireOwner, async (req: AdminAuthedRequest, res: Response) => {
    try {
      // In a real system, this would query retention policies
      res.json({
        policies: [
          { table: "conversation_messages", retentionDays: 365, autoDelete: false },
          { table: "user_activity", retentionDays: 90, autoDelete: true },
          { table: "admin_audit_log", retentionDays: 2555, autoDelete: false }, // 7 years
        ],
        message: "Data retention configuration not yet implemented. Add a data_retention_policies table.",
      });
    } catch (err) {
      console.error("[Admin] data retention error:", err);
      res.status(500).json({ error: "Could not load data retention policies." });
    }
  });
}
