/**
 * JARVIS — authentication REST routes + authorization middleware.
 *
 * Registration, login, logout, password reset, session inspection and the
 * auth status probe. Every route that touches private data goes through
 * requireAuth, which resolves the user from a VERIFIED Supabase session —
 * never from a client-supplied id.
 */
import type { NextFunction, Request, Response } from "express";
import { supabase, supabaseConfigured, userClient } from "./supabaseClient";
import { initializeWorkspace } from "./workspace";
import { ensureOwnerRole } from "./ownerBootstrap";
import { randomBytes } from "node:crypto";

export interface AuthedRequest extends Request {
  userId?: string;
  userEmail?: string | null;
}

/** Error strings the frontend can show verbatim; never leak internals. */
export const AUTH_ERRORS = {
  notConfigured: "Sign-in is not available on this instance.",
  invalidCredentials: "Invalid email or password.",
  unverifiedEmail: "Please verify your email before signing in.",
  emailInUse: "An account with this email already exists.",
  weakPassword: "Password must be at least 8 characters.",
  missingFields: "Email and password are required.",
  sessionExpired: "Your session has expired. Please sign in again.",
  unauthorized: "You must be signed in to do that.",
  suspended: "This account has been suspended. Contact support.",
  emailNotSent: "Could not send that email right now. Please try again later.",
} as const;

/** Middleware: rejects requests without a verified Supabase session. */
export async function requireAuth(req: AuthedRequest, res: Response, next: NextFunction): Promise<void> {
  if (!supabaseConfigured) {
    res.status(503).json({ error: AUTH_ERRORS.notConfigured });
    return;
  }
  const header = req.headers["authorization"];
  const token = (Array.isArray(header) ? header[0] : header)?.replace(/^Bearer\s+/i, "").trim();

  if (!token) {
    res.status(401).json({ error: AUTH_ERRORS.unauthorized });
    return;
  }

  const { data, error } = await supabase.auth.getUser(token);
  if (error || !data.user) {
    res.status(401).json({ error: AUTH_ERRORS.sessionExpired });
    return;
  }

  // Suspended accounts are denied everywhere, on the authority of the verified
  // session's server-controlled app_metadata (set only by the backend via the
  // service role). app_metadata cannot be edited by the end user, unlike
  // user_metadata.
  if (data.user.app_metadata?.suspended === true) {
    res.status(403).json({ error: AUTH_ERRORS.suspended });
    return;
  }

  req.userId = data.user.id;
  req.userEmail = data.user.email ?? null;
  next();
}

/** Translate Supabase auth errors into safe, user-facing messages. */
function friendlyAuthError(message: string): string {
  const m = message.toLowerCase();
  if (m.includes("invalid login") || m.includes("invalid credentials")) return AUTH_ERRORS.invalidCredentials;
  if (m.includes("email not confirmed") || m.includes("not confirmed")) return AUTH_ERRORS.unverifiedEmail;
  if (m.includes("already registered") || m.includes("already in use") || m.includes("user already")) return AUTH_ERRORS.emailInUse;
  if (m.includes("password") && (m.includes("weak") || m.includes("short") || m.includes("at least"))) return AUTH_ERRORS.weakPassword;
  if (m.includes("rate limit")) return "Too many attempts. Please wait a moment and try again.";
  return "Sign-in failed. Please check your details and try again.";
}

export function registerAuthRoutes(app: import("express").Express): void {
  // --- status probe (public) -------------------------------------------
  app.get("/api/auth/status", (_req: Request, res: Response) => {
    res.json({ configured: supabaseConfigured });
  });

  if (!supabaseConfigured) return;

  // --- sign up ----------------------------------------------------------
  app.post("/api/auth/signup", async (req: Request, res: Response) => {
    const email = String(req.body?.email || "").trim().toLowerCase();
    const password = String(req.body?.password || "");

    if (!email || !password) {
      res.status(400).json({ error: AUTH_ERRORS.missingFields });
      return;
    }
    if (password.length < 8) {
      res.status(400).json({ error: AUTH_ERRORS.weakPassword });
      return;
    }

    // Supabase issues the session itself on signup when email confirmation is
    // off. When it is on, the session arrives only after the email callback.
    const { data, error } = await supabase.auth.signUp({ email, password });
    if (error) {
      res.status(400).json({ error: friendlyAuthError(error.message) });
      return;
    }

    const userId = data.user?.id;
    if (!userId) {
      // Confirmation required and no session yet — nothing to initialize yet;
      // the workspace is created on first verified sign-in.
      res.status(200).json({
        user: null,
        session: null,
        emailConfirmationRequired: true,
      });
      return;
    }

    const workspace = await initializeWorkspace(userId, data.session?.access_token).catch((err) => {
      console.error("[Auth] workspace init failed:", err);
      return null;
    });

    // Allowlisted Owner accounts get full rights automatically, no manual step.
    await ensureOwnerRole(userId, data.user!.email);

    res.status(201).json({
      user: { id: userId, email: data.user!.email },
      session: data.session
        ? { accessToken: data.session.access_token, refreshToken: data.session.refresh_token, expiresAt: data.session.expires_at }
        : null,
      emailConfirmationRequired: !data.session,
      workspace,
    });
  });

  // --- sign in ----------------------------------------------------------
  app.post("/api/auth/signin", async (req: Request, res: Response) => {
    const email = String(req.body?.email || "").trim().toLowerCase();
    const password = String(req.body?.password || "");

    if (!email || !password) {
      res.status(400).json({ error: AUTH_ERRORS.missingFields });
      return;
    }

    const { data, error } = await supabase.auth.signInWithPassword({ email, password });
    if (error || !data.user) {
      res.status(401).json({ error: friendlyAuthError(error?.message || "invalid credentials") });
      return;
    }

    // A returning user must never receive an empty replacement profile:
    // initialize is idempotent and leaves existing rows untouched.
    const workspace = await initializeWorkspace(data.user.id, data.session!.access_token).catch((err) => {
      console.error("[Auth] workspace re-init failed:", err);
      return null;
    });

    // Keep allowlisted Owner accounts on the OWNER role across sign-ins.
    await ensureOwnerRole(data.user.id, data.user.email);

    res.status(200).json({
      user: { id: data.user.id, email: data.user.email },
      session: {
        accessToken: data.session!.access_token,
        refreshToken: data.session!.refresh_token,
        expiresAt: data.session!.expires_at,
      },
      emailConfirmationRequired: false,
      workspace,
    });
  });

  // --- sign out ---------------------------------------------------------
  app.post("/api/auth/signout", async (req: Request, res: Response) => {
    const header = req.headers["authorization"];
    const token = (Array.isArray(header) ? header[0] : header)?.replace(/^Bearer\s+/i, "").trim();
    if (token) {
      // Best-effort: a server-side signOut needs the token; failure is fine
      // because the client discards its copy regardless.
      await supabase.auth.signOut(token).catch(() => {});
    }
    res.status(200).json({ ok: true });
  });

  // --- forgot password --------------------------------------------------
  app.post("/api/auth/forgot-password", async (req: Request, res: Response) => {
    const email = String(req.body?.email || "").trim().toLowerCase();
    if (!email) {
      res.status(400).json({ error: "Email is required." });
      return;
    }
    // Always respond positively so the endpoint cannot be used to enumerate.
    await supabase.auth.resetPasswordForEmail(email).catch(() => {});
    res.status(200).json({ ok: true });
  });

  // --- reset password (callback completes the flow) ---------------------
  app.post("/api/auth/reset-password", async (req: Request, res: Response) => {
    const password = String(req.body?.password || "");
    const accessToken = String(req.body?.accessToken || "");

    if (password.length < 8) {
      res.status(400).json({ error: AUTH_ERRORS.weakPassword });
      return;
    }
    if (!accessToken) {
      res.status(400).json({ error: "The reset link is missing or invalid. Please request a new one." });
      return;
    }

    // The user is authenticated by the recovery token Supabase issued, not by
    // anything the browser invented. Create a client scoped to that token so
    // the update applies to the recovery session's user.
    const { createClient } = await import("@supabase/supabase-js");
    const recoveryClient = createClient(
      process.env.SUPABASE_URL || "",
      process.env.SUPABASE_ANON_KEY || "",
      { auth: { persistSession: false, autoRefreshToken: false } },
    );
    const { data: userData, error: userError } = await recoveryClient.auth.getUser(accessToken);
    if (userError || !userData.user) {
      res.status(401).json({ error: "The reset link has expired. Please request a new one." });
      return;
    }

    const { error } = await recoveryClient.auth.updateUser({ password });
    if (error) {
      res.status(400).json({ error: friendlyAuthError(error.message) });
      return;
    }
    res.status(200).json({ ok: true });
  });

  // --- refresh an expired access token -----------------------------------
  //
  // The desktop app keeps its session on disk, so the access token eventually
  // expires. Without this route the app could only ask the user to sign in
  // again, which is what "it asks me to sign in every time I reopen it" meant.
  // The refresh token is exchanged server-side; a rejected or reused refresh
  // token yields 401 and the client falls back to the sign-in screen.
  app.post("/api/auth/refresh", async (req: Request, res: Response) => {
    const refreshToken = String(req.body?.refreshToken || "").trim();
    if (!refreshToken) {
      res.status(400).json({ error: AUTH_ERRORS.unauthorized });
      return;
    }

    const { data, error } = await supabase.auth.refreshSession({ refresh_token: refreshToken });
    if (error || !data.session?.access_token) {
      res.status(401).json({ error: AUTH_ERRORS.sessionExpired });
      return;
    }

    res.status(200).json({
      session: {
        accessToken: data.session.access_token,
        refreshToken: data.session.refresh_token,
        expiresAt: data.session.expires_at,
      },
    });
  });

  // --- verify a session the frontend already holds -----------------------
  app.get("/api/auth/me", requireAuth, async (req: AuthedRequest, res: Response) => {
    // Allowlisted Owner accounts are reconciled before the profile is read, so
    // the very first /me after login already reports the OWNER role.
    await ensureOwnerRole(req.userId!, req.userEmail);

    // Load the user's own profile so the client can personalize. Scope the
    // read to the caller's verified token so RLS resolves auth.uid().
    const header = req.headers["authorization"];
    const token = (Array.isArray(header) ? header[0] : header)!.replace(/^Bearer\s+/i, "").trim();
    const client = userClient(token);

    const { data: profile } = await client
      .from("profiles")
      .select("id, display_name, avatar_url, onboarding_completed, created_at, admin_role")
      .eq("id", req.userId)
      .maybeSingle();

    const { data: memorySettings } = await client
      .from("user_memory_settings")
      .select("memory_enabled")
      .eq("user_id", req.userId)
      .maybeSingle();

    res.status(200).json({
      user: { id: req.userId, email: req.userEmail },
      profile,
      memoryEnabled: memorySettings?.memory_enabled ?? true,
    });
  });

  // --- resend email verification ----------------------------------------
  app.post("/api/auth/resend-verification", async (req: Request, res: Response) => {
    const email = String(req.body?.email || "").trim().toLowerCase();
    if (!email) {
      res.status(400).json({ error: "Email is required." });
      return;
    }
    const { error } = await supabase.auth.resend({ type: "signup", email });
    if (error) {
      res.status(400).json({ error: friendlyAuthError(error.message) });
      return;
    }
    res.status(200).json({ ok: true });
  });

  // --- desktop handoff (browser-based login -> app code) ----------------
  //
  // The desktop app has no in-app login form. Instead it opens the system
  // browser to /desktop-login, the user signs in there, and the browser
  // requests a short one-time code. The user pastes that code into the app,
  // which exchanges it for the session. Codes are in-memory, single-use and
  // expire after 10 minutes — they never touch disk.
  const handoffCodes = new Map<string, {
    session: { accessToken: string; refreshToken: string; expiresAt: number };
    expiresAt: number;
  }>();
  const cleanHandoff = () => {
    const now = Date.now();
    for (const [code, value] of handoffCodes) {
      if (value.expiresAt < now) handoffCodes.delete(code);
    }
  };

  // The browser, already signed in, sends its session and receives a code.
  // Only the access token is trusted after Supabase verifies it; the refresh
  // token is stored solely to hand back to the same-machine desktop app.
  app.post("/api/auth/desktop/handoff", async (req: Request, res: Response) => {
    const accessToken = String(req.body?.accessToken || "").trim();
    const refreshToken = String(req.body?.refreshToken || "").trim();
    const expiresAt = Number(req.body?.expiresAt) || 0;

    if (!accessToken || !refreshToken) {
      res.status(400).json({ error: AUTH_ERRORS.unauthorized });
      return;
    }

    const { data, error } = await supabase.auth.getUser(accessToken);
    if (error || !data.user) {
      res.status(401).json({ error: AUTH_ERRORS.sessionExpired });
      return;
    }

    cleanHandoff();
    // 6-digit numeric code (easy to read, type, and say aloud).
    let code = String(Math.floor(100000 + Math.random() * 900000));
    while (handoffCodes.has(code)) code = String(Math.floor(100000 + Math.random() * 900000));
    const expiresAtMs = Date.now() + 10 * 60 * 1000;
    handoffCodes.set(code, {
      session: { accessToken, refreshToken, expiresAt },
      expiresAt: expiresAtMs,
    });
    res.json({ code, expiresAt: Math.floor(expiresAtMs / 1000) });
  });

  // The desktop app exchanges the pasted code for the session. Single-use.
  app.post("/api/auth/desktop/exchange", async (req: Request, res: Response) => {
    const code = String(req.body?.code || "").toUpperCase().trim();
    if (!code) {
      res.status(400).json({ error: "Enter the code shown in your browser." });
      return;
    }
    cleanHandoff();
    const entry = handoffCodes.get(code);
    if (!entry || entry.expiresAt < Date.now()) {
      handoffCodes.delete(code);
      res.status(400).json({ error: "That code is invalid or has expired. Please sign in again." });
      return;
    }
    // Consume it immediately: a code can only be used once.
    handoffCodes.delete(code);
    res.json({ session: entry.session });
  });
}
