/**
 * Managed Gemini key pool.
 *
 * The Free plan is served by platform-supplied keys, so more than one can be
 * configured (comma separated). A key that is denied, out of quota or simply
 * overloaded must not take the whole Free tier offline, so the pool moves to
 * the next key when a request fails for a key-level reason.
 *
 * A Pro user who supplies their own key is never affected: their key is
 * resolved before the pool is consulted.
 */
import { getManagedGeminiApiKeys } from "../../server_paths";

/** Errors that mean "this key cannot serve the request right now". */
const KEY_LEVEL_FAILURE =
  /\b(403|429)\b|quota|rate.?limit|resource[_ ]exhausted|denied|unauthenticated|permission|too many requests|overloaded|capacity/i;

export class GeminiKeyPool {
  private keys: string[] = [];
  private index = 0;
  /** How many consecutive failures each key has accumulated. */
  private readonly failures = new Map<string, number>();

  /** Re-read the configured keys. Safe to call at any time. */
  refresh(keys?: string[]): void {
    const next = (keys ?? getManagedGeminiApiKeys()).filter(Boolean);
    const changed = next.join(",") !== this.keys.join(",");
    this.keys = next;
    if (changed) {
      this.index = 0;
      this.failures.clear();
    }
  }

  get size(): number {
    return this.keys.length;
  }

  /** The key that should be used for the next request. */
  get current(): string | undefined {
    if (!this.keys.length) this.refresh();
    if (!this.keys.length) return undefined;
    return this.keys[this.index % this.keys.length];
  }

  /**
   * Move to the next key. Returns the new current key, or undefined when the
   * pool is empty.
   */
  rotate(): string | undefined {
    if (this.keys.length < 2) return this.current;
    this.index = (this.index + 1) % this.keys.length;
    return this.current;
  }

  /**
   * Report a failed request. Returns true when the failure was a key-level
   * problem and the pool was rotated.
   */
  reportFailure(error: unknown): boolean {
    const message = error instanceof Error ? error.message : String(error ?? "");
    const status = Number((error as { status?: number; code?: number })?.status ?? 0);
    const keyLevel = KEY_LEVEL_FAILURE.test(message) || status === 403 || status === 429;
    if (!keyLevel) return false;

    const key = this.current;
    if (key) this.failures.set(key, (this.failures.get(key) ?? 0) + 1);
    this.rotate();
    return true;
  }

  /**
   * Drop the keys that cannot serve a request at all.
   *
   * A key whose project was denied access is dead for good, and the Free plan
   * must not spend a user's request on it. Probing once at startup keeps the
   * pool honest without a health check on every call.
   */
  async pruneUnusableKeys(model = "gemini-3.5-flash"): Promise<string[]> {
    if (!this.keys.length) this.refresh();
    const alive: string[] = [];
    const dropped: string[] = [];
    for (const key of this.keys) {
      try {
        const res = await fetch(
          `https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(model)}:generateContent`,
          {
            method: "POST",
            headers: { "Content-Type": "application/json", "X-goog-api-key": key },
            body: JSON.stringify({
              contents: [{ parts: [{ text: "ok" }],
              }],
              generationConfig: { maxOutputTokens: 4 },
            }),
          },
        );
        if (res.ok) alive.push(key);
        else dropped.push(key);
      } catch {
        // A network hiccup is not proof the key is dead — keep it.
        alive.push(key);
      }
    }
    if (dropped.length) {
      this.keys = alive;
      this.index = 0;
      this.failures.clear();
    }
    return dropped;
  }
}

let pool: GeminiKeyPool | null = null;

/** The process-wide managed key pool. */
export function managedGeminiPool(): GeminiKeyPool {
  if (!pool) pool = new GeminiKeyPool();
  return pool;
}

/**
 * Called by the provider when a request fails. Rotates the pool when the
 * failure is key-level so the next request is served by a different key.
 */
export function reportGeminiKeyFailure(error: unknown): boolean {
  return managedGeminiPool().reportFailure(error);
}
