/**
 * Core Logs — feature backend module.
 *
 * Registered through the Feature Registry's explicit contract: this module
 * exports `register(app, ctx)` which contributes a tool handler (for the
 * `readSystemLogs` tool declared in the manifest). No dynamic requires, no
 * shell execution — just the registry's safe hooks.
 */
import fs from "node:fs";
import path from "node:path";
import type { FeatureContext } from "../registry";

const MAX_DEFAULT = 200;

export async function register(_app: unknown, ctx: FeatureContext): Promise<{ unregister: () => void }> {
  // Executable handler for the declarative `readSystemLogs` tool.
  ctx.registerToolHandler("readSystemLogs", async (args) => {
    const limit = clamp(Number(args.limit) || MAX_DEFAULT, 1, 1000);
    const raw = args.level === "all" || args.level === undefined ? undefined : String(args.level);
    const result = recentLogs(limit, raw);
    // `in` narrowing (this project compiles without strictNullChecks, where
    // truthiness narrowing on a boolean discriminant does not apply).
    if ("error" in result) return { ok: false, error: result.error };
    return { ok: true, result: { entries: result.entries } };
  });

  return {
    unregister: () => {
      /* handlers and tools are cleaned up by the registry */
    },
  };
}

export function health(): boolean {
  return true;
}

// ---- log reading (local, read-only, best-effort) ---------------------------

interface LogEntry {
  ts?: string;
  level?: string;
  component?: string;
  message?: string;
  raw?: string;
}

function recentLogs(limit: number, level?: string): { ok: true; entries: LogEntry[] } | { ok: false; error: string } {
  const dataDir = process.env.EVA_DATA_DIR || "";
  const candidates = [
    dataDir && path.join(dataDir, "logs", "eva.jsonl"),
    path.join(process.cwd(), "logs", "eva.jsonl"),
  ].filter(Boolean) as string[];

  for (const file of candidates) {
    if (!fs.existsSync(file)) continue;
    try {
      const text = fs.readFileSync(file, "utf-8");
      const lines = text.split("\n").filter(Boolean).slice(-limit * 2);
      const entries: LogEntry[] = [];
      for (const line of lines) {
        try {
          const parsed = JSON.parse(line) as LogEntry;
          if (level && parsed.level && parsed.level !== level) continue;
          entries.push({ ts: parsed.ts, level: parsed.level, component: parsed.component, message: parsed.message });
        } catch {
          entries.push({ raw: line.slice(0, 300) });
        }
      }
      return { ok: true, entries: entries.slice(-limit) };
    } catch {
      /* try the next candidate */
    }
  }
  return { ok: false, error: "No JARVIS log file is available on this instance yet." };
}

function clamp(value: number, min: number, max: number): number {
  return Math.max(min, Math.min(max, Number.isFinite(value) ? Math.round(value) : max));
}
