/**
 * JARVIS — platform Owner bootstrap.
 *
 * Guarantees that the platform's designated Owner accounts automatically hold
 * the OWNER role, on every verified sign-in / sign-up / session probe, without
 * any manual step. The database applies the same rule through a trigger on
 * auth.users (see migration 0002/0003), so the guarantee holds on every path —
 * this module is the application-layer belt for that database-layer suspenders.
 *
 * Security:
 *  - Only the service-role client ever writes a role; the frontend has no way
 *    to reach this code path or to grant itself a role.
 *  - The allowlist is server-side only (env EVA_OWNER_EMAILS, with the
 *    platform's permanent Owner addresses as the default). It is BOOTSTRAP
 *    CONFIGURATION, not a role system: administrative roles still live solely
 *    in profiles.admin_role and are limited to OWNER / ADMIN.
 *  - Failures never break sign-in: role bootstrapping is logged and skipped.
 */
import { getAdmin } from "./supabaseClient";

/** The platform's permanent Owners. Override with EVA_OWNER_EMAILS (comma-separated). */
export const DEFAULT_PLATFORM_OWNER_EMAILS = [
  "iffatabdulsattar68@gmail.com",
  "iffatabdulsattar1010@gmail.com",
] as const;

export function platformOwnerEmails(): Set<string> {
  const raw = process.env.EVA_OWNER_EMAILS?.trim();
  const list = raw
    ? raw.split(",").map((e) => e.trim().toLowerCase()).filter(Boolean)
    : [...DEFAULT_PLATFORM_OWNER_EMAILS];
  return new Set(list);
}

/**
 * Ensure a verified user whose email is on the Owner allowlist carries the
 * OWNER role. Idempotent; a no-op for everyone else. Never throws.
 */
export async function ensureOwnerRole(userId: string, email: string | null | undefined): Promise<void> {
  if (!userId || !email) return;
  if (!platformOwnerEmails().has(email.toLowerCase())) return;

  try {
    const admin = await getAdmin();
    if (!admin) return; // no service role: the database trigger still covers this

    const { data: profile, error: readError } = await admin
      .from("profiles")
      .select("admin_role")
      .eq("id", userId)
      .maybeSingle();

    if (readError) {
      console.error("[OwnerBootstrap] could not read profile role:", readError.message);
      return;
    }

    if (profile?.admin_role === "OWNER") return; // already correct

    const previousRole = profile?.admin_role ?? null;
    const { error: writeError } = await admin
      .from("profiles")
      .upsert({ id: userId, admin_role: "OWNER" }, { onConflict: "id" });

    if (writeError) {
      console.error("[OwnerBootstrap] could not grant OWNER:", writeError.message);
      return;
    }

    // Audit the bootstrap grant (best effort; constrained to known actions).
    const { error: auditError } = await admin.rpc("log_admin_action", {
      p_actor_id: userId,
      p_actor_email: email.toLowerCase(),
      p_target_id: userId,
      p_target_email: email.toLowerCase(),
      p_action: "PROMOTE_OWNER",
      p_previous_role: previousRole,
      p_new_role: "OWNER",
      p_metadata: { bootstrap: true, source: "owner_allowlist" },
    });
    if (auditError) {
      console.warn("[OwnerBootstrap] audit write skipped:", auditError.message);
    }

    console.log(`[OwnerBootstrap] granted OWNER to allowlisted account ${email}`);
  } catch (err) {
    console.error("[OwnerBootstrap] unexpected error:", err);
  }
}

/**
 * Walk the Owner allowlist and reconcile every registered account against it.
 * Called at server start and after role-sensitive operations; cheap at the
 * scale this platform runs at and fully idempotent.
 */
export async function syncPlatformOwners(): Promise<void> {
  try {
    const admin = await getAdmin();
    if (!admin) return;

    const { data, error } = await admin.rpc("get_all_users_with_roles");
    if (error || !Array.isArray(data)) {
      if (error) console.error("[OwnerBootstrap] sync listing failed:", error.message);
      return;
    }

    const owners = platformOwnerEmails();
    for (const row of data as Array<{ id: string; email: string | null; admin_role: string | null }>) {
      if (!row.email || !owners.has(row.email.toLowerCase())) continue;
      if (row.admin_role !== "OWNER") {
        await ensureOwnerRole(row.id, row.email);
      }
    }
  } catch (err) {
    console.error("[OwnerBootstrap] sync error:", err);
  }
}
