/**
 * Per-device session bookkeeping on the PC gateway side.
 *
 * Tracks, for each paired device that has opened a relay connection since the
 * gateway started:
 *
 *   - last accepted sequence — envelopes with `seq <= lastSeq` are replays
 *     and are dropped (a reconnect starts fresh because the phone mints a
 *     new session, so `hello` resets the window);
 *   - a fixed 60s rate window keyed by device id;
 *   - a set of seen message ids within the current window, so a retransmitted
 *     envelope (same id) is a no-op even if its seq looks fresh.
 *
 * This lives next to the dispatcher, not in the device store: it is purely
 * in-memory connection state and intentionally lost on restart.
 */

export interface DeviceSession {
  deviceId: string;
  userId: string;
  lastSeq: number;
  windowStart: number;
  windowCount: number;
  seenIds: Set<string>;
  connectedAt: number;
}

export class SessionTracker {
  private readonly sessions = new Map<string, DeviceSession>();

  constructor(private readonly ratePerMinute: number) {}

  open(deviceId: string, userId: string): DeviceSession {
    const existing = this.sessions.get(deviceId);
    if (existing) {
      // A new connection (re)opens the rate window but keeps seq monotonic
      // within the process lifetime of the gateway.
      existing.windowStart = Date.now();
      existing.windowCount = 0;
      existing.userId = userId;
      return existing;
    }
    const session: DeviceSession = {
      deviceId,
      userId,
      lastSeq: 0,
      windowStart: Date.now(),
      windowCount: 0,
      seenIds: new Set(),
      connectedAt: Date.now(),
    };
    this.sessions.set(deviceId, session);
    return session;
  }

  close(deviceId: string): void {
    this.sessions.delete(deviceId);
  }

  get(deviceId: string): DeviceSession | null {
    return this.sessions.get(deviceId) || null;
  }

  /**
   * Admission check for one inbound envelope. Returns:
   *   "ok"        — accept and dispatch;
   *   "replay"    — duplicate id or stale sequence; silently ignore;
   *   "rate"      — over the per-device rate limit; reply relay.error.
   *
   * A device with no tracked session is admitted at most once to bootstrap:
   * the gateway opens the real session after the device row is verified.
   *
   * `allowResync` is for `hello` only: a phone that reloads its page restarts
   * its per-sender sequence at 1, so a stale `lastSeq` from before the reload
   * would classify every envelope as a replay — including the `hello` that
   * exists precisely to reset the baseline. With `allowResync`, hello is
   * accepted (duplicate *ids* are still rejected) and becomes the new
   * baseline. Without this, a reloaded phone is silently mute until its
   * counter climbs past the stale value.
   */
  admit(deviceId: string, envelopeId: string, seq: number, options: { allowResync?: boolean } = {}): "ok" | "replay" | "rate" {
    let session = this.sessions.get(deviceId);
    if (!session) {
      session = this.open(deviceId, "");
    }

    const now = Date.now();
    if (now - session.windowStart >= 60_000) {
      session.windowStart = now;
      session.windowCount = 0;
      session.seenIds.clear();
    }
    session.windowCount += 1;
    if (session.windowCount > this.ratePerMinute) return "rate";

    if (session.seenIds.has(envelopeId)) return "replay";
    session.seenIds.add(envelopeId);
    // Bound the id set: within a window it cannot exceed the rate limit by
    // much, but a safety cap keeps a pathological peer from growing it.
    if (session.seenIds.size > this.ratePerMinute * 2) session.seenIds.clear();

    if (seq <= session.lastSeq) {
      if (!options.allowResync) return "replay";
      session.lastSeq = seq;
      return "ok";
    }
    session.lastSeq = seq;
    return "ok";
  }

  /** Force the seq baseline (used by hello after a phone reconnect). */
  resetSeq(deviceId: string, seq: number): void {
    const session = this.sessions.get(deviceId);
    if (session) session.lastSeq = seq;
  }
}
