/**
 * Device pairing flow.
 *
 *   1. start  - on the PC (local, authenticated): creates a `link_sent`
 *      device row, mints a 10-minute one-time pair token and EMAILS a deep
 *      link to the signed-in account address. If SMTP is not configured the
 *      link is returned for on-screen display (never silently dropped).
 *   2. claim  - on the phone (must be signed in as the SAME user): the pair
 *      token is verified, the row moves to `pending`, and the phone receives
 *      a pending-scope access token so it can wait for approval even if the
 *      emailed link expires.
 *   3. approve - on the PC ONLY (local loopback REST): moves the row to
 *      `active` and notifies the waiting phone with full credentials.
 *
 * A pairing link is never a bearer credential on its own: claiming it still
 * requires an authenticated session of the same user, and activation still
 * requires a human clicking Allow on the PC.
 */
import { randomBytes } from "node:crypto";
import type { Transporter } from "nodemailer";
import type { RemoteConfig } from "./config";
import type { DeviceStore, RemoteDevice } from "./devices";
import { mintAccess, mintPair, mintRefresh, verifyToken } from "./tokens";

export interface PairingStartResult {
  device: RemoteDevice;
  link: string;
  emailSent: boolean;
  manualCode: string | null;
  expiresAt: string;
}

export interface PairingClaimResult {
  device: RemoteDevice;
  pendingAccess: string;
}

export interface IssuedCredentials {
  access: string;
  refresh: string;
  accessTokenExpiresAt: string;
}

const PAIR_PATH = "/remote/pair";

function baseFromRelay(relayUrl: string): string {
  return relayUrl.replace(/^wss:/i, "https:").replace(/^ws:/i, "http:");
}

export function pairingLinkBase(cfg: RemoteConfig): string {
  const override = (process.env.EVA_PAIR_LINK_URL || "").trim().replace(/\/+$/, "");
  if (override) return override;
  if (cfg.relayUrl) return baseFromRelay(cfg.relayUrl);
  return cfg.appUrl;
}

let transporterPromise: Promise<Transporter | null> | null = null;

async function getTransporter(cfg: RemoteConfig): Promise<Transporter | null> {
  if (!cfg.smtpUrl) return null;
  if (!transporterPromise) {
    transporterPromise = import("nodemailer")
      .then((nodemailer) => nodemailer.createTransport(cfg.smtpUrl) as Transporter)
      .catch((error) => {
        console.warn("[Remote] nodemailer unavailable; pairing falls back to on-screen links:", error);
        return null;
      });
  }
  return transporterPromise;
}

async function sendPairingEmail(cfg: RemoteConfig, to: string, link: string, deviceLabel: string): Promise<boolean> {
  const transport = await getTransporter(cfg);
  if (!transport) return false;
  try {
    await transport.sendMail({
      from: cfg.smtpFrom,
      to,
      subject: "Pair a device with EVA-JARVIS",
      text: [
        `A device (${deviceLabel}) is requesting remote access to your EVA-JARVIS PC.`,
        "",
        "Open this link on that device WHILE SIGNED IN to your EVA account:",
        link,
        "",
        "The link expires in 10 minutes. You must still approve the device on your PC.",
        "If you did not request this, ignore this email - nothing is paired without your approval on the computer.",
      ].join("\n"),
      html: [
        '<div style="font-family:system-ui,sans-serif;max-width:480px;margin:auto">',
        '<h2 style="margin-bottom:8px">Pair a device</h2>',
        `<p><b>${escapeHtml(deviceLabel)}</b> is requesting remote access to your EVA-JARVIS PC.</p>`,
        `<p><a href="${escapeHtml(link)}" style="display:inline-block;padding:12px 20px;background:#111;color:#fff;border-radius:8px;text-decoration:none">Open pairing page</a></p>`,
        '<p style="color:#666;font-size:13px">The link expires in 10 minutes. You must still approve the device on your PC.',
        "If you did not request this, ignore this email - nothing is paired without your approval on the computer.</p>",
        "</div>",
      ].join("\n"),
    });
    return true;
  } catch (error) {
    console.warn("[Remote] pairing email failed:", error instanceof Error ? error.message : error);
    return false;
  }
}

function escapeHtml(value: string): string {
  return value.replace(/[&<>"']/g, (char) => (
    { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[char] || char
  ));
}

export function resetPairingForTests(): void {
  transporterPromise = null;
}

export type PairingEventType = "pairing.started" | "pairing.claimed" | "pairing.approved" | "pairing.revoked";

export class PairingService {
  constructor(
    private readonly cfg: RemoteConfig,
    private readonly store: DeviceStore,
    private readonly onPairingEvent: (event: { type: PairingEventType; device: RemoteDevice }) => void = () => {},
  ) {}

  async start(userId: string, userEmail: string | null, deviceLabel = "New device"): Promise<PairingStartResult> {
    const nonce = randomBytes(9).toString("base64url");
    const device = await this.store.create({
      userId,
      name: deviceLabel,
      status: "link_sent",
      pairNonce: nonce,
    });
    const token = mintPair(this.cfg, userId, device.id, nonce);
    const link = `${pairingLinkBase(this.cfg)}${PAIR_PATH}?token=${encodeURIComponent(token)}`;

    const emailSent = userEmail ? await sendPairingEmail(this.cfg, userEmail, link, deviceLabel) : false;

    this.onPairingEvent({ type: "pairing.started", device });
    const expiresAt = new Date(Date.now() + 10 * 60 * 1000).toISOString();
    return {
      device,
      link,
      emailSent,
      manualCode: emailSent ? null : link,
      expiresAt,
    };
  }

  /**
   * Claim a pairing token from a signed-in phone. Idempotent while the device
   * is still pending, so a dropped connection during the wait can reconnect.
   */
  async claim(userId: string, pairToken: string, deviceName: string, platform: string | null): Promise<PairingClaimResult | null> {
    const claims = verifyToken(this.cfg, pairToken, "pair");
    if (!claims || claims.uid !== userId) return null;

    const device = await this.store.get(claims.did);
    if (!device || device.userId !== userId) return null;
    if (device.status === "revoked") return null;
    if (device.status === "link_sent" && device.pairNonce !== claims.jti) return null;

    if (device.status === "link_sent") {
      await this.store.update(device.id, {
        status: "pending",
        name: sanitizeName(deviceName) || device.name,
        platform: platform ? platform.slice(0, 120) : null,
      });
    } else if (device.status === "pending") {
      await this.store.update(device.id, {
        name: sanitizeName(deviceName) || device.name,
        platform: platform ? platform.slice(0, 120) : device.platform,
      });
    } else {
      return null;
    }

    const updated = (await this.store.get(device.id))!;
    this.onPairingEvent({ type: "pairing.claimed", device: updated });
    return {
      device: updated,
      pendingAccess: mintAccess(this.cfg, userId, updated.id),
    };
  }

  /**
   * Approve a pending device. LOCAL ONLY - the route must be mounted behind
   * both requireAuth and the loopback host guard (see remote/index.ts).
   */
  async approve(userId: string, deviceId: string): Promise<RemoteDevice | null> {
    const device = await this.store.get(deviceId);
    if (!device || device.userId !== userId || device.status !== "pending") return null;
    const updated = await this.store.update(deviceId, {
      status: "active",
      approvedAt: new Date().toISOString(),
    });
    if (updated) this.onPairingEvent({ type: "pairing.approved", device: updated });
    return updated;
  }

  async deny(userId: string, deviceId: string): Promise<RemoteDevice | null> {
    const device = await this.store.get(deviceId);
    if (!device || device.userId !== userId) return null;
    if (device.status !== "pending" && device.status !== "link_sent") return null;
    const updated = await this.store.update(deviceId, {
      status: "revoked",
      revokedAt: new Date().toISOString(),
    });
    if (updated) this.onPairingEvent({ type: "pairing.revoked", device: updated });
    return updated;
  }

  async revoke(userId: string, deviceId: string): Promise<RemoteDevice | null> {
    const device = await this.store.get(deviceId);
    if (!device || device.userId !== userId || device.status === "revoked") return null;
    const updated = await this.store.update(deviceId, {
      status: "revoked",
      revokedAt: new Date().toISOString(),
    });
    if (updated) this.onPairingEvent({ type: "pairing.revoked", device: updated });
    return updated;
  }

  issueCredentials(userId: string, deviceId: string): IssuedCredentials {
    const access = mintAccess(this.cfg, userId, deviceId);
    const refresh = mintRefresh(this.cfg, userId, deviceId);
    return {
      access,
      refresh,
      accessTokenExpiresAt: new Date(Date.now() + accessTtlMs()).toISOString(),
    };
  }
}

function accessTtlMs(): number {
  const parsed = Number(process.env.EVA_REMOTE_ACCESS_TTL_SEC);
  const secs = Number.isFinite(parsed) && parsed > 0 ? parsed : 30 * 60;
  return secs * 1000;
}

function sanitizeName(name: string): string {
  return String(name || "")
    .replace(/[\u0000-\u001f\u007f-\u009f]/g, "")
    .trim()
    .slice(0, 120);
}