import { providerSettings } from "../config";
import { providerFetch } from "../http";
import type { IntegrationProvider, ProviderHealth } from "../types";

export class ComposioProvider implements IntegrationProvider {
  id="composio"; name="Composio";
  async health():Promise<ProviderHealth>{
    return {id:this.id,name:this.name,status:providerSettings.COMPOSIO_API_KEY ? "configured":"unconfigured"};
  }
  async execute(input:unknown,signal?:AbortSignal):Promise<unknown>{
    if(!providerSettings.COMPOSIO_API_KEY) throw new Error("Composio is not configured.");
    const request=typeof input==="object"&&input!==null?input as Record<string,unknown>:{};
    const path=typeof request.path==="string"?request.path:"/api/v3.1/tools";
    const method=String(request.method||"GET").toUpperCase();
    const response=await providerFetch(`${providerSettings.COMPOSIO_BASE_URL}${path}`,{
      method,headers:{"x-api-key":providerSettings.COMPOSIO_API_KEY,"Content-Type":"application/json"},
      body:method==="GET"?undefined:JSON.stringify(request.body??{}),signal
    },providerSettings.PROVIDER_TIMEOUT_MS);
    if(!response.ok) throw new Error(`Composio request failed (${response.status}).`);
    return response.json();
  }
}
