/**
 * JARVIS — Feature Registry (backend).
 *
 * Owns the full feature lifecycle: discovery, validation, persistence,
 * activation, health, rollback and the mapping of a feature's declarative
 * contract onto the running application (tool registration, optional route
 * hooks, health probes). Frontend integration is handled by a matching
 * renderer-side registry fed from the same manifest through `/api/features`.
 *
 * Safety properties:
 *  - Only manifests under the project's own `features/` directory are accepted
 *    (source === "bundled"). There is no arbitrary file → feature mapping.
 *  - Manifests are strictly validated before anything is activated.
 *  - Duplicate ids, malformed manifests, missing required dependencies and
 *    unsupported app versions are rejected.
 *  - Production activation passes through `awaiting_approval` unless the owner
 *    has enabled trusted auto-activation.
 *  - Activation is atomic over the registry: if any step throws, everything the
 *    activation registered (tools, routes) is removed and the previous working
 *    registry is restored.
 *  - Tools and routes are registered through explicit contracts — never dynamic
 *    `require` of untrusted strings, never arbitrary shell commands.
 */
import path from "node:path";
import fs from "node:fs";
import type { Express, Request, Response, NextFunction } from "express";
import {
  FEATURE_LIFECYCLE_STATES,
  compareSemver,
  isSafeModuleId,
  normalizeManifest,
  satisfiesSemver,
  validateManifest,
  type FeatureDependency,
  type FeatureLifecycleState,
  type FeatureManifest,
  type FeatureToolDecl,
  type FeatureValidationResult,
  type RawFeatureManifest,
} from "../shared/featureTypes";
import { readJsonFile, writeJsonFile } from "../shared/jsonFile";
import { createLogger } from "../shared/logger";

const log = createLogger("feature-registry");

/** Tool registry contract: we only need register + unregister + list. */
export interface ToolRegistryLike {
  register(descriptor: { name: string; purpose: string; permission: string; riskLevel: number; timeoutMs: number; maxRetries: number }): void;
  unregister(name: string): boolean;
  list(): Array<{ name: string }>;
}

/** Route auth guard a feature may request. Applied by the registry. */
export type RouteAuth = "owner" | "admin_or_owner" | "user" | "public";

export interface FeatureRouteDef {
  method: "get" | "post" | "patch" | "delete" | "put";
  path: string;
  handler: (req: Request, res: Response, next?: NextFunction) => unknown;
  auth?: RouteAuth;
  description?: string;
}

/** Result shape of a feature tool handler (mirrors callDesktopAgent/callApiHubTool). */
export interface FeatureToolResult {
  ok: boolean;
  result?: unknown;
  error?: string;
}
export type FeatureToolHandler = (args: Record<string, unknown>, signal: AbortSignal) => Promise<FeatureToolResult>;

/** Context handed to a feature module's register(app, ctx). */
export interface FeatureContext {
  feature: FeatureManifest;
  dataDir: string;
  app: Express;
  /** Register a route that the registry tracks and removes on disable/rollback. */
  registerRoute(def: FeatureRouteDef): void;
  /**
   * Register the executable handler for one of the feature's *declared* tools.
   * The name must appear in the manifest's tools[] — this is what turns a
   * declarative tool into a real, callable capability without exposing
   * arbitrary functions to the agent.
   */
  registerToolHandler(name: string, fn: FeatureToolHandler): void;
  log: { info: (m: string, d?: unknown) => void; warn: (m: string, d?: unknown) => void; error: (m: string, d?: unknown) => void };
}

/** Per-module lifecycle contract exported by feature backend modules. */
export interface FeatureModuleLifecycle {
  register(app: Express, context: FeatureContext): Promise<unknown> | unknown;
  unregister?(): Promise<unknown> | unknown;
  health?(): Promise<boolean> | boolean;
}

export interface FeatureRecord {
  manifest: FeatureManifest;
  state: FeatureLifecycleState;
  lastError?: string | null;
  lastUpdatedAt: string;
  activatedAt?: string | null;
  buildStatus?: "pending" | "passed" | "failed";
  testStatus?: "pending" | "passed" | "failed";
  dependencyHealth: Record<string, boolean | string>;
  pendingMigrations: string[];
  active: boolean;
  _teardown?: (() => Promise<void> | void) | null;
}

export interface FeatureSnapshot {
  manifest: FeatureManifest;
  state: FeatureLifecycleState;
  lastError: string | null;
  lastUpdatedAt: string;
  activatedAt: string | null;
  buildStatus: FeatureRecord["buildStatus"];
  testStatus: FeatureRecord["testStatus"];
  dependencyHealth: FeatureRecord["dependencyHealth"];
  pendingMigrations: string[];
  active: boolean;
}

export interface FeatureRegistryOptions {
  dataDir: string;
  appVersion: string;
  featuresDir: string;
  /** Production mode requires owner approval for new activation. */
  production: boolean;
  /** Env-gated trusted auto-activation (dev only by convention). */
  autoActivate?: boolean;
  /** Resolve a feature backend module id to its lifecycle object. */
  loadModule?: (moduleId: string) => FeatureModuleLifecycle | null;
  /** Tool registry to register declared tools into. */
  tools?: ToolRegistryLike;
  /** Express app (optional; route hooks need it). */
  app?: Express;
  /** Apply an owner-authorized auth guard to a route. Defaults to requireUser. */
  guard?: (auth: RouteAuth) => (req: Request, res: Response, next: NextFunction) => void;
  /** Called after any lifecycle transition (used to fan out feature.status events). */
  onStatusChange?: (snapshot: FeatureSnapshot, reason: string) => void;
}

const PERSISTENCE_FILE = "features.registry.json";

export class FeatureRegistry {
  private readonly records = new Map<string, FeatureRecord>();
  private readonly file: string;
  private readonly featuresDir: string;
  private readonly options: FeatureRegistryOptions;
  private readonly routeCleanups = new Map<string, Array<() => void>>();
  /** feature id -> tool name -> handler, only for declared manifest tools. */
  private readonly toolHandlers = new Map<string, Map<string, FeatureToolHandler>>();
  private initialized = false;

  constructor(options: FeatureRegistryOptions) {
    this.options = options;
    this.featuresDir = options.featuresDir;
    this.file = path.join(options.dataDir, PERSISTENCE_FILE);
  }

  // ---- discovery ------------------------------------------------------------

  async discover(): Promise<string[]> {
    await fs.promises.mkdir(this.featuresDir, { recursive: true });
    let entries: fs.Dirent[];
    try {
      entries = await fs.promises.readdir(this.featuresDir, { withFileTypes: true });
    } catch {
      return [];
    }
    return entries
      .filter((e) => e.isDirectory())
      .map((e) => e.name)
      .filter(isSafeModuleId);
  }

  private manifestPathFor(id: string): string {
    return path.join(this.featuresDir, id, "manifest.json");
  }

  // ---- initialization -------------------------------------------------------

  async initialize(): Promise<void> {
    if (this.initialized) return;
    this.initialized = true;

    const persisted = await readJsonFile<Record<string, unknown>>(this.file, {});
    const persistedByKey = new Map<string, FeatureRecord>();
    for (const [id, value] of Object.entries(persisted)) {
      const rec = value as Partial<FeatureRecord>;
      if (rec && typeof rec === "object" && typeof rec.manifest === "object") {
        persistedByKey.set(id, rec as unknown as FeatureRecord);
      }
    }

    const ids = await this.discover();
    const seen = new Set<string>();
    for (const id of ids) {
      if (seen.has(id)) {
        log.warn(`duplicate feature id on disk: ${id}`);
        continue;
      }
      seen.add(id);
      const raw = await readJsonFile<RawFeatureManifest | null>(this.manifestPathFor(id), null);
      if (!raw || raw.id !== id) {
        this.records.set(id, this.recordForFailure(id, `Manifest missing or id mismatch for ${id}.`));
        continue;
      }
      const result = validateManifest(raw);
      if (!result.valid) {
        this.records.set(id, this.recordForFailure(id, result.errors.join("; ")));
        continue;
      }
      const manifest = normalizeManifest(raw);
      const previous = persistedByKey.get(id);
      const wasActive = previous?.active === true;
      this.records.set(id, {
        manifest,
        state: wasActive ? "ready" : "discovered",
        lastError: null,
        lastUpdatedAt: new Date().toISOString(),
        activatedAt: previous?.activatedAt ?? null,
        buildStatus: previous?.buildStatus ?? "pending",
        testStatus: previous?.testStatus ?? "pending",
        dependencyHealth: {},
        pendingMigrations: manifest.databaseMigrations?.map((m) => m.file) ?? [],
        active: false,
      });
    }

    for (const id of persistedByKey.keys()) {
      if (!seen.has(id)) this.records.delete(id);
    }

    for (const rec of this.records.values()) this.evaluateDependencies(rec);

    // Re-activate features that were active before a restart (owner-approved
    // previously). Idempotent and safe: still runs all validation.
    for (const rec of this.records.values()) {
      if (persistedByKey.get(rec.manifest.id)?.active === true && rec.state === "ready") {
        await this.activate(rec.manifest.id, { internal: true });
      }
    }

    await this.persist();
  }

  private recordForFailure(id: string, error: string): FeatureRecord {
    const manifest = { id, name: id, version: "0.0.0", description: "", status: "failed" as const, backendModules: [], source: "bundled" as const };
    return {
      manifest: manifest as FeatureManifest,
      state: "failed",
      lastError: error,
      lastUpdatedAt: new Date().toISOString(),
      activatedAt: null,
      buildStatus: "failed",
      testStatus: "failed",
      dependencyHealth: {},
      pendingMigrations: [],
      active: false,
    };
  }

  // ---- persistence ----------------------------------------------------------

  private async persist(): Promise<void> {
    const out: Record<string, unknown> = {};
    for (const [id, rec] of this.records) {
      out[id] = {
        manifest: rec.manifest,
        state: rec.state,
        lastError: rec.lastError,
        lastUpdatedAt: rec.lastUpdatedAt,
        activatedAt: rec.activatedAt,
        buildStatus: rec.buildStatus,
        testStatus: rec.testStatus,
        dependencyHealth: rec.dependencyHealth,
        pendingMigrations: rec.pendingMigrations,
        active: rec.active,
      };
    }
    await writeJsonFile(this.file, out);
  }

  // ---- public accessors -----------------------------------------------------

  list(): FeatureSnapshot[] {
    return [...this.records.values()]
      .map((r) => this.snapshot(r))
      .sort((a, b) => a.manifest.id.localeCompare(b.manifest.id));
  }

  get(id: string): FeatureSnapshot | null {
    const rec = this.records.get(id);
    return rec ? this.snapshot(rec) : null;
  }

  private snapshot(rec: FeatureRecord): FeatureSnapshot {
    return {
      manifest: rec.manifest,
      state: rec.state,
      lastError: rec.lastError,
      lastUpdatedAt: rec.lastUpdatedAt,
      activatedAt: rec.activatedAt,
      buildStatus: rec.buildStatus,
      testStatus: rec.testStatus,
      dependencyHealth: rec.dependencyHealth,
      pendingMigrations: rec.pendingMigrations,
      active: rec.active,
    };
  }

  isActive(id: string): boolean {
    return this.records.get(id)?.active === true;
  }

  activeFrontend(): FeatureManifest[] {
    return [...this.records.values()]
      .filter((r) => r.active && (r.manifest.frontendEntry || r.manifest.navigation))
      .map((r) => r.manifest);
  }

  // ---- dependency evaluation --------------------------------------------------

  private evaluateDependencies(rec: FeatureRecord): void {
    const health: Record<string, boolean | string> = {};
    for (const dep of rec.manifest.dependencies ?? []) {
      const target = this.records.get(dep.id);
      if (!target) {
        health[dep.id] = `missing feature '${dep.id}'`;
        continue;
      }
      if (!target.active && dep.required !== false) {
        health[dep.id] = `dependency '${dep.id}' is not active`;
        continue;
      }
      if (dep.version && !satisfiesSemver(target.manifest.version, dep.version)) {
        health[dep.id] = `dependency '${dep.id}' version ${target.manifest.version} does not satisfy ${dep.version}`;
        continue;
      }
      health[dep.id] = true;
    }
    rec.dependencyHealth = health;
  }

  private dependenciesSatisfied(rec: FeatureRecord): boolean {
    return Object.values(rec.dependencyHealth).every((v) => v === true);
  }

  private missingDependencyReport(rec: FeatureRecord): string {
    return Object.entries(rec.dependencyHealth)
      .filter(([, v]) => v !== true)
      .map(([k, v]) => `${k}: ${v}`)
      .join("; ");
  }

  // ---- lifecycle ------------------------------------------------------------

  async activate(id: string, opts: { internal?: boolean } = {}): Promise<FeatureSnapshot> {
    const rec = this.records.get(id);
    if (!rec) throw new Error(`Feature '${id}' is not registered.`);
    if (rec.active) return this.snapshot(rec);

    this.setState(rec, "activating");
    const registeredTools: string[] = [];

    try {
      const validation = validateManifest(rec.manifest as unknown as RawFeatureManifest);
      if (!validation.valid) throw new Error(`Manifest invalid: ${validation.errors.join("; ")}`);

      if (rec.manifest.minimumAppVersion) {
        const cmp = compareSemver(this.options.appVersion, rec.manifest.minimumAppVersion);
        if (cmp !== null && cmp < 0) {
          throw new Error(`Requires app >= ${rec.manifest.minimumAppVersion} (running ${this.options.appVersion}).`);
        }
      }

      if (rec.manifest.activationRequirements?.length) {
        throw new Error(`Activation requirements not met: ${rec.manifest.activationRequirements.join("; ")}.`);
      }

      this.evaluateDependencies(rec);
      if (!this.dependenciesSatisfied(rec)) {
        throw new Error(`Missing dependency: ${this.missingDependencyReport(rec)}.`);
      }

      if (!opts.internal && this.options.production && !this.ownerAutoActivateEnabled()) {
        this.setState(rec, "awaiting_approval");
        this.notify(rec, "awaiting_approval");
        throw new Error("Production activation requires owner approval.");
      }

      // Register declared tools (explicit contract; safe ids only).
      if (this.options.tools && rec.manifest.tools?.length) {
        for (const tool of rec.manifest.tools) {
          const duplicate = this.options.tools.list().some((t) => t.name === tool.name);
          if (duplicate) throw new Error(`Tool '${tool.name}' is already registered by another component.`);
          this.options.tools.register(toolDescriptor(tool));
          registeredTools.push(tool.name);
        }
      }

      // Load the feature's backend module(s) and register them.
      let teardown: FeatureRecord["_teardown"] = null;
      if (rec.manifest.backendModules.length) {
        for (const moduleId of rec.manifest.backendModules) {
          const mod = this.options.loadModule?.(moduleId);
          if (!mod || typeof mod.register !== "function") {
            throw new Error(`Backend module '${moduleId}' is not available or has no register().`);
          }
          const result = await mod.register(this.options.app as Express, this.contextFor(rec));
          if (result && typeof (result as { unregister?: () => unknown }).unregister === "function") {
            const prior = teardown;
            const thisModule = (result as { unregister: () => unknown }).unregister;
            teardown = async () => {
              await prior?.();
              await thisModule();
            };
          }
        }
      }

      // Health check must pass before publishing active state.
      await this.assertHealthy(rec);

      // Commit atomically.
      rec._teardown = teardown;
      rec.active = true;
      rec.activatedAt = rec.activatedAt ?? new Date().toISOString();
      rec.state = "active";
      rec.lastError = null;
      rec.lastUpdatedAt = new Date().toISOString();
      rec.buildStatus = rec.buildStatus === "failed" ? "passed" : rec.buildStatus || "passed";
      rec.testStatus = rec.testStatus === "failed" ? "passed" : rec.testStatus || "passed";
      rec.pendingMigrations = [];
      await this.persist();
      log.info(`feature activated: ${id} v${rec.manifest.version}`);
      this.notify(rec, "activated");
      return this.snapshot(rec);
    } catch (error) {
      // The approval gate is not a failure: nothing has been registered yet, so
      // the record must stay in awaiting_approval for the owner to approve later.
      if (rec.state === "awaiting_approval") {
        rec.lastUpdatedAt = new Date().toISOString();
        await this.persist();
        throw error;
      }
      // Remove anything the failed activation registered.
      for (const name of registeredTools) this.options.tools?.unregister(name);
      this.clearRoutes(id);
      this.toolHandlers.delete(id);
      await this.rollback(id, error instanceof Error ? error.message : String(error));
      throw error;
    }
  }

  private setState(rec: FeatureRecord, state: FeatureLifecycleState): void {
    rec.state = state;
    rec.lastUpdatedAt = new Date().toISOString();
  }

  private notify(rec: FeatureRecord, reason: string): void {
    try {
      this.options.onStatusChange?.(this.snapshot(rec), reason);
    } catch {
      /* a broken subscriber must not break the registry */
    }
  }

  private contextFor(rec: FeatureRecord): FeatureContext {
    const feature = rec.manifest;
    const app = this.options.app as Express;
    const self = this;
    const declaredTools = new Set((feature.tools ?? []).map((t) => t.name));
    return {
      feature,
      dataDir: this.options.dataDir,
      app,
      registerRoute(def: FeatureRouteDef) {
        self.mountRoute(feature.id, def);
      },
      registerToolHandler(name: string, fn: FeatureToolHandler) {
        if (!declaredTools.has(name)) {
          throw new Error(`Tool handler '${name}' is not declared in the feature's tools[] manifest.`);
        }
        if (!self.toolHandlers.has(feature.id)) self.toolHandlers.set(feature.id, new Map());
        self.toolHandlers.get(feature.id)!.set(name, fn);
      },
      log: {
        info: (m, d) => log.info(`[${feature.id}] ${m}`, d),
        warn: (m, d) => log.warn(`[${feature.id}] ${m}`, d),
        error: (m, d) => log.error(`[${feature.id}] ${m}`, d),
      },
    };
  }

  /** Resolve an executable handler for a feature tool, if one was registered. */
  getToolHandler(name: string): FeatureToolHandler | undefined {
    for (const handlers of this.toolHandlers.values()) {
      const fn = handlers.get(name);
      if (fn) return fn;
    }
    return undefined;
  }

  /** Mount a route onto Express, tracking it so it can be removed later. */
  private mountRoute(featureId: string, def: FeatureRouteDef): void {
    if (!this.options.app) return;
    const app = this.options.app;
    const guard = this.options.guard?.(def.auth ?? "user");
    const handler = guard ? [guard, def.handler] : def.handler;
    const router = (app as unknown as { _router?: { stack: Array<{ handle?: unknown }> } })._router;
    const before = router?.stack?.length ?? 0;
    app[def.method](def.path, handler as never);
    const stack = (app as unknown as { _router?: { stack: unknown[] } })._router?.stack;
    const added = Array.isArray(stack) ? stack.slice(before) : [];
    this.trackRoute(featureId, () => {
      const s = (app as unknown as { _router?: { stack: unknown[] } })._router?.stack;
      if (!Array.isArray(s)) return;
      for (const layer of added) {
        const i = s.indexOf(layer);
        if (i >= 0) s.splice(i, 1);
      }
    });
    log.debug(`feature route mounted: ${def.method.toUpperCase()} ${def.path} (${featureId})`);
  }

  private trackRoute(featureId: string, cleanup: () => void): void {
    if (!this.routeCleanups.has(featureId)) this.routeCleanups.set(featureId, []);
    this.routeCleanups.get(featureId)!.push(cleanup);
  }

  private clearRoutes(featureId: string): void {
    for (const cleanup of this.routeCleanups.get(featureId) ?? []) {
      try { cleanup(); } catch { /* best-effort */ }
    }
    this.routeCleanups.delete(featureId);
  }

  /** Disable an active feature (keeps data; removes registrations). */
  async disable(id: string): Promise<FeatureSnapshot> {
    const rec = this.records.get(id);
    if (!rec) throw new Error(`Feature '${id}' is not registered.`);
    if (rec.active) {
      this.setState(rec, "rolling_back");
      try {
        if (this.options.tools && rec.manifest.tools?.length) {
          for (const tool of rec.manifest.tools) this.options.tools.unregister(tool.name);
        }
        this.clearRoutes(id);
        await rec._teardown?.();
        rec._teardown = null;
        this.toolHandlers.delete(id);
      } finally {
        rec.active = false;
        rec.state = "disabled";
        rec.activatedAt = null;
        rec.lastUpdatedAt = new Date().toISOString();
        await this.persist();
        this.notify(rec, "disabled");
      }
    } else {
      rec.state = "disabled";
      rec.lastUpdatedAt = new Date().toISOString();
      await this.persist();
      this.notify(rec, "disabled");
    }
    log.info(`feature disabled: ${id}`);
    return this.snapshot(rec);
  }

  private async rollback(id: string, error: string): Promise<void> {
    const rec = this.records.get(id);
    if (!rec) return;
    if (this.options.tools && rec.manifest.tools?.length) {
      for (const tool of rec.manifest.tools) this.options.tools.unregister(tool.name);
    }
    this.clearRoutes(id);
    await Promise.resolve(rec._teardown?.()).catch(() => {});
    rec._teardown = null;
    this.toolHandlers.delete(id);
    rec.active = false;
    rec.state = "failed";
    rec.lastError = error;
    rec.lastUpdatedAt = new Date().toISOString();
    await this.persist();
    log.error(`feature activation failed: ${id} — ${error}`);
    this.notify(rec, "failed");
  }

  async recordBuild(id: string, status: "passed" | "failed", detail?: string): Promise<FeatureSnapshot> {
    const rec = this.records.get(id);
    if (!rec) throw new Error(`Feature '${id}' is not registered.`);
    rec.buildStatus = status;
    if (status === "failed") { rec.state = "failed"; rec.lastError = detail ?? "Build failed."; }
    rec.lastUpdatedAt = new Date().toISOString();
    await this.persist();
    return this.snapshot(rec);
  }

  async recordTests(id: string, status: "passed" | "failed", detail?: string): Promise<FeatureSnapshot> {
    const rec = this.records.get(id);
    if (!rec) throw new Error(`Feature '${id}' is not registered.`);
    rec.testStatus = status;
    if (status === "failed") { rec.state = "failed"; rec.lastError = detail ?? "Tests failed."; }
    rec.lastUpdatedAt = new Date().toISOString();
    await this.persist();
    return this.snapshot(rec);
  }

  /** Fold a newly added/updated manifest on disk into the registry. */
  async refresh(id: string): Promise<FeatureSnapshot> {
    const previous = this.records.get(id);
    const wasActive = previous?.active === true;
    const previousVersion = previous?.manifest.version;
    // Tear the current registrations down first so a refresh never leaves
    // orphaned tools/routes behind a record that now says "inactive".
    if (wasActive) await this.disable(id);

    const raw = await readJsonFile<RawFeatureManifest | null>(this.manifestPathFor(id), null);
    if (!raw || raw.id !== id) {
      this.records.set(id, this.recordForFailure(id, `Manifest missing or id mismatch for ${id}.`));
      await this.persist();
      return this.snapshot(this.records.get(id)!);
    }
    const result = validateManifest(raw);
    if (!result.valid) {
      this.records.set(id, this.recordForFailure(id, result.errors.join("; ")));
      await this.persist();
      return this.snapshot(this.records.get(id)!);
    }
    const manifest = normalizeManifest(raw);
    this.records.set(id, {
      manifest,
      state: wasActive ? "ready" : "discovered",
      lastError: null,
      lastUpdatedAt: new Date().toISOString(),
      activatedAt: null,
      buildStatus: previous?.buildStatus ?? "pending",
      testStatus: previous?.testStatus ?? "pending",
      dependencyHealth: {},
      pendingMigrations: manifest.databaseMigrations?.map((m) => m.file) ?? [],
      active: false,
    });
    this.evaluateDependencies(this.records.get(id)!);
    await this.persist();

    // Same version that was already owner-approved: re-activate immediately so
    // a dev edit or a repaired manifest comes back up. A *version change* is a
    // new release: it stays ready until an owner activates (approves) it.
    if (wasActive && previousVersion === manifest.version && this.records.get(id)!.state !== "failed") {
      return this.activate(id, { internal: true });
    }
    return this.snapshot(this.records.get(id)!);
  }

  static validate(raw: RawFeatureManifest): FeatureValidationResult {
    return validateManifest(raw);
  }

  static validateSet(manifests: FeatureManifest[]): FeatureValidationResult {
    const errors: string[] = [];
    const seen = new Map<string, string>();
    for (const m of manifests) {
      if (seen.has(m.id) && seen.get(m.id) !== m.version) {
        errors.push(`Duplicate feature id '${m.id}' with conflicting versions ${seen.get(m.id)} vs ${m.version}.`);
      }
      seen.set(m.id, m.version);
    }
    return { valid: errors.length === 0, errors };
  }

  async checkHealth(id: string): Promise<boolean> {
    const rec = this.records.get(id);
    if (!rec) return false;
    return this.checkHealthRec(rec);
  }

  private async checkHealthRec(rec: FeatureRecord): Promise<boolean> {
    if (rec.manifest.healthCheck) {
      const mod = rec.manifest.backendModules[0] ? this.options.loadModule?.(rec.manifest.backendModules[0]) : undefined;
      if (mod && typeof mod.health === "function") {
        try {
          const ok = await mod.health();
          return ok !== false;
        } catch {
          return false;
        }
      }
    }
    return true;
  }

  private async assertHealthy(rec: FeatureRecord): Promise<void> {
    const ok = await this.checkHealthRec(rec);
    if (!ok) throw new Error(`Health check failed for '${rec.manifest.id}'.`);
  }

  private ownerAutoActivateEnabled(): boolean {
    return this.options.autoActivate === true;
  }

  get lifecycleStates(): readonly FeatureLifecycleState[] {
    return FEATURE_LIFECYCLE_STATES;
  }
}

function toolDescriptor(tool: FeatureToolDecl) {
  return {
    name: tool.name,
    purpose: tool.purpose,
    permission: tool.permission ?? "desktop_control",
    riskLevel: tool.riskLevel ?? 1,
    timeoutMs: tool.timeoutMs ?? 25_000,
    maxRetries: tool.maxRetries ?? 0,
  };
}

export { compareSemver, satisfiesSemver };
