/**
 * Remote device registry.
 *
 * Authoritative record of which controller devices (phones/browsers) may
 * reach this PC. Two backends behind one interface:
 *
 *   - SupabaseDeviceStore — table `remote_devices` (migration 0005) when
 *     Supabase is configured; survives PC reinstalls, visible to account UIs.
 *   - JsonDeviceStore — durable local JSON under `<dataDir>/remote/` used
 *     when Supabase is absent (dev/tests) so pairing still works, and as the
 *     natural fallback for a single-machine install.
 *
 * The gateway consults this store on EVERY remote session open and on every
 * privileged envelope: a cryptographically valid token whose row is not
 * 'active' is refused, so revocation takes effect immediately.
 */
import fs from "node:fs";
import fsp from "node:fs/promises";
import path from "node:path";
import { randomUUID } from "node:crypto";
import { supabaseConfigured, requireAdmin } from "../auth/supabaseClient";

/** Service-role client, or null when the service key is not configured. */
function adminOrNull(): ReturnType<typeof requireAdmin> | null {
  try {
    return requireAdmin();
  } catch {
    return null;
  }
}

export type DeviceStatus = "link_sent" | "pending" | "active" | "revoked";

export interface RemoteDevice {
  id: string;
  userId: string;
  name: string;
  platform: string | null;
  status: DeviceStatus;
  /** jti of the one-time pairing token minted for this row. */
  pairNonce: string | null;
  approvedAt: string | null;
  revokedAt: string | null;
  lastSeenAt: string | null;
  createdAt: string;
  updatedAt: string;
}

export interface DeviceStore {
  readonly backend: "supabase" | "json";
  initialize(): Promise<void>;
  create(input: { userId: string; name: string; platform?: string | null; status: DeviceStatus; pairNonce: string }): Promise<RemoteDevice>;
  get(id: string): Promise<RemoteDevice | null>;
  getByPairNonce(nonce: string): Promise<RemoteDevice | null>;
  listForUser(userId: string): Promise<RemoteDevice[]>;
  /** Uids reachable on the relay: anyone with a device row that is not revoked (link_sent included so claims can land). */
  ownerIds(): Promise<string[]>;
  update(id: string, patch: Partial<Pick<RemoteDevice, "name" | "platform" | "status" | "pairNonce" | "approvedAt" | "revokedAt" | "lastSeenAt">>): Promise<RemoteDevice | null>;
}

const nowIso = () => new Date().toISOString();
const toStatus = (value: unknown): DeviceStatus =>
  value === "pending" || value === "active" || value === "revoked" ? value : "link_sent";

// ---------------------------------------------------------------------------
// Local JSON backend
// ---------------------------------------------------------------------------

interface JsonFile {
  devices: RemoteDevice[];
}

export class JsonDeviceStore implements DeviceStore {
  readonly backend = "json" as const;
  private readonly file: string;
  private devices = new Map<string, RemoteDevice>();
  private writeQueue: Promise<void> = Promise.resolve();

  constructor(dataDir: string) {
    this.file = path.join(dataDir, "remote", "devices.json");
  }

  async initialize(): Promise<void> {
    try {
      const raw = await fsp.readFile(this.file, "utf-8");
      const parsed = JSON.parse(raw) as JsonFile;
      for (const device of parsed.devices || []) {
        if (device && typeof device.id === "string" && typeof device.userId === "string") {
          this.devices.set(device.id, { ...device, status: toStatus(device.status) });
        }
      }
    } catch {
      /* no store yet */
    }
  }

  private persist(): void {
    this.writeQueue = this.writeQueue.then(async () => {
      try {
        await fsp.mkdir(path.dirname(this.file), { recursive: true });
        const tmp = `${this.file}.tmp`;
        await fsp.writeFile(tmp, JSON.stringify({ devices: [...this.devices.values()] }, null, 2), "utf-8");
        await fsp.rename(tmp, this.file);
      } catch {
        /* best effort: next write retries */
      }
    });
  }

  async create(input: { userId: string; name: string; platform?: string | null; status: DeviceStatus; pairNonce: string }): Promise<RemoteDevice> {
    const device: RemoteDevice = {
      id: randomUUID(),
      userId: input.userId,
      name: input.name.slice(0, 120) || "Unnamed device",
      platform: input.platform ?? null,
      status: input.status,
      pairNonce: input.pairNonce,
      approvedAt: null,
      revokedAt: null,
      lastSeenAt: null,
      createdAt: nowIso(),
      updatedAt: nowIso(),
    };
    this.devices.set(device.id, device);
    this.persist();
    return device;
  }

  async get(id: string): Promise<RemoteDevice | null> {
    return this.devices.get(id) || null;
  }

  async getByPairNonce(nonce: string): Promise<RemoteDevice | null> {
    for (const device of this.devices.values()) if (device.pairNonce === nonce) return device;
    return null;
  }

  async listForUser(userId: string): Promise<RemoteDevice[]> {
    return [...this.devices.values()]
      .filter((device) => device.userId === userId)
      .sort((a, b) => b.createdAt.localeCompare(a.createdAt));
  }

  async ownerIds(): Promise<string[]> {
    return [...new Set([...this.devices.values()]
      .filter((device) => device.status !== "revoked")
      .map((device) => device.userId))];
  }

  async update(id: string, patch: Partial<RemoteDevice>): Promise<RemoteDevice | null> {
    const device = this.devices.get(id);
    if (!device) return null;
    Object.assign(device, patch, { updatedAt: nowIso() });
    this.persist();
    return device;
  }
}

// ---------------------------------------------------------------------------
// Supabase backend
// ---------------------------------------------------------------------------

function rowToDevice(row: Record<string, unknown>): RemoteDevice {
  return {
    id: String(row.id),
    userId: String(row.user_id),
    name: String(row.name || "Unnamed device"),
    platform: row.platform === null || row.platform === undefined ? null : String(row.platform),
    status: toStatus(row.status),
    pairNonce: row.pair_nonce === null || row.pair_nonce === undefined ? null : String(row.pair_nonce),
    approvedAt: (row.approved_at as string) || null,
    revokedAt: (row.revoked_at as string) || null,
    lastSeenAt: (row.last_seen_at as string) || null,
    createdAt: String(row.created_at || nowIso()),
    updatedAt: String(row.updated_at || nowIso()),
  };
}

export class SupabaseDeviceStore implements DeviceStore {
  readonly backend = "supabase" as const;
  private migrationsHinted = false;

  async initialize(): Promise<void> {
    const admin = adminOrNull();
    if (!admin) throw new Error("Supabase service role is unavailable for the remote device store.");
    const { error } = await admin.from("remote_devices").select("id").limit(1);
    if (error && !this.migrationsHinted) {
      this.migrationsHinted = true;
      throw new Error(
        `Remote device table is not available (${error.message}). Run supabase/migrations/0005_remote_devices.sql first.`,
      );
    }
  }

  private requireAdmin() {
    const admin = adminOrNull();
    if (!admin) throw new Error("Supabase service role is unavailable for the remote device store.");
    return admin;
  }

  async create(input: { userId: string; name: string; platform?: string | null; status: DeviceStatus; pairNonce: string }): Promise<RemoteDevice> {
    const row = {
      user_id: input.userId,
      name: input.name.slice(0, 120) || "Unnamed device",
      platform: input.platform ?? null,
      status: input.status,
      pair_nonce: input.pairNonce,
    };
    const { data, error } = await this.requireAdmin().from("remote_devices").insert(row).select("*").single();
    if (error) throw new Error(`Device create failed: ${error.message}`);
    return rowToDevice(data);
  }

  async get(id: string): Promise<RemoteDevice | null> {
    const { data, error } = await this.requireAdmin().from("remote_devices").select("*").eq("id", id).maybeSingle();
    if (error) throw new Error(`Device read failed: ${error.message}`);
    return data ? rowToDevice(data) : null;
  }

  async getByPairNonce(nonce: string): Promise<RemoteDevice | null> {
    const { data, error } = await this.requireAdmin()
      .from("remote_devices").select("*").eq("pair_nonce", nonce).limit(1);
    if (error) throw new Error(`Device read failed: ${error.message}`);
    return data?.[0] ? rowToDevice(data[0]) : null;
  }

  async listForUser(userId: string): Promise<RemoteDevice[]> {
    const { data, error } = await this.requireAdmin()
      .from("remote_devices").select("*").eq("user_id", userId).order("created_at", { ascending: false });
    if (error) throw new Error(`Device list failed: ${error.message}`);
    return (data || []).map(rowToDevice);
  }

  async ownerIds(): Promise<string[]> {
    const { data, error } = await this.requireAdmin()
      .from("remote_devices").select("user_id").neq("status", "revoked");
    if (error) throw new Error(`Device owners failed: ${error.message}`);
    return [...new Set((data || []).map((row) => String(row.user_id)))];
  }

  async update(id: string, patch: Partial<RemoteDevice>): Promise<RemoteDevice | null> {
    const row: Record<string, unknown> = {};
    if (patch.name !== undefined) row.name = patch.name;
    if (patch.platform !== undefined) row.platform = patch.platform;
    if (patch.status !== undefined) row.status = patch.status;
    if (patch.pairNonce !== undefined) row.pair_nonce = patch.pairNonce;
    if (patch.approvedAt !== undefined) row.approved_at = patch.approvedAt;
    if (patch.revokedAt !== undefined) row.revoked_at = patch.revokedAt;
    if (patch.lastSeenAt !== undefined) row.last_seen_at = patch.lastSeenAt;
    if (Object.keys(row).length === 0) return this.get(id);
    const { data, error } = await this.requireAdmin().from("remote_devices").update(row).eq("id", id).select("*").maybeSingle();
    if (error) throw new Error(`Device update failed: ${error.message}`);
    return data ? rowToDevice(data) : null;
  }
}

/** True when Supabase reports the remote_devices table has not been migrated. */
function isTableMissing(error: unknown): boolean {
  const message = error instanceof Error ? error.message : String(error);
  return /could not find the table|relation .* does not exist|pgrst205/i.test(message);
}

/**
 * Use Supabase when it is configured AND migrated; otherwise silently fall back
 * to the local JSON store so pairing still works. The backend once degraded
 * stays on JSON for the process lifetime (no per-call probing).
 *
 * Reads are UNIONED with the local JSON store: devices paired before Supabase
 * was migrated (still sitting in `<dataDir>/remote/devices.json`) would
 * otherwise become invisible the moment Supabase takes over — the PC would
 * bind no relay rooms and every phone would see `host_offline`. The primary
 * (Supabase) stays authoritative whenever it actually has a row.
 */
export class FallbackDeviceStore implements DeviceStore {
  readonly backend = "supabase" as const;
  private readonly primary: DeviceStore;
  private readonly secondary: JsonDeviceStore;
  private degraded = false;

  constructor(dataDir: string, primary: DeviceStore = new SupabaseDeviceStore()) {
    this.primary = primary;
    this.secondary = new JsonDeviceStore(dataDir);
  }

  private degrade(error: unknown): boolean {
    if (!this.degraded && isTableMissing(error)) {
      this.degraded = true;
      return true;
    }
    return this.degraded;
  }

  async initialize(): Promise<void> {
    // Always load the local mirror: it holds pairings made before the
    // Supabase migration, and it is the only backend when degraded.
    await this.secondary.initialize();
    if (this.degraded) return;
    try {
      await this.primary.initialize();
    } catch (error) {
      if (!this.degrade(error)) throw error;
    }
  }

  async create(input: Parameters<DeviceStore["create"]>[0]): Promise<RemoteDevice> {
    if (this.degraded) return this.secondary.create(input);
    try {
      return await this.primary.create(input);
    } catch (error) {
      if (!this.degrade(error)) throw error;
      return this.secondary.create(input);
    }
  }

  async get(id: string): Promise<RemoteDevice | null> {
    if (this.degraded) return this.secondary.get(id);
    try {
      const remote = await this.primary.get(id);
      if (remote) return remote;
    } catch (error) {
      if (!this.degrade(error)) throw error;
    }
    return this.secondary.get(id);
  }

  async getByPairNonce(nonce: string): Promise<RemoteDevice | null> {
    if (this.degraded) return this.secondary.getByPairNonce(nonce);
    try {
      const remote = await this.primary.getByPairNonce(nonce);
      if (remote) return remote;
    } catch (error) {
      if (!this.degrade(error)) throw error;
    }
    return this.secondary.getByPairNonce(nonce);
  }

  async listForUser(userId: string): Promise<RemoteDevice[]> {
    const local = await this.secondary.listForUser(userId);
    if (this.degraded) return local;
    try {
      const remote = await this.primary.listForUser(userId);
      const byId = new Map<string, RemoteDevice>();
      for (const device of local) byId.set(device.id, device);
      for (const device of remote) byId.set(device.id, device); // Supabase wins
      return [...byId.values()].sort((a, b) => b.createdAt.localeCompare(a.createdAt));
    } catch (error) {
      if (!this.degrade(error)) throw error;
      return local;
    }
  }

  async ownerIds(): Promise<string[]> {
    const ids = new Set(await this.secondary.ownerIds());
    if (this.degraded) return [...ids];
    try {
      for (const id of await this.primary.ownerIds()) ids.add(id);
    } catch (error) {
      if (!this.degrade(error)) throw error;
    }
    return [...ids];
  }

  async update(id: string, patch: Partial<RemoteDevice>): Promise<RemoteDevice | null> {
    if (this.degraded) return this.secondary.update(id, patch);
    try {
      const remote = await this.primary.update(id, patch);
      if (remote) return remote;
    } catch (error) {
      if (!this.degrade(error)) throw error;
      return this.secondary.update(id, patch);
    }
    return this.secondary.update(id, patch);
  }
}

/** Pick the backend: Supabase when configured, otherwise local JSON. */
export function createDeviceStore(dataDir: string): DeviceStore {
  if (supabaseConfigured && adminOrNull()) return new FallbackDeviceStore(dataDir);
  return new JsonDeviceStore(dataDir);
}

/** Read the JSON store directly (tests / diagnostics only). */
export function readJsonDevices(dataDir: string): RemoteDevice[] {
  try {
    const raw = fs.readFileSync(path.join(dataDir, "remote", "devices.json"), "utf-8");
    return (JSON.parse(raw) as JsonFile).devices || [];
  } catch {
    return [];
  }
}
