/**
 * Multitasking Engine â€” parallel task execution with DAG scheduling.
 *
 * Reuses the existing TaskManager (agent/loop.ts) for planning-intensive work
 * and TaskStore for persistence. Runs independent tasks concurrently with
 * bounded parallelism, respects dependencies, and publishes live events via
 * appEvents for the WebSocket fan-out.
 */
import { randomUUID } from "node:crypto";
import { readJsonFile, writeJsonFile, DebouncedJsonWriter } from "../shared/jsonFile";
import path from "node:path";
import { appEvents } from "../shared/appEvents";
import { createLogger } from "../shared/logger";
import { publicTaskView, TaskStore, TERMINAL_STATES, type TaskSession } from "./taskSession";
import { TaskManager } from "./loop";
import { rootScope, type CancellationScope } from "./cancellation";
import type { ModelRouter } from "../models/router";
import type { ActionExecutor } from "./actions/executor";
import type { AuditLog } from "./audit";
import type { ConfirmationBroker } from "../permissions/confirmations";
import type { PermissionEngine } from "../permissions/engine";
import type { ContactBook } from "../memory/contacts";
import type { WorkingMemory } from "../memory/workingMemory";
import type { ResourceScheduler } from "./scheduler";

const log = createLogger("multi-engine");

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface MultitaskPlan {
  id: string;
  requestId: string;
  createdAt: string;
  tasks: MultitaskTask[];
  total: number;
  parallelizable: number;
}

export interface MultitaskTask {
  id: string;
  title: string;
  description: string;
  dependsOn: string[];
  priority: number;
  maxRetries: number;
  timeoutMs: number;
  agentCapability: string | null;
  state: MultitaskTaskState;
  progress: number;
  progressMessage: string;
  result: string | null;
  error: string | null;
  createdAt: string;
  startedAt: string | null;
  completedAt: string | null;
  retryCount: number;
  sessionId: string | null;
  requiresApproval: boolean;
  approvalId: string | null;
}

export type MultitaskTaskState =
  | "pending"
  | "queued"
  | "running"
  | "waiting_for_dependency"
  | "waiting_for_approval"
  | "waiting_for_external_service"
  | "paused"
  | "retrying"
  | "recovering"
  | "completed"
  | "failed"
  | "timed_out"
  | "cancelled";

export interface MultitaskRequest {
  id: string;
  description: string;
  tasks: MultitaskTaskSpec[];
  maxConcurrency: number;
  createdAt: string;
  createdBy: "voice" | "text" | "api";
}

export interface MultitaskTaskSpec {
  title: string;
  description: string;
  dependsOn: string[];
  priority?: number;
  maxRetries?: number;
  timeoutMs?: number;
  agentCapability?: string;
  sensitive?: boolean;
}

export interface MultitaskSummary {
  total: number;
  running: number;
  queued: number;
  completed: number;
  failed: number;
  waitingApproval: number;
}

// ---------------------------------------------------------------------------
// State
// ---------------------------------------------------------------------------

interface RunningTask {
  task: MultitaskTask;
  scope: CancellationScope;
  abortController: AbortController;
}

interface ApprovalRecord {
  id: string;
  taskId: string;
  title: string;
  description: string;
  capability: string;
  createdAt: string;
}

// ---------------------------------------------------------------------------
// MultitaskingEngine
// ---------------------------------------------------------------------------

export class MultitaskingEngine {
  private readonly requests = new Map<string, MultitaskRequest>();
  private readonly plans = new Map<string, MultitaskPlan>();
  private readonly requestPlanIds = new Map<string, string>();
  private readonly tasks = new Map<string, MultitaskTask>();
  private readonly running = new Map<string, RunningTask>();
  private readonly pendingByRequest = new Map<string, Set<string>>();
  private readonly approvals = new Map<string, ApprovalRecord>();

  private globalConcurrency = 1;
  private runningCount = 0;
  private readonly maxConcurrencyPerUser = 8;

  private pumpTimer: ReturnType<typeof setImmediate> | null = null;
  private disposed = false;

  private readonly dataDir: string;
  private readonly writer: DebouncedJsonWriter;
  private readonly file: string;

  constructor(
    private readonly store: TaskStore,
    private readonly manager: TaskManager,
    private readonly router: ModelRouter,
    dataDir: string = "",
  ) {
    this.dataDir = dataDir || process.cwd();
    this.file = path.join(this.dataDir, "tasks", "multitasks.v1.json");
    this.writer = new DebouncedJsonWriter(this.file, 400);
  }

  // ---------------------------------------------------------------------------
  // Public API
  // ---------------------------------------------------------------------------

  async initialize(): Promise<void> {
    const stored = await readJsonFile<{ version: number; plans: MultitaskPlan[]; tasks: MultitaskTask[]; requests: MultitaskRequest[] }>(this.file, { version: 1, plans: [], tasks: [], requests: [] });
    for (const req of stored.requests || []) this.requests.set(req.id, req);
    for (const plan of stored.plans || []) this.plans.set(plan.id, plan);
    for (const task of stored.tasks || []) {
      // Recover: anything live at crash time is marked interrupted/failed.
      if (task.state === "running" || task.state === "retrying") {
        task.state = "failed";
        task.error = task.error || "Interrupted by application restart.";
        task.completedAt = new Date().toISOString();
      }
      this.tasks.set(task.id, task);
    }
    for (const plan of stored.plans || []) {
      if (plan.requestId) this.requestPlanIds.set(plan.requestId, plan.id);
    }
    // Re-schedule any queued/pending work.
    this.schedulePump();
    this.schedulePersist();
  }

  private schedulePersist(): void {
    this.writer.schedule(() => ({
      version: 1,
      plans: [...this.plans.values()],
      tasks: [...this.tasks.values()],
      requests: [...this.requests.values()],
    }));
  }

  async flush(): Promise<void> {
    await this.writer.flush();
  }

  setMaxConcurrency(n: number): void {
    this.globalConcurrency = Math.max(1, Math.min(n, 16));
  }

  getMaxConcurrency(): number {
    return this.globalConcurrency;
  }

  /**
   * Validate a multitask execution plan without creating tasks.
   */
  validatePlan(request: MultitaskRequest): { valid: boolean; error?: string; plan: MultitaskPlan } {
    try {
      const plan = this.buildPlan(request);
      return { valid: true, plan };
    } catch (err) {
      return { valid: false, error: err instanceof Error ? err.message : String(err), plan: null as never };
    }
  }

  /**
   * Decompose a natural-language instruction into a structured task plan.
   * First tries the model router (lightweight model for planning); if no
   * model is configured or the model call fails, falls back to a
   * deterministic rule-based splitter so multitasking still works offline.
   * Returns a validated MultitaskRequest ready for submit().
   */
  async decompose(instruction: string, options: { signal?: AbortSignal; createdBy?: "voice" | "text" | "api" } = {}): Promise<MultitaskRequest> {
    const trimmed = instruction.trim();
    if (!trimmed) throw new Error("An instruction is required.");

    let request: MultitaskRequest | null = null;
    try {
      request = await this.decomposeWithModel(trimmed, options);
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      log.warn("model decomposition unavailable; using rule-based splitter", { error: message });
      request = this.decomposeWithRules(trimmed, options.createdBy ?? "text");
    }
    // Validate the final plan shape (dependencies, cycles) before returning.
    const validation = this.validatePlan(request);
    if (!validation.valid) throw new Error(validation.error || "Decomposed plan is invalid.");
    return request;
  }

  private async decomposeWithModel(instruction: string, options: { signal?: AbortSignal; createdBy?: "voice" | "text" | "api" } = {}): Promise<MultitaskRequest> {
    const prompt = [
      "Break the user's instruction into a parallel, dependency-aware execution plan. Return JSON only.",
      `Instruction: ${instruction.slice(0, 2_000)}`,
      'Schema: {"description":"one-line goal","tasks":[{"title":"short title","description":"one sentence of what this task does","dependsOn":["earlier task title or slug"],"agentCapability":"research|coding|document|spreadsheet|presentation|email|browser|data|reasoning","maxRetries":0}]}',
      "Rules: keep each task self-contained; dependencies reference earlier task titles; no circular dependencies; no more than 12 tasks; do not fabricate outputs; mark descriptions that send/publish/delete/pay as sensitive.",
    ].join("\n");

    const response = await this.router.generate("planning", {
      purpose: "multiengine.decompose",
      messages: [{ role: "user", parts: [{ type: "text", text: prompt }] }],
      maxOutputTokens: 2_000,
    }, { signal: options.signal, role: "background", maxAttempts: 1, structuredOutput: true });

    const parsed = parseJsonLoose(response.text);
    if (!parsed || typeof parsed !== "object") throw new Error("Planner returned invalid JSON.");
    const raw = parsed as { description?: unknown; tasks?: unknown };
    const description = String(raw.description || instruction).slice(0, 500);
    const rawTasks = Array.isArray(raw.tasks) ? raw.tasks : [];
    if (!rawTasks.length) throw new Error("Planner returned no tasks.");
    const tasks: MultitaskTaskSpec[] = rawTasks.slice(0, 12).map((value, index) => {
      if (!value || typeof value !== "object") throw new Error(`Planner task ${index + 1} is invalid.`);
      const spec = value as Record<string, unknown>;
      const title = String(spec.title || "").trim();
      const desc = String(spec.description || "").trim();
      if (!title || !desc) throw new Error(`Planner task ${index + 1} needs title and description.`);
      const capability = String(spec.agentCapability || "reasoning").trim();
      return {
        title: title.slice(0, 120),
        description: desc.slice(0, 400),
        dependsOn: Array.isArray(spec.dependsOn) ? spec.dependsOn.map(String) : [],
        agentCapability: capability,
        maxRetries: Math.max(0, Math.min(3, Number(spec.maxRetries ?? 0))),
        sensitive: spec.sensitive === true,
      };
    });

    return {
      id: `req_${randomUUID().slice(0, 8)}`,
      description,
      tasks,
      maxConcurrency: this.globalConcurrency,
      createdBy: options.createdBy ?? "text",
      createdAt: new Date().toISOString(),
    };
  }

  /**
   * Deterministic fallback: split the instruction into separate action
   * segments (no LLM needed) so multitasking works without a configured
   * model. Segments after "then" are made dependent on the previous one;
   * otherwise segments run independently.
   */
  private decomposeWithRules(instruction: string, createdBy: "voice" | "text" | "api"): MultitaskRequest {
    const verbs = /\b(send|find|research|create|prepare|summarize|write|make|draft|build|list|download|email|open|call|book|install|schedule|analyze|plan|compose|generate|update|clean|organize|review|check)\b/i;
    // Split at conjunction boundaries that start a new action.
    const rawSegments = instruction
      .split(/\s*(?:,|\.)\s+|\s+\band\s+(?:also\s+)?|\s+\bplus\s+|\s+\band\s+then\s+|\s+\bthen\s+/i)
      .map((seg) => seg.trim())
      .filter(Boolean);
    const segments = rawSegments.filter((seg) => verbs.test(seg)).slice(0, 12);
    if (segments.length < 2) {
      // Not decomposable into multiple actions — treat as one task so the
      // caller still gets a valid (single) plan rather than an error.
      const tasks: MultitaskTaskSpec[] = [{
        title: instruction.slice(0, 80),
        description: instruction.slice(0, 400),
        dependsOn: [],
        agentCapability: capabilityFor(instruction),
        maxRetries: 1,
        sensitive: /\b(send|publish|delete|pay|install|email|message)\b/i.test(instruction),
      }];
      return {
        id: `req_${randomUUID().slice(0, 8)}`,
        description: instruction.slice(0, 500),
        tasks,
        maxConcurrency: this.globalConcurrency,
        createdBy,
        createdAt: new Date().toISOString(),
      };
    }
    // Chain segments after "then"; separate "and" clauses are independent.
    const tasks: MultitaskTaskSpec[] = [];
    let lastDep: string | null = null;
    for (const seg of segments) {
      const isThen = /\s+then\s+/i.test(instruction) && tasks.length > 0;
      const dependsOn = isThen && lastDep ? [lastDep] : [];
      const title = seg.replace(/\b(please|pls|ko|kar do|kar de|bana do|bhej do)\b/gi, "").replace(/\s+/g, " ").trim().slice(0, 80) || seg.slice(0, 80);
      tasks.push({
        title,
        description: seg.slice(0, 400),
        dependsOn,
        agentCapability: capabilityFor(seg),
        maxRetries: 1,
        sensitive: /\b(send|publish|delete|pay|install|email|message)\b/i.test(seg),
      });
      lastDep = title;
    }
    return {
      id: `req_${randomUUID().slice(0, 8)}`,
      description: instruction.slice(0, 500),
      tasks,
      maxConcurrency: this.globalConcurrency,
      createdBy,
      createdAt: new Date().toISOString(),
    };
  }

  /**
   * Submit a validated multitask request and begin execution.
   */
  submit(request: MultitaskRequest): MultitaskPlan {
    const existing = this.requestPlanIds.get(request.id);
    if (existing) {
      const plan = this.plans.get(existing);
      if (plan) return plan;
    }
    this.requests.set(request.id, request);
    const plan = this.buildPlan(request);
    this.plans.set(plan.id, plan);
    this.requestPlanIds.set(request.id, plan.id);

    for (const task of plan.tasks) {
      this.tasks.set(task.id, task);
    }

    this.publishPlanEvent(plan);
    appEvents.publish("mtask.batch_submitted", {
      planId: plan.id,
      requestId: request.id,
      taskCount: plan.total,
    });

    this.schedulePump();
    this.schedulePersist();
    this.schedulePersist();
    return plan;
  }

  /**
   * Get all tasks for a request.
   */
  getTasks(requestId: string): MultitaskTask[] {
    const plan = this.plans.get(requestId) ?? [...this.plans.values()].find((p) => p.requestId === requestId);
    if (!plan) return [];
    return plan.tasks.map((t) => this.tasks.get(t.id)!).filter(Boolean);
  }

  /**
   * Get a single task.
   */
  getTask(taskId: string): MultitaskTask | undefined {
    return this.tasks.get(taskId);
  }

  /**
   * Get execution summary counts.
   */
  summary(): MultitaskSummary {
    const all = [...this.tasks.values()];
    return {
      total: all.length,
      running: all.filter((t) => t.state === "running").length,
      queued: all.filter((t) => t.state === "queued" || t.state === "pending").length,
      completed: all.filter((t) => t.state === "completed").length,
      failed: all.filter((t) => t.state === "failed" || t.state === "timed_out").length,
      waitingApproval: all.filter((t) => t.state === "waiting_for_approval").length,
    };
  }

  /**
   * Get all active plans.
   */
  listPlans(): MultitaskPlan[] {
    return [...this.plans.values()];
  }

  /** All tasks across every plan (for live replay / resync). */
  allTasks(): MultitaskTask[] {
    return [...this.tasks.values()];
  }

  /** The plan a task belongs to, if any. */
  planIdOf(taskId: string): string | null {
    return this.findPlanOfTask(taskId);
  }

  /**
   * Update a task's scheduling priority (0..1).
   */
  setPriority(taskId: string, priority: number): boolean {
    const task = this.tasks.get(taskId);
    if (!task) return false;
    if (!Number.isFinite(priority) || priority < 0 || priority > 1) return false;
    task.priority = Math.round(priority * 100) / 100;
    this.emitUpdate(task);
    this.schedulePump();
    return true;
  }

  /**
   * Translate a natural-language instruction such as "pause the second task",
   * "cancel all tasks" or "retry the failed tasks" into engine control actions.
   *
   * Returns a human-readable response when the text clearly refers to task
   * control on tasks the engine already tracks; returns null otherwise so the
   * text can be handled as a normal instruction (new task or conversation).
   */
  controlByText(text: string): { message: string } | null {
    const lower = text.trim().toLowerCase();
    if (!/\btasks?\b/.test(lower) && !/\beverything\b/.test(lower)) return null;
    // Creation phrasing must never be treated as task control.
    if (/\b(add|create|new|save|remind|draft|write|make|compose)\b/.test(lower)) return null;
    const hasVerb = /\b(pause|hold|resume|unpause|continue|cancel|stop|abort|kill|retry|status|list|report|progress|priority)\b/.test(lower);
    if (!hasVerb) return null;

    const all = this.allTasks();
    const picked = this.resolveControlTargets(lower, all);
    const targets = picked === "all" ? all : picked;
    const label = (tasks: MultitaskTask[]) => tasks.map((t) => `"${t.title}"`).join(", ");

    if (/\b(status|report|progress|list|show)\b/.test(lower) && !/\b(pause|resume|cancel|stop|retry|priority)\b/.test(lower)) {
      if (all.length === 0) return { message: "No tasks are being tracked right now." };
      const s = this.summary();
      const lines = all.slice(0, 6).map((t) => `• "${t.title}" — ${t.state}${t.state === "running" ? ` (${t.progress}%)` : ""}`);
      return { message: `${s.total} task(s): ${s.running} running, ${s.queued} queued, ${s.completed} completed, ${s.failed} failed.\n${lines.join("\n")}` };
    }

    const actionable = targets.filter((t) => !TERMINAL_STATES_MULTITASK.has(t.state));

    if (/\bretry\b/.test(lower)) {
      const failed = targets.filter((t) => t.state === "failed" || t.state === "timed_out");
      const done = failed.filter((t) => this.retry(t.id));
      return { message: done.length > 0 ? `Retrying ${label(done)}.` : "Nothing to retry right now." };
    }

    if (/\b(pause|hold)\b/.test(lower)) {
      const done = actionable.filter((t) => this.pause(t.id));
      return { message: done.length > 0 ? `Paused ${label(done)}.` : "No running or queued tasks to pause." };
    }

    if (/\b(resume|unpause|continue)\b/.test(lower)) {
      const done = targets.filter((t) => t.state === "paused").filter((t) => this.resume(t.id));
      return { message: done.length > 0 ? `Resumed ${label(done)}.` : "No paused tasks to resume." };
    }

    if (/\b(cancel|stop|abort|kill)\b/.test(lower)) {
      const done = actionable.filter((t) => this.cancel(t.id));
      return { message: done.length > 0 ? `Cancelled ${label(done)}.` : "No active tasks to cancel." };
    }

    if (/\bpriority\b/.test(lower)) {
      const raise = /\b(higher|raise|increase|high|up)\b/.test(lower);
      const drop = /\b(lower|reduce|decrease|low|down)\b/.test(lower);
      if (!raise && !drop) return { message: "Say 'raise priority' or 'lower priority' and I'll adjust the task." };
      const delta = raise ? 0.2 : -0.2;
      const done = actionable.filter((t) => this.setPriority(t.id, Math.max(0, Math.min(1, t.priority + delta))));
      return { message: done.length > 0 ? `${raise ? "Raised" : "Lowered"} priority for ${label(done)}.` : "No active tasks to reprioritize." };
    }

    return null;
  }

  /** Resolve "all", "the second task", "task 2", "the last task" or a quoted title to tracked tasks. */
  private resolveControlTargets(lower: string, all: MultitaskTask[]): MultitaskTask[] | "all" {
    const numeric = lower.match(/\btask\s*#?\s*(\d+)\b/);
    if (numeric) {
      const idx = Number(numeric[1]) - 1;
      return idx >= 0 && idx < all.length ? [all[idx]] : [];
    }
    const ordinals: Record<string, number> = { first: 1, "1st": 1, second: 2, "2nd": 2, third: 3, "3rd": 3, fourth: 4, "4th": 4, fifth: 5, "5th": 5 };
    const ordinal = lower.match(/\b(first|1st|second|2nd|third|3rd|fourth|4th|fifth|5th)\b/);
    if (ordinal) {
      const idx = ordinals[ordinal[1]] - 1;
      return idx >= 0 && idx < all.length ? [all[idx]] : [];
    }
    if (/\blast\b/.test(lower)) return all.length > 0 ? [all[all.length - 1]] : [];
    const quoted = lower.match(/"([^"]+)"/);
    if (quoted) return all.filter((t) => t.title.toLowerCase().includes(quoted[1]));
    return "all";
  }

  /**
   * Pause a running or queued task.
   */
  pause(taskId: string): boolean {
    const task = this.tasks.get(taskId);
    if (!task) return false;
    if (task.state === "running") {
      const running = this.running.get(taskId);
      if (running) {
        running.scope.cancel("user_pause");
        task.state = "paused";
        task.progressMessage = "Paused by user.";
        this.emitUpdate(task);
        this.schedulePump();
    this.schedulePersist();
        return true;
      }
    }
    if (task.state === "queued" || task.state === "pending") {
      task.state = "paused";
      this.emitUpdate(task);
      return true;
    }
    return false;
  }

  /**
   * Resume a paused task.
   */
  resume(taskId: string): boolean {
    const task = this.tasks.get(taskId);
    if (!task) return false;
    if (task.state === "paused") {
      const depsDone = this.dependenciesSatisfied(task);
      if (!depsDone) {
        task.state = "waiting_for_dependency";
      } else if (task.requiresApproval && !task.approvalId) {
        task.state = "waiting_for_approval";
      } else {
        task.state = "queued";
      }
      this.emitUpdate(task);
      this.schedulePump();
    this.schedulePersist();
      return true;
    }
    return false;
  }

  /**
   * Cancel a task.
   */
  cancel(taskId: string): boolean {
    const task = this.tasks.get(taskId);
    if (!task) return false;
    const prev = task.state;
    if (TERMINAL_STATES_MULTITASK.has(task.state)) return false;

    if (task.state === "running") {
      const running = this.running.get(taskId);
      if (running) {
        running.scope.cancel("user_cancel");
        running.abortController.abort();
      }
    }
    task.state = "cancelled";
    task.completedAt = new Date().toISOString();
    this.running.delete(taskId);
    if (this.runningCount > 0) this.runningCount--;
    this.emitUpdate(task);
    appEvents.publish("mtask.task_cancelled", { taskId, planId: this.findPlanOfTask(taskId) });
    this.unblockDependents(taskId);
    this.schedulePump();
    this.schedulePersist();
    return true;
  }

  /**
   * Retry a failed task.
   */
  retry(taskId: string): boolean {
    const task = this.tasks.get(taskId);
    if (!task || (task.state !== "failed" && task.state !== "timed_out")) return false;
    if (task.retryCount >= task.maxRetries) return false;
    task.retryCount++;
    task.state = "queued";
    task.error = null;
    task.result = null;
    task.startedAt = null;
    task.completedAt = null;
    task.progress = 0;
    task.progressMessage = "";
    this.emitUpdate(task);
    this.schedulePump();
    this.schedulePersist();
    return true;
  }

  /**
   * Approve a task waiting for approval.
   */
  approve(taskId: string): boolean {
    const task = this.tasks.get(taskId);
    if (!task || task.state !== "waiting_for_approval") return false;
    task.approvalId = null;
    task.requiresApproval = false;
    task.state = "queued";
    this.emitUpdate(task);
    this.schedulePump();
    this.schedulePersist();
    return true;
  }

  /**
   * Reject a task waiting for approval.
   */
  reject(taskId: string): boolean {
    const task = this.tasks.get(taskId);
    if (!task || task.state !== "waiting_for_approval") return false;
    task.state = "cancelled";
    task.completedAt = new Date().toISOString();
    task.error = "Rejected by user.";
    this.emitUpdate(task);
    this.unblockDependents(taskId);
    this.schedulePump();
    this.schedulePersist();
    return true;
  }

  /**
   * Stop all tasks for a request.
   */
  cancelRequest(requestId: string): number {
    const tasks = this.getTasks(requestId);
    let count = 0;
    for (const task of tasks) {
      if (this.cancel(task.id)) count++;
    }
    return count;
  }

  dispose(): void {
    this.disposed = true;
    if (this.pumpTimer) {
      clearImmediate(this.pumpTimer);
      this.pumpTimer = null;
    }
    for (const running of this.running.values()) {
      running.scope.cancel("engine_disposed");
    }
    this.running.clear();
  }

  // ---------------------------------------------------------------------------
  // Private â€” plan building
  // ---------------------------------------------------------------------------

  private buildPlan(request: MultitaskRequest): MultitaskPlan {
    const now = new Date().toISOString();
    const planId = `plan_${randomUUID().slice(0, 8)}`;
    const tasks: MultitaskTask[] = request.tasks.map((spec, index) => {
      const id = spec.title.toLowerCase().replace(/[^a-z0-9]+/g, "_").slice(0, 48) || `task_${index + 1}`;
      return {
        id: `${planId}_${id}`,
        title: spec.title,
        description: spec.description,
        dependsOn: spec.dependsOn || [],
        priority: spec.priority ?? 0.5,
        maxRetries: spec.maxRetries ?? 2,
        timeoutMs: spec.timeoutMs ?? 300_000,
        agentCapability: spec.agentCapability ?? null,
        state: "pending",
        progress: 0,
        progressMessage: "Waiting to be scheduled.",
        result: null,
        error: null,
        createdAt: now,
        startedAt: null,
        completedAt: null,
        retryCount: 0,
        sessionId: null,
        requiresApproval: this.detectRequiresApproval(spec.description),
        approvalId: null,
      };
    });

    // Resolve user-supplied dependency references to actual generated IDs.
    // A dependsOn entry may match the generated ID, the task's title slug,
    // or the task's title itself (case-insensitive).
    const idMap = new Map<string, string>();
    for (const task of tasks) {
      idMap.set(task.id, task.id);
      idMap.set(task.id.toLowerCase(), task.id);
      idMap.set(slugify(task.title), task.id);
      idMap.set(task.title.toLowerCase(), task.id);
    }
    for (const task of tasks) {
      task.dependsOn = task.dependsOn.map((dep) => idMap.get(dep.toLowerCase()) ?? dep);
    }

    this.validateDAG(tasks);
    const parallelizable = tasks.filter((t) => t.dependsOn.length === 0).length;
    return { id: planId, requestId: request.id, createdAt: now, tasks, total: tasks.length, parallelizable };
  }

  private validateDAG(tasks: MultitaskTask[]): void {
    const ids = new Set(tasks.map((t) => t.id));
    for (const task of tasks) {
      for (const dep of task.dependsOn) {
        if (!ids.has(dep)) throw new Error(`Task '${task.id}' depends on unknown task '${dep}'.`);
      }
      if (task.dependsOn.includes(task.id)) throw new Error(`Task '${task.id}' cannot depend on itself.`);
    }
    const visiting = new Set<string>();
    const visited = new Set<string>();
    const byId = new Map(tasks.map((t) => [t.id, t]));
    const visit = (id: string) => {
      if (visiting.has(id)) throw new Error(`Cycle detected at task '${id}'.`);
      if (visited.has(id)) return;
      visiting.add(id);
      for (const dep of byId.get(id)?.dependsOn || []) visit(dep);
      visiting.delete(id);
      visited.add(id);
    };
    for (const task of tasks) visit(task.id);
  }

  private detectRequiresApproval(description: string): boolean {
    return /\b(send|email|mail|message|delete|remove|install|buy|purchase|pay|post|publish|submit|execute|run|grant|revoke)/i.test(description);
  }

  // ---------------------------------------------------------------------------
  // Private â€” scheduling
  // ---------------------------------------------------------------------------

  private schedulePump(): void {
    if (this.pumpTimer || this.disposed) return;
    this.pumpTimer = setImmediate(() => {
      this.pumpTimer = null;
      if (!this.disposed) this.pump();
    });
  }

  private pump(): void {
    if (this.disposed) return;
    if (this.runningCount >= this.globalConcurrency) return;

    const availableSlots = this.globalConcurrency - this.runningCount;
    if (availableSlots <= 0) return;

    const eligible = this.getEligibleTasks().slice(0, availableSlots);
    for (const task of eligible) {
      this.startTask(task);
    }
  }

  private getEligibleTasks(): MultitaskTask[] {
    const changed = new Set<MultitaskTask>();
    for (const task of this.tasks.values()) {
      if (task.state === "pending") {
        if (this.dependenciesSatisfied(task)) {
          if (task.requiresApproval && !task.approvalId) {
            task.state = "waiting_for_approval";
            appEvents.publish("mtask.task_waiting_approval", { taskId: task.id, planId: this.findPlanOfTask(task.id) });
          } else {
            task.state = "queued";
          }
          changed.add(task);
        } else if (task.dependsOn.length > 0) {
          task.state = "waiting_for_dependency";
          changed.add(task);
        }
      }
    }
    for (const task of changed) this.emitUpdate(task);

    return [...this.tasks.values()]
      .filter((task) => task.state === "queued" && !this.running.has(task.id))
      .sort((a, b) => b.priority - a.priority);
  }

  private dependenciesSatisfied(task: MultitaskTask): boolean {
    if (task.dependsOn.length === 0) return true;
    for (const depId of task.dependsOn) {
      const dep = this.tasks.get(depId);
      if (!dep) continue;
      if (dep.state !== "completed") return false;
    }
    return true;
  }

  private unblockDependents(finishedId: string): void {
    for (const task of this.tasks.values()) {
      if (task.state !== "waiting_for_dependency" || !task.dependsOn.includes(finishedId)) continue;
      const failedDep = task.dependsOn.find((depId) => {
        const dep = this.tasks.get(depId);
        return dep && (dep.state === "failed" || dep.state === "cancelled" || dep.state === "timed_out");
      });
      if (failedDep) {
        const dep = this.tasks.get(failedDep)!;
        task.state = dep.state === "cancelled" ? "cancelled" : "failed";
        task.error = `Prerequisite '${dep.title}' did not complete (${dep.state}).`;
        task.completedAt = new Date().toISOString();
        this.emitUpdate(task);
        appEvents.publish(task.state === "cancelled" ? "mtask.task_cancelled" : "mtask.task_failed", {
          taskId: task.id,
          planId: this.findPlanOfTask(task.id),
          error: task.error,
        });
        continue;
      }
      if (this.dependenciesSatisfied(task)) {
        if (task.requiresApproval && !task.approvalId) {
          task.state = "waiting_for_approval";
        } else {
          task.state = "queued";
        }
        this.emitUpdate(task);
      }
    }
  }

  // ---------------------------------------------------------------------------
  // Private â€” execution
  // ---------------------------------------------------------------------------

  private async startTask(task: MultitaskTask): Promise<void> {
    if (this.running.has(task.id)) return;
    if (this.runningCount >= this.globalConcurrency) return;
    if (TERMINAL_STATES_MULTITASK.has(task.state)) return;

    const scope = rootScope.child(`mtask:${task.id}`);
    const abortController = new AbortController();
    const signal = abortController.signal;

    task.state = "running";
    task.startedAt = new Date().toISOString();
    task.progress = 5;
    task.progressMessage = "Starting task...";
    this.runningCount++;
    this.running.set(task.id, { task, scope, abortController });
    this.emitUpdate(task);
    appEvents.publish("mtask.task_started", { taskId: task.id, planId: this.findPlanOfTask(task.id) });

    const timeout = setTimeout(() => {
      if (!scope.cancelled) scope.cancel("timeout");
    }, task.timeoutMs);
    timeout.unref?.();

    try {
      // All multitask steps are executed by the real agent (TaskManager),
      // which runs the existing perception → plan → act → verify loop and
      // supports browser, office, file and messaging tools. `agentCapability`
      // is preserved as routing metadata for future per-capability model
      // selection. Tasks run via startParallel so independent steps execute
      // concurrently instead of queueing behind the serial pump.
      const session = this.manager.startParallel(task.description, "api", {});
      task.sessionId = session.id;

      const result = await this.waitForSession(session, scope, signal);
      // Only the outcome of a task that is still "running" may change its
      // state. If the user cancelled or paused it meanwhile, those decisions
      // win — otherwise a cancelled task would silently restart itself.
      if (result.ok && task.state === "running") {
        task.state = "completed";
        task.result = result.summary;
        task.progress = 100;
        task.progressMessage = "Done.";
      } else if (task.state !== "running") {
        // Cancelled/paused while the session was aborting: keep the user's state.
      } else if (scope.reason === "timeout") {
        task.state = "timed_out";
        task.error = `Task exceeded its ${Math.round(task.timeoutMs / 1000)}s budget.`;
        task.progressMessage = "Timed out.";
        task.completedAt = new Date().toISOString();
      } else {
        const canRetry = task.retryCount < task.maxRetries;
        task.state = canRetry ? "retrying" : "failed";
        task.error = result.error || result.summary;
        if (canRetry) {
          task.progressMessage = `Retrying (${task.retryCount + 1}/${task.maxRetries})...`;
          task.retryCount++;
        } else {
          task.progressMessage = "Failed.";
        }
      }
    } catch (err) {
      if (scope.cancelled || signal.aborted) {
        if (task.state === "running") {
          if (scope.reason === "timeout") {
            task.state = "timed_out";
            task.error = `Task exceeded its ${Math.round(task.timeoutMs / 1000)}s budget.`;
            task.progressMessage = "Timed out.";
          } else {
            task.state = "cancelled";
            task.progressMessage = "Cancelled.";
          }
          task.completedAt = new Date().toISOString();
        }
      } else if (task.state === "running") {
        const canRetry = task.retryCount < task.maxRetries;
        task.state = canRetry ? "retrying" : "failed";
        task.error = err instanceof Error ? err.message : String(err);
        if (canRetry) {
          task.progressMessage = `Retry ${task.retryCount + 1}/${task.maxRetries} in a moment...`;
        }
      }
    } finally {
      clearTimeout(timeout);
      scope.dispose();
      this.running.delete(task.id);
      if (this.runningCount > 0) this.runningCount--;
      if (!TERMINAL_STATES_MULTITASK.has(task.state)) {
        if (task.state === "retrying") {
          task.state = "queued";
        } else if (task.state !== "completed" && task.state !== "cancelled" && task.state !== "failed") {
          task.state = task.state === "running" ? "failed" : task.state;
        }
      }
      if (TERMINAL_STATES_MULTITASK.has(task.state)) {
        task.completedAt = task.completedAt || new Date().toISOString();
      }
      this.emitUpdate(task);

      if (task.state === "completed") {
        appEvents.publish("mtask.task_completed", { taskId: task.id, planId: this.findPlanOfTask(task.id) });
      } else if (task.state === "failed" || task.state === "timed_out") {
        appEvents.publish("mtask.task_failed", { taskId: task.id, planId: this.findPlanOfTask(task.id), error: task.error, timedOut: task.state === "timed_out" });
      }

      this.unblockDependents(task.id);
      this.schedulePump();
    this.schedulePersist();
    }
  }

  private async waitForSession(
    session: TaskSession,
    scope: CancellationScope,
    signal: AbortSignal,
  ): Promise<{ ok: boolean; summary: string; error?: string }> {
    return new Promise((resolve) => {
      const unsubscribe = this.store.subscribe((s) => {
        if (s.id !== session.id) return;
        if (s.state === "completed") {
          unsubscribe();
          resolve({ ok: true, summary: s.result?.summary || "Done." });
        } else if (s.state === "failed" || s.state === "cancelled" || s.state === "interrupted") {
          unsubscribe();
          resolve({ ok: false, summary: s.error || s.currentStatus, error: s.error || undefined });
        }
      });

      scope.signal.addEventListener("abort", () => {
        unsubscribe();
        if (!TERMINAL_STATES.has(session.state)) {
          this.manager.stop(session.id, "scope_cancelled");
        }
        resolve({ ok: false, summary: "Cancelled." });
      });

      signal.addEventListener("abort", () => {
        unsubscribe();
        if (!TERMINAL_STATES.has(session.state)) {
          this.manager.stop(session.id, "signal_aborted");
        }
        resolve({ ok: false, summary: "Aborted." });
      });
    });
  }

  // ---------------------------------------------------------------------------
  // Private â€” events
  // ---------------------------------------------------------------------------

  private emitUpdate(task: MultitaskTask): void {
    appEvents.publish("mtask.task_progress", {
      taskId: task.id,
      planId: this.findPlanOfTask(task.id),
      state: task.state,
      progress: task.progress,
      progressMessage: task.progressMessage,
      result: task.result,
      error: task.error,
    });
  }

  private findPlanOfTask(taskId: string): string | null {
    for (const plan of this.plans.values()) {
      if (plan.tasks.some((t) => t.id === taskId)) return plan.id;
    }
    return null;
  }

  private publishPlanEvent(plan: MultitaskPlan): void {
    appEvents.publish("mtask.plan_created", {
      planId: plan.id,
      requestId: plan.requestId,
      total: plan.total,
      parallelizable: plan.parallelizable,
      tasks: plan.tasks.map((t) => ({ id: t.id, title: t.title, dependsOn: t.dependsOn, priority: t.priority })),
    });
  }
}

const TERMINAL_STATES_MULTITASK: ReadonlySet<MultitaskTaskState> = new Set(["completed", "failed", "cancelled", "timed_out"]);

function slugify(text: string): string {
  return text.toLowerCase().replace(/[^a-z0-9]+/g, "_").slice(0, 48);
}

function parseJsonLoose(text: string): unknown {
  const cleaned = text.replace(/^```(?:json)?\s*/i, "").replace(/\s*```$/i, "").trim();
  const start = cleaned.indexOf("{");
  const end = cleaned.lastIndexOf("}");
  if (start >= 0 && end > start) return JSON.parse(cleaned.slice(start, end + 1));
  return JSON.parse(cleaned);
}

/** Map a segment's keywords to a declared agent capability. */
function capabilityFor(text: string): string {
  if (/\b(summarize|summarise|inbox|email|mail|outlook|gmail)\b/i.test(text)) return "email";
  if (/\b(excel|spreadsheet|sheet|csv|data)\b/i.test(text)) return "spreadsheet";
  if (/\b(presentation|slides|ppt|deck|powerpoint)\b/i.test(text)) return "presentation";
  if (/\b(document|doc|word|report|letter|note|file)\b/i.test(text)) return "document";
  if (/\b(research|search|find|look up|investigate|trend|analyze|compare)\b/i.test(text)) return "research";
  if (/\b(code|coding|script|program|build app|develop)\b/i.test(text)) return "coding";
  if (/\b(browser|website|web|url|page)\b/i.test(text)) return "browser";
  return "reasoning";
}


