/**
 * JARVIS — Feature Registry types, manifest schema and validation.
 *
 * A *feature* is a self-describing unit of functionality. Its manifest declares
 * exactly what it contributes (backend modules, tools, routes, settings,
 * frontend entry points, permissions, database migrations, dependencies) so the
 * application can integrate it automatically through an explicit contract —
 * never by scanning arbitrary source files or trusting an AI-generated blob.
 *
 * The schema is deliberately strict about identity and paths but tolerant of
 * optional fields, so a simple backend-only feature is as easy to declare as a
 * full frontend page.
 *
 * Security: feature discovery is NOT feature authorization. A manifest is only
 * ever *validated* by this module; every operation it maps to is re-checked by
 * the backend role layer before it is exposed.
 */

export type FeatureLifecycleState =
  | "discovered"
  | "validating"
  | "building"
  | "awaiting_approval"
  | "ready"
  | "activating"
  | "active"
  | "failed"
  | "disabled"
  | "rolling_back";

export const FEATURE_LIFECYCLE_STATES: readonly FeatureLifecycleState[] = [
  "discovered",
  "validating",
  "building",
  "awaiting_approval",
  "ready",
  "activating",
  "active",
  "failed",
  "disabled",
  "rolling_back",
];

/** Where a feature contributes user-facing UI. */
export type FeatureFrontendKind =
  | "page"        // a full view/panel
  | "dashboard"   // a card in a dashboard
  | "settings"    // a settings section
  | "action";     // a contextual action / tool

export interface FeatureNavigationEntry {
  /** Route-like key, e.g. "features/core-logs". Must match [a-z0-9-] only. */
  id: string;
  label: string;
  /** lucide icon name resolved by the renderer's icon map. */
  icon?: string;
  /** Sort order within the navigation group. */
  order?: number;
  /** Minimum role to see the entry (OWNER | ADMIN | USER | undefined = USER). */
  minRole?: "OWNER" | "ADMIN" | "USER";
}

export interface FeatureToolDecl {
  name: string;
  purpose: string;
  /** Permission bucket: filesystem_read | filesystem_write | network | browser | system_control | desktop_control | code_execution | screen_awareness | messaging. */
  permission?: string;
  riskLevel?: 0 | 1 | 2 | 3 | 4;
  timeoutMs?: number;
  maxRetries?: number;
}

export interface FeatureSettingField {
  key: string;
  label: string;
  type: "text" | "number" | "boolean" | "select";
  options?: string[];
  default?: unknown;
  /** Minimum role allowed to change this setting. */
  minRole?: "OWNER" | "ADMIN" | "USER";
}

export interface FeatureMigration {
  /** Relative path under supabase/migrations, e.g. "0007_my_feature.sql". */
  file: string;
  /** Semantic version this migration applies. */
  version: string;
  /** Whether the migration is safely reversible (expand/contract). */
  reversible: boolean;
}

export interface FeatureDependency {
  /** Feature id, e.g. "core-runtime". */
  id: string;
  /** Semver range; optional when only presence is required. */
  version?: string;
  /** If true, a missing dependency blocks activation. Default true. */
  required?: boolean;
}

export interface FeatureManifest {
  id: string;
  name: string;
  version: string;
  description: string;
  status: FeatureLifecycleState;
  minimumAppVersion?: string;
  /** Backend module ids this feature provides (e.g. "core-logs"). */
  backendModules: string[];
  /** Frontend component ids this feature contributes. */
  frontendEntry?: string;
  navigation?: FeatureNavigationEntry;
  settings?: FeatureSettingField[];
  tools?: FeatureToolDecl[];
  permissions?: string[];
  databaseMigrations?: FeatureMigration[];
  dependencies?: FeatureDependency[];
  featureFlags?: Record<string, boolean>;
  healthCheck?: string;
  activationRequirements?: string[];
  /** Trusted source tag — only manifests from the repo's own features/ dir are accepted at runtime. */
  source: "bundled";
}

/**
 * The manifest as stored on disk (superset of FeatureManifest; unknown keys
 * are ignored rather than trusted).
 */
export interface RawFeatureManifest extends Record<string, unknown> {
  id: string;
  name: string;
  version: string;
  description?: string;
  status?: string;
  backendModules?: unknown;
  frontendEntry?: unknown;
  navigation?: unknown;
  settings?: unknown;
  tools?: unknown;
  permissions?: unknown;
  databaseMigrations?: unknown;
  dependencies?: unknown;
  featureFlags?: unknown;
  healthCheck?: unknown;
  activationRequirements?: unknown;
  minimumAppVersion?: unknown;
}

export interface FeatureValidationResult {
  valid: boolean;
  errors: string[];
}

// ---------------------------------------------------------------------------
// Identity / path safety
// ---------------------------------------------------------------------------

export const FEATURE_ID_RE = /^[a-z0-9][a-z0-9-]{0,63}$/;
export const NAV_ID_RE = /^[a-z0-9][a-z0-9-]{0,127}$/;
export const TOOL_NAME_RE = /^[a-zA-Z][a-zA-Z0-9]{0,63}$/;
export const MODULE_ID_RE = /^[a-z0-9][a-z0-9-]{0,63}$/;

/** A module id must never be usable as a path traversal. */
export function isSafeModuleId(id: unknown): id is string {
  return typeof id === "string" && MODULE_ID_RE.test(id) && !id.includes("..") && !id.includes("/") && !id.includes("\\");
}

/** A manifest path must never escape a trusted root. */
export function isSafeRelativePath(value: unknown, allowDot = false): boolean {
  if (typeof value !== "string" || !value) return false;
  if (value.includes("..") || value.startsWith("/") || value.startsWith("\\")) return false;
  if (/[\\/]/.test(value) && !allowDot) return false;
  if (!allowDot && value.includes(".")) return false;
  return true;
}

// ---------------------------------------------------------------------------
// Semver (tiny, dependency-free)
// ---------------------------------------------------------------------------

export function parseSemver(version: string): { major: number; minor: number; patch: number } | null {
  const m = /^v?(\d+)\.(\d+)\.(\d+)(?:[-+].*)?$/.exec(version.trim());
  if (!m) return null;
  return { major: Number(m[1]), minor: Number(m[2]), patch: Number(m[3]) };
}

/** Compare two valid semver strings; -1/0/1, or null if either is invalid. */
export function compareSemver(a: string, b: string): number | null {
  const pa = parseSemver(a);
  const pb = parseSemver(b);
  if (!pa || !pb) return null;
  for (const key of ["major", "minor", "patch"] as const) {
    if (pa[key] !== pb[key]) return pa[key] > pb[key] ? 1 : -1;
  }
  return 0;
}

/**
 * Check a version against a small semver range grammar: "1.2.3", ">=1.0.0",
 * ">=1.0.0 <2.0.0". Returns true when version satisfies every clause.
 */
export function satisfiesSemver(version: string, range: string): boolean {
  const clauses = range.split(/\s+/).filter(Boolean);
  if (!clauses.length) return true;
  const v = parseSemver(version);
  if (!v) return false;
  for (const clause of clauses) {
    const m = /^(>=|<=|>|<|=)?\s*(?:v)?(\d+)\.(\d+)\.(\d+)$/.exec(clause);
    if (!m) return false;
    const op = m[1] || "=";
    const target = { major: Number(m[2]), minor: Number(m[3]), patch: Number(m[4]) };
    const cmp = (a: number, b: number) => (a > b ? 1 : a < b ? -1 : 0);
    const c = cmp(v.major, target.major) || cmp(v.minor, target.minor) || cmp(v.patch, target.patch);
    let ok = false;
    switch (op) {
      case ">=": ok = c >= 0; break;
      case "<=": ok = c <= 0; break;
      case ">": ok = c > 0; break;
      case "<": ok = c < 0; break;
      case "=": ok = c === 0; break;
    }
    if (!ok) return false;
  }
  return true;
}

// ---------------------------------------------------------------------------
// Validation
// ---------------------------------------------------------------------------

const MIN_ROLES = ["OWNER", "ADMIN", "USER"] as const;
const SETTING_TYPES = ["text", "number", "boolean", "select"] as const;
const PERMISSION_BUCKETS = new Set([
  "filesystem_read", "filesystem_write", "network", "browser", "system_control",
  "desktop_control", "code_execution", "screen_awareness", "messaging",
]);

export function validateManifest(raw: RawFeatureManifest): FeatureValidationResult {
  const errors: string[] = [];

  if (typeof raw.id !== "string" || !FEATURE_ID_RE.test(raw.id)) {
    errors.push("id must be a lowercase [a-z0-9-] string (max 64 chars).");
  }
  if (typeof raw.name !== "string" || !raw.name.trim() || raw.name.length > 80) {
    errors.push("name is required (max 80 chars).");
  }
  if (typeof raw.version !== "string" || !parseSemver(raw.version)) {
    errors.push("version must be a semantic version like 1.0.0.");
  }
  if (raw.description !== undefined && typeof raw.description !== "string") {
    errors.push("description must be a string.");
  }
  if (raw.status !== undefined && !FEATURE_LIFECYCLE_STATES.includes(raw.status as FeatureLifecycleState)) {
    errors.push(`status must be one of: ${FEATURE_LIFECYCLE_STATES.join(", ")}.`);
  }
  if (raw.minimumAppVersion !== undefined && (typeof raw.minimumAppVersion !== "string" || !parseSemver(raw.minimumAppVersion))) {
    errors.push("minimumAppVersion must be a semantic version.");
  }

  // backend_modules
  if (raw.backendModules === undefined || !Array.isArray(raw.backendModules) || raw.backendModules.length === 0) {
    errors.push("backendModules must be a non-empty array of module ids.");
  } else {
    for (const mod of raw.backendModules) {
      if (!isSafeModuleId(mod)) errors.push(`backendModules entry "${String(mod)}" is not a safe module id.`);
    }
    if (new Set(raw.backendModules).size !== raw.backendModules.length) {
      errors.push("backendModules contains duplicate ids.");
    }
  }

  // frontendEntry
  if (raw.frontendEntry !== undefined && !isSafeModuleId(raw.frontendEntry)) {
    errors.push("frontendEntry must be a safe module id (lowercase [a-z0-9-]).");
  }

  // navigation
  if (raw.navigation !== undefined) {
    const nav = raw.navigation as Record<string, unknown>;
    if (typeof nav !== "object" || nav === null) errors.push("navigation must be an object.");
    else {
      if (typeof nav.id !== "string" || !NAV_ID_RE.test(nav.id)) errors.push("navigation.id must be a [a-z0-9-] route id.");
      if (typeof nav.label !== "string" || !nav.label.trim()) errors.push("navigation.label is required.");
      if (nav.icon !== undefined && typeof nav.icon !== "string") errors.push("navigation.icon must be a string.");
      if (nav.minRole !== undefined && !MIN_ROLES.includes(nav.minRole as never)) errors.push("navigation.minRole must be OWNER, ADMIN or USER.");
      if (nav.order !== undefined && (typeof nav.order !== "number" || !Number.isFinite(nav.order))) errors.push("navigation.order must be a number.");
    }
  }

  // settings
  if (raw.settings !== undefined) {
    if (!Array.isArray(raw.settings)) errors.push("settings must be an array.");
    else {
      for (const field of raw.settings as Record<string, unknown>[]) {
        if (typeof field !== "object" || field === null) { errors.push("settings entries must be objects."); continue; }
        if (typeof field.key !== "string" || !/^[a-z][a-z0-9_.-]{0,63}$/.test(field.key)) errors.push(`settings key "${String(field.key)}" is invalid.`);
        if (typeof field.label !== "string" || !field.label.trim()) errors.push("settings label is required.");
        if (!SETTING_TYPES.includes(field.type as never)) errors.push(`settings type "${String(field.type)}" is invalid.`);
        if (field.minRole !== undefined && !MIN_ROLES.includes(field.minRole as never)) errors.push("settings.minRole must be OWNER, ADMIN or USER.");
      }
    }
  }

  // tools
  if (raw.tools !== undefined) {
    if (!Array.isArray(raw.tools)) errors.push("tools must be an array.");
    else {
      const seen = new Set<string>();
      for (const tool of raw.tools as Record<string, unknown>[]) {
        if (typeof tool !== "object" || tool === null) { errors.push("tools entries must be objects."); continue; }
        if (typeof tool.name !== "string" || !TOOL_NAME_RE.test(tool.name)) errors.push(`tools name "${String(tool.name)}" is invalid.`);
        else if (seen.has(tool.name)) errors.push(`tools name "${tool.name}" is duplicated.`);
        else seen.add(tool.name);
        if (typeof tool.purpose !== "string") errors.push(`tools "${String(tool.name)}" needs a purpose string.`);
        if (tool.permission !== undefined && !PERMISSION_BUCKETS.has(String(tool.permission))) errors.push(`tools "${String(tool.name)}" has unknown permission "${String(tool.permission)}".`);
        if (tool.riskLevel !== undefined && ![0, 1, 2, 3, 4].includes(Number(tool.riskLevel))) errors.push(`tools "${String(tool.name)}" riskLevel must be 0-4.`);
      }
    }
  }

  // permissions
  if (raw.permissions !== undefined && !Array.isArray(raw.permissions)) errors.push("permissions must be an array of strings.");

  // databaseMigrations
  if (raw.databaseMigrations !== undefined) {
    if (!Array.isArray(raw.databaseMigrations)) errors.push("databaseMigrations must be an array.");
    else {
      for (const mig of raw.databaseMigrations as Record<string, unknown>[]) {
        if (typeof mig !== "object" || mig === null) { errors.push("databaseMigrations entries must be objects."); continue; }
        if (typeof mig.file !== "string" || !mig.file.match(/^[0-9]+_[a-z0-9_-]+\.sql$/)) errors.push(`databaseMigrations file "${String(mig.file)}" must look like 000N_name.sql.`);
        if (typeof mig.version !== "string" || !parseSemver(mig.version)) errors.push("databaseMigrations version must be a semantic version.");
      }
    }
  }

  // dependencies
  if (raw.dependencies !== undefined) {
    if (!Array.isArray(raw.dependencies)) errors.push("dependencies must be an array.");
    else {
      for (const dep of raw.dependencies as Record<string, unknown>[]) {
        if (typeof dep !== "object" || dep === null) { errors.push("dependencies entries must be objects."); continue; }
        if (typeof dep.id !== "string" || !FEATURE_ID_RE.test(dep.id)) errors.push(`dependencies id "${String(dep.id)}" is invalid.`);
        if (dep.version !== undefined && (typeof dep.version !== "string" || !parseSemver(String(dep.version).replace(/[<>= ]/g, "")))) errors.push(`dependencies "${String(dep.id)}" version must be a semver/range.`);
      }
    }
  }

  // featureFlags
  if (raw.featureFlags !== undefined) {
    if (typeof raw.featureFlags !== "object" || raw.featureFlags === null || Array.isArray(raw.featureFlags)) {
      errors.push("featureFlags must be an object of boolean flags.");
    } else {
      for (const [k, v] of Object.entries(raw.featureFlags)) {
        if (typeof v !== "boolean") errors.push(`featureFlags.${k} must be a boolean.`);
      }
    }
  }

  if (raw.healthCheck !== undefined && typeof raw.healthCheck !== "string") errors.push("healthCheck must be a string.");
  if (raw.activationRequirements !== undefined && !Array.isArray(raw.activationRequirements)) errors.push("activationRequirements must be an array of strings.");
  if (raw.source !== undefined && raw.source !== "bundled") errors.push("source must be 'bundled' (only trusted repo manifests are accepted).");

  return { valid: errors.length === 0, errors };
}

/** Normalize a validated raw manifest into a fully-typed manifest. */
export function normalizeManifest(raw: RawFeatureManifest): FeatureManifest {
  const backendModules = Array.isArray(raw.backendModules)
    ? (raw.backendModules as unknown[]).map(String)
    : [];
  const navigation = raw.navigation as FeatureNavigationEntry | undefined;
  const settings = (Array.isArray(raw.settings) ? raw.settings : []) as FeatureSettingField[];
  const tools = (Array.isArray(raw.tools) ? raw.tools : []) as FeatureToolDecl[];
  const permissions = (Array.isArray(raw.permissions) ? raw.permissions : []).map(String);
  const databaseMigrations = (Array.isArray(raw.databaseMigrations) ? raw.databaseMigrations : []) as FeatureMigration[];
  const dependencies = (Array.isArray(raw.dependencies) ? raw.dependencies : []) as FeatureDependency[];
  const featureFlags = (raw.featureFlags && typeof raw.featureFlags === "object" && !Array.isArray(raw.featureFlags))
    ? (raw.featureFlags as Record<string, boolean>)
    : undefined;

  return {
    id: raw.id,
    name: String(raw.name),
    version: String(raw.version),
    description: String(raw.description ?? ""),
    status: (raw.status as FeatureLifecycleState) ?? "discovered",
    minimumAppVersion: raw.minimumAppVersion === undefined ? undefined : String(raw.minimumAppVersion),
    backendModules,
    frontendEntry: raw.frontendEntry === undefined ? undefined : String(raw.frontendEntry),
    navigation: navigation ? { ...navigation, order: typeof navigation.order === "number" ? navigation.order : 100 } : undefined,
    settings,
    tools,
    permissions,
    databaseMigrations,
    dependencies,
    featureFlags,
    healthCheck: raw.healthCheck === undefined ? undefined : String(raw.healthCheck),
    activationRequirements: raw.activationRequirements === undefined ? undefined : (raw.activationRequirements as string[]).map(String),
    source: "bundled",
  };
}
